import { Book } from "@/lib/types";

export const _2samuel: Book = {
  id: "2samuel",
  name: "2. Samuel",
  shortName: "2.Sam",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und es geschah nach dem Tode Sauls*, als David von der Schlacht* gegen Amalek zurückgekommen war, da blieb David zwei Tage in Ziklag*.", heading: "Davids Klage um Saul und Jonatan nach ihrem Tod", footnotes: ["℘ 1Sam 31,4", "w. von dem Schlag", "℘ 1Sam 30,17.26"] },
      { number: 2, text: "Und es geschah am dritten Tag, siehe, da kam ein Mann aus dem Heerlager von Saul her. Seine Kleider waren zerrissen, und Erde war auf seinem Kopf*. Und als er zu David kam, fiel er zur Erde und huldigte ihm*.", footnotes: ["℘ Kap. 13,19; 15,32; Jos 7,6", "w. und warf sich nieder\n℘ Kap. 14,4; 24,20; 1Sam 20,41"] },
      { number: 3, text: "Und David sagte zu ihm: Woher kommst du?* Er sagte zu ihm: Aus dem Heerlager Israels bin ich entkommen.", footnotes: ["℘ 1Sam 30,13"] },
      { number: 4, text: "Und David sagte zu ihm: Wie steht die Sache? Berichte mir doch! Und er sagte: Das Volk ist aus dem Kampf geflohen, auch sind viele von dem Volk gefallen und umgekommen, und auch Saul und sein Sohn Jonatan sind tot." },
      { number: 5, text: "Da sagte David zu dem jungen Mann, der ihm berichtete: Wie hast du erfahren*, dass Saul und sein Sohn Jonatan tot sind?", footnotes: ["o. erkannt"] },
      { number: 6, text: "Der junge Mann, der ihm berichtete, sagte: Ich geriet zufällig* auf das Gebirge Gilboa, und siehe, Saul lehnte sich auf seinen Speer; und siehe, die Wagen und die Reiter* holten ihn ein*.", footnotes: ["℘ Rt 2,3", "w. die Herren der Pferde", "℘ 1Sam 31,3"] },
      { number: 7, text: "Da wandte er sich um, sah mich und rief mich, und ich sagte: Hier bin ich!" },
      { number: 8, text: "Und er sagte zu mir: Wer bist du?* Ich sagte zu ihm: Ich bin ein Amalekiter.", footnotes: ["℘ 1Sam 30,13"] },
      { number: 9, text: "Da sagte er zu mir: Tritt doch her zu mir und gib mir den Todesstoß*, denn ein Schwächeanfall* hat mich ergriffen, doch mein Leben ist noch ganz in mir!", footnotes: ["℘ Ri 9,54", "o. der Todeskrampf"] },
      { number: 10, text: "Da trat ich zu ihm und gab ihm den Todesstoß, denn ich erkannte, dass er nach seinem Fall nicht am Leben bleiben würde. Und ich nahm das Diadem, das er auf seinem Kopf hatte, und die Spange, die an seinem Arm war, und brachte sie hierher zu meinem Herrn." },
      { number: 11, text: "Da fasste David seine Kleider und zerriss sie*; das taten auch all die Männer, die bei ihm waren.", footnotes: ["℘ Kap. 3,31; 2Kö 5,7"] },
      { number: 12, text: "Und sie klagten und weinten und fasteten bis zum Abend* um Saul und um seinen Sohn Jonatan und um das Volk des HERRN und um das Haus Israel, weil sie durchs Schwert gefallen waren*.", footnotes: ["℘ Kap. 3,35; 1Sam 31,13", "℘ 1Sam 31,6"] },
      { number: 13, text: "Und David sagte zu dem jungen Mann, der ihm berichtete: Woher bist du?* Er sagte: Ich bin der Sohn eines amalekitischen Fremdlings*.", footnotes: ["℘ 1Sam 30,13", "o. Schutzbürgers"] },
      { number: 14, text: "Und David sagte zu ihm: Wie, hast du dich nicht gefürchtet, deine Hand auszustrecken, um den Gesalbten des HERRN* umzubringen*?", footnotes: ["℘ 1Sam 24,7", "℘ 1Sam 26,9; Ps 105,15"] },
      { number: 15, text: "Und David rief einen von den jungen Männern und sagte: Tritt heran, stoß ihn nieder! Da erschlug er ihn. So starb er*.", footnotes: ["℘ Kap. 4,10"] },
      { number: 16, text: "Und David sagte zu ihm: Dein Blut komme auf deinen Kopf!* Denn dein eigener Mund hat gegen dich ausgesagt*, als du sprachst: Ich habe den Gesalbten des HERRN getötet.", footnotes: ["℘ Kap. 3,29; 1Sam 25,39", "℘ Lk 19,22"] },
      { number: 17, text: "Und David stimmte dieses Klagelied an* über Saul und über Jonatan, seinen Sohn.", footnotes: ["℘ Kap. 3,33; 2Chr 35,25; Ps 35,14"] },
      { number: 18, text: "Und er befahl*, dass man die Söhne Juda das Lied über den Bogen lehren solle. Siehe, es ist geschrieben im Buch Jaschar*:", footnotes: ["w. sagte", "d. h. des Rechtschaffenen, o. des Aufrichtigen\n℘ Jos 10,13"] },
      { number: 19, text: "Deine* Zierde, Israel, liegt erschlagen auf deinen Höhen! Wie sind die Helden gefallen!", footnotes: ["w. Die Zierde, o. Die Zierde Israels"] },
      { number: 20, text: "Berichtet es nicht in Gat*, verkündet die Botschaft nicht auf den Straßen von Aschkelon*, dass sich nicht freuen die Töchter der Philister, dass nicht jubeln die Töchter der Unbeschnittenen*!", footnotes: ["℘ 1Sam 6,17; Mi 1,10", "℘ 1Sam 30,13", "℘ 1Sam 31,9"] },
      { number: 21, text: "Ihr Berge von Gilboa*, nicht Tau noch Regen falle auf euch, ihr Berge des Todes*! Denn dort wurde besudelt der Schild der Helden, *der Schild Sauls nicht gesalbt mit Öl*.", footnotes: ["℘ 1Sam 31,1.8", "so mit der alten lat. Üs.; Mas. T.: Felder des Hebopfers", "o. Sauls Schild wie der eines mit Öl nicht Gesalbten, 22 vom Blut der Durchbohrten, vom Fett der Helden. Jonatans Bogen wich nie zurück, und Sauls Schwert kehrte nicht erfolglos heim", "℘ Jes 21,5"] },
      { number: 22, text: "Ohne das Blut von Durchbohrten, ohne das Fett der Helden kam Jonatans Bogen nie zurück, und auch Sauls Schwert kehrte nicht erfolglos heim*.", footnotes: ["o. Sauls Schild wie der eines mit Öl nicht Gesalbten, 22 vom Blut der Durchbohrten, vom Fett der Helden. Jonatans Bogen wich nie zurück, und Sauls Schwert kehrte nicht erfolglos heim\n℘ 1Sam 14,47.48; Jer 50,9"] },
      { number: 23, text: "Saul und Jonatan, die Geliebten und Liebenswerten, in ihrem Leben und in ihrem Tod sind sie ungetrennt; sie waren schneller als Adler, stärker als Löwen*.", footnotes: ["℘ Spr 30,30"] },
      { number: 24, text: "Ihr Töchter Israels, weint um Saul, der euch köstlich kleidete in Karmesin*, der goldenen Schmuck an eure Kleider heftete!", footnotes: ["w. der euch kleidete in Karmesin mit Köstlichkeiten o. mit Schmuckstücken"] },
      { number: 25, text: "Wie sind die Helden gefallen mitten im Kampf! Jonatan liegt durchbohrt auf deinen Höhen." },
      { number: 26, text: "Mir ist weh um dich, mein Bruder Jonatan! Über alles lieb warst du mir*. Wunderbar war mir deine Liebe, mehr als Frauenliebe*.", footnotes: ["w. Du warst mir sehr lieblich", "℘ 1Sam 18,1.3; Spr 18,24"] },
      { number: 27, text: "Wie sind die Helden gefallen, verloren gegangen die Waffen der Schlacht!" },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und es geschah danach, da befragte David den HERRN*: Soll ich in eine der Städte Judas hinaufziehen? Und der HERR sprach zu ihm: Zieh hinauf! Und David sagte: Wohin soll ich hinaufziehen? Und er sprach: Nach Hebron*!", heading: "David wird König über Juda, Isch-Boschet über Israel", footnotes: ["℘ Kap. 5,19.23; 1Sam 10,22", "℘ 1Mo 13,18; Jos 15,13; 2Chr 11,10"] },
      { number: 2, text: "Da zog David dort hinauf und auch seine beiden Frauen, Ahinoam, die Jesreeliterin, und Abigajil, die Frau Nabals, des Karmeliters*.", footnotes: ["℘ Kap. 3,3; 1Sam 25,42.43"] },
      { number: 3, text: "Auch seine Männer, die bei ihm waren*, ließ David hinaufziehen, jeden mit seinem Haus; und sie ließen sich in den Städten Hebrons nieder.", footnotes: ["℘ 1Chr 12,1-23"] },
      { number: 4, text: "Und die Männer von Juda* kamen und salbten David dort zum König über das Haus Juda*. Und man berichtete David: Die Männer von Jabesch in Gilead sind es, die Saul begraben haben.", footnotes: ["℘ Kap. 19,42", "℘ Kap. 5,3.5; 2Kö 11,12; Mt 1,5"] },
      { number: 5, text: "Da sandte David Boten zu den Männern von Jabesch in Gilead* und ließ ihnen sagen: Gesegnet sollt ihr sein von dem HERRN*, dass ihr diese Güte* an eurem Herrn, an Saul, erwiesen und ihn begraben habt*!", footnotes: ["℘ 1Sam 11,1", "℘ 1Mo 14,19; Rt 2,20", "o. Gnade", "℘ Kap. 21,12"] },
      { number: 6, text: "So erweise nun der HERR Güte* und Treue an euch*! Und auch ich will euch dieses Gute vergelten*, weil ihr das* getan habt*.", footnotes: ["o. Gnade", "℘ Kap. 15,20; Jos 2,14; Rt 1,8", "w. erweisen", "w. diese Sache", "℘ 2Tim 1,16"] },
      { number: 7, text: "Und nun lasst eure Hände erstarken und seid tapfere Männer! Denn Saul, euer Herr, ist tot. Auch hat mich das Haus Juda zum König über sich gesalbt*.", footnotes: ["℘ Kap. 5,3.5; 2Kö 11,12; Mt 1,5"] },
      { number: 8, text: "Abner aber, der Sohn des Ner, der Heeroberste Sauls*, nahm Isch-Boschet*, den Sohn Sauls, und brachte ihn hinüber nach Mahanajim*.", footnotes: ["℘ 1Sam 14,50", "Der Name lautet in 1Chr 8,33 und in 9,39 Eschbaal, in 1Sam 14,49 Jischwi.\n℘ Kap. 3,7; 1Chr 8,33", "℘ V. 29; Kap. 17,24; 1Mo 32,3"] },
      { number: 9, text: "Und er machte ihn zum König über Gilead* und über die Asseriter*, über Jesreel*, über Ephraim*, über Benjamin* und über ganz Israel*.", footnotes: ["℘ Jos 17,1", "so mit aram. Üs.; gemeint sind die Angehörigen des Stammes Asser; Mas. T.: die Assuriter", "℘ Jos 19,18", "℘ Jos 16,5-9", "℘ Jos 18,11-28", "℘ 1Chr 12,30"] },
      { number: 10, text: "Vierzig Jahre war Isch-Boschet*, der Sohn Sauls, alt, als er über Israel König wurde, und er war zwei Jahre König; nur* das Haus Juda stand hinter David.", footnotes: ["Der Name lautet in 1Chr 8,33 und in 9,39 Eschbaal, in 1Sam 14,49 Jischwi.", "o. jedoch"] },
      { number: 11, text: "Und die Zahl der Tage, die David in Hebron über das Haus Juda König war, betrug sieben Jahre und sechs Monate*.", footnotes: ["℘ Kap. 5,5"] },
      { number: 12, text: "Und Abner, der Sohn des Ner, zog aus mit den Knechten Isch-Boschets*, des Sohnes Sauls, von Mahanajim nach Gibeon*.", heading: "Streit zwischen dem Haus Davids und dem Haus Sauls — Joab und Abner", footnotes: ["Der Name lautet in 1Chr 8,33 und in 9,39 Eschbaal, in 1Sam 14,49 Jischwi.", "℘ Jos 9,3"] },
      { number: 13, text: "Und Joab, der Sohn der Zeruja*, und Davids Knechte zogen aus. Und sie stießen beim Teich von Gibeon aufeinander. Und sie ließen sich dort nieder, die einen auf dieser Seite des Teiches und die anderen auf jener Seite des Teiches*.", footnotes: ["℘ Kap. 23,24; 1Sam 26,6; 1Chr 2,16; 27,7", "℘ Jer 41,12"] },
      { number: 14, text: "Da sagte Abner zu Joab: Lass doch die jungen Männer sich aufmachen und vor uns zum Kampfspiel antreten*! Und Joab sagte: Sollen sie sich aufmachen!", footnotes: ["w. und vor uns spielen"] },
      { number: 15, text: "So machten sie sich denn auf und gingen hinüber, abgezählt: zwölf für Benjamin und für Isch-Boschet, den Sohn Sauls, und zwölf von den Knechten Davids." },
      { number: 16, text: "Und sie ergriffen einer den andern beim Kopf, und jeder stieß sein Schwert dem andern in die Seite, und sie fielen miteinander. Und man nannte jenen Ort Helkat-Hazzurim*; der liegt bei Gibeon.", footnotes: ["d. h. Feld der Felsen; wahrscheinlich verschrieben aus: Feld der Seiten (hebr. ziddim)"] },
      { number: 17, text: "Und der Kampf wurde überaus heftig* an diesem Tag. Abner aber und die Männer von Israel wurden vor den Knechten Davids geschlagen*.", footnotes: ["℘ Spr 17,14", "℘ Kap. 3,1.6"] },
      { number: 18, text: "Nun waren dort die drei Söhne der Zeruja: Joab und Abischai und Asaël*. Asaël aber war schnell auf seinen Füßen wie eine der Gazellen, die auf dem freien Feld leben*.", footnotes: ["℘ Kap. 23,24; 1Sam 26,6; 1Chr 2,16; 27,7", "℘ 1Chr 12,9"] },
      { number: 19, text: "Und Asaël jagte Abner nach und bog bei der Verfolgung Abners nicht ab, weder zur Rechten noch zur Linken." },
      { number: 20, text: "Da wandte Abner sich um und sagte: Bist du es, Asaël? Und er sagte: Ich bin es." },
      { number: 21, text: "Da sagte Abner zu ihm: Bieg ab vom Weg zu deiner Rechten oder zu deiner Linken und greif dir einen von den jungen Männern und nimm dir seine Rüstung! Aber Asaël wollte nicht von ihm weichen." },
      { number: 22, text: "Da sagte Abner noch einmal zu Asaël: Weiche von mir! Warum soll ich dich zu Boden schlagen? Wie könnte ich mein Gesicht zu deinem Bruder Joab erheben?" },
      { number: 23, text: "Aber er weigerte sich zu weichen. Da stieß ihn Abner mit dem hinteren Ende des Speeres in den Bauch*, so dass der Speer hinten herausdrang; und er fiel dort und starb an ebendieser Stelle. Und es geschah, jeder, der an die Stelle kam, wo Asaël gefallen und gestorben war, der blieb stehen*.", footnotes: ["℘ Kap. 3,27; 4,6; 20,10", "℘ Kap. 20,12"] },
      { number: 24, text: "Joab und Abischai aber jagten Abner nach. Die Sonne ging gerade unter, als sie zum Hügel Amma kamen, der vor Giach liegt auf dem Weg zur Steppe von Gibeon." },
      { number: 25, text: "Und die Söhne Benjamin sammelten sich hinter Abner, bildeten einen geschlossenen Haufen und stellten sich auf den Gipfel eines alleinstehenden Hügels*.", footnotes: ["w. eines Hügels; »eines« ist Zahlwort; andere lesen mit leichter Änderung des Zahlwortes: auf den Gipfel des Hügels Amma"] },
      { number: 26, text: "Und Abner rief Joab zu und sagte: Soll denn das Schwert immerfort fressen? Weißt du nicht, dass zuletzt Erbitterung entstehen wird? Wie lange willst du dem Volk nicht sagen, dass es von der Verfolgung seiner Brüder umkehren soll?" },
      { number: 27, text: "Da sagte Joab: So wahr Gott lebt, wenn du nicht geredet hättest, dann hätte sich schon heute Morgen* das Volk zurückgezogen, jeder von seinem Bruder!", footnotes: ["w. vom Morgen an. — Andere üs.: dann hätte sich erst vom Morgen an"] },
      { number: 28, text: "Darauf stieß Joab ins Horn, und das ganze Volk machte halt. Sie jagten Israel nicht länger nach und kämpften nicht mehr weiter*.", footnotes: ["℘ Kap. 18,16"] },
      { number: 29, text: "Und Abner und seine Männer zogen jene ganze Nacht durch die Jordanebene* und setzten über den Jordan und durchzogen das ganze Bitron* und kamen nach Mahanajim.", footnotes: ["hebr. Araba; vgl. Anm. zu 5Mo 1,1", "o. die ganze Schlucht"] },
      { number: 30, text: "Joab aber kehrte von der Verfolgung Abners zurück und sammelte das ganze Volk. Da wurden von den Knechten Davids neunzehn Mann vermisst und Asaël." },
      { number: 31, text: "Die Knechte Davids aber hatten von Benjamin und unter den Männern Abners viele erschlagen; 360 Mann waren tot." },
      { number: 32, text: "Und sie hoben Asaël auf und begruben ihn im Grab seines Vaters in Bethlehem. Und Joab und seine Männer gingen die ganze Nacht, und es wurde hell*, als sie in Hebron ankamen.", footnotes: ["w. es wurde ihnen hell"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*Und der Kampf währte lange zwischen dem Haus Sauls und dem Haus Davids*. David aber wurde immer stärker*, während das Haus Sauls immer schwächer* wurde.", heading: "Davids Frauen und Söhne in Hebron", footnotes: ["℘ 1Chr 3,1-4", "℘ V. 6; Kap. 2,17", "℘ Kap. 5,10; 22,44; Hi 17,9", "o. geringer"] },
      { number: 2, text: "Und es wurden David in Hebron Söhne geboren: Sein Erstgeborener war Amnon*, von Ahinoam, der Jesreeliterin,", footnotes: ["℘ Kap. 13,1"] },
      { number: 3, text: "und sein zweiter Kilab, von Abigajil, der Frau des Karmeliters Nabal*, und der dritte Absalom*, der Sohn der Maacha, der Tochter Talmais, des Königs von Geschur*,", footnotes: ["℘ Kap. 2,2; 1Sam 25,42.43", "℘ Kap. 13,1", "℘ Kap. 13,37; 14,23; Jos 13,13"] },
      { number: 4, text: "und der vierte Adonija*, der Sohn der Haggit, und der fünfte Schefatja, der Sohn der Abital,", footnotes: ["℘ 1Kö 1,5"] },
      { number: 5, text: "und der sechste Jitream, von Egla, der Frau Davids. Diese wurden David in Hebron geboren*.", footnotes: ["℘ Ps 127,3"] },
      { number: 6, text: "Und es geschah, solange zwischen dem Haus Sauls und dem Haus Davids Krieg war*, stand Abner* dem Haus Sauls mutig bei*.", heading: "Abner tritt auf Davids Seite — Joabs Mord an Abner — Davids Klage um Abner", footnotes: ["℘ V. 1", "℘ 1Sam 14,50", "o. hielt Abner fest zum Haus Sauls"] },
      { number: 7, text: "Und Saul hatte eine Nebenfrau, ihr Name war Rizpa, eine Tochter des Aja*. Und Isch-Boschet* sagte zu Abner: Warum bist du zu der Nebenfrau meines Vaters eingegangen?", footnotes: ["℘ Kap. 21,8", "w. er\n℘ Kap. 2,8"] },
      { number: 8, text: "Da wurde Abner sehr zornig über die Worte Isch-Boschets und sagte: Bin ich ein Hundskopf*, der zu Juda hält*? Bis heute erweise ich Güte* am Haus deines Vaters Saul, an seinen Brüdern und an seinen Freunden, und ich habe dich nicht in die Hand Davids geraten lassen, und jetzt ziehst du mich wegen des Vergehens mit der Frau zur Rechenschaft?", footnotes: ["℘ Kap. 9,8; 16,9; 1Sam 17,43", "o. gehört", "o. Gnade"] },
      { number: 9, text: "So möge Gott Abner tun und so ihm hinzufügen!* Ja, wie der HERR dem David geschworen hat, so werde ich ihm tun*:", footnotes: ["℘ V. 35; Kap. 19,14; 1Sam 3,17; 1Kö 2,23", "℘ Ps 89,36.37"] },
      { number: 10, text: "das Königtum vom Haus Sauls wegnehmen und den Thron Davids aufrichten über Israel und über Juda*, von Dan bis Beerscheba*!", footnotes: ["℘ 1Sam 15,28; 28,17", "℘ Kap. 17,11; 24,2; Ri 20,1"] },
      { number: 11, text: "Und er konnte Abner kein Wort mehr erwidern, weil er ihn fürchtete." },
      { number: 12, text: "Und Abner sandte Boten für sich* zu David und ließ ihm sagen: Wem gehört das Land? Und weiter: Schließ deinen Bund mit mir! Siehe, meine Hand wird mit dir sein, um dir ganz Israel zuzuwenden.", footnotes: ["o. an seiner Stelle"] },
      { number: 13, text: "Und David* sagte: Gut, ich will einen Bund mit dir schließen. Nur eine Sache fordere ich von dir, nämlich: Du sollst mein Angesicht nicht sehen, es sei denn, du bringst mir vorher Michal*, die Tochter Sauls, wenn du kommst, um mein Angesicht zu sehen.", footnotes: ["w. er", "℘ 1Sam 18,27"] },
      { number: 14, text: "Und David sandte Boten zu Isch-Boschet, dem Sohn Sauls, und ließ ihm sagen: Gib mir Michal, meine Frau, die ich mir verlobt habe für hundert Vorhäute der Philister!" },
      { number: 15, text: "Da sandte Isch-Boschet hin und ließ sie von ihrem Mann wegholen, von Paltiel, dem Sohn des Lajisch*.", footnotes: ["℘ 1Sam 25,44"] },
      { number: 16, text: "Und ihr Mann ging mit ihr, und laut weinend ging er hinter ihr her bis Bahurim*. Da sagte Abner zu ihm: Geh, kehre um! Und er kehrte um.", footnotes: ["℘ Kap. 16,5; 17,18; 19,17"] },
      { number: 17, text: "Und Abner hatte eine Unterredung mit den Ältesten Israels gehabt und gesagt: Früher schon* habt ihr David zum König über euch verlangt.", footnotes: ["w. Schon gestern und schon vorgestern"] },
      { number: 18, text: "So handelt jetzt! Denn der HERR hat zu David geredet: Durch die Hand meines Knechtes David will ich mein Volk Israel retten aus der Hand der Philister und aus der Hand aller seiner Feinde." },
      { number: 19, text: "So redete Abner auch zu den Ohren Benjamins*. Dann ging Abner auch hin, um zu den Ohren Davids in Hebron alles zu reden, was gut war in den Augen Israels und in den Augen des ganzen Hauses Benjamin.", footnotes: ["℘ 1Chr 12,30"] },
      { number: 20, text: "Als nun Abner zu David nach Hebron kam und mit ihm zwanzig Männer, bereitete David Abner und den Männern, die bei ihm waren, ein Mahl*.", footnotes: ["℘ 1Sam 25,36"] },
      { number: 21, text: "Und Abner sagte zu David: Ich will mich aufmachen und hingehen und ganz Israel zu meinem Herrn, dem König, versammeln, damit sie einen Bund mit dir schließen und du über alles König bist, was deine Seele begehrt. Und David entließ Abner, und er ging hin in Frieden." },
      { number: 22, text: "Und siehe, die Knechte Davids und Joab kamen von einem Streifzug und brachten viel Beute mit sich. Abner war aber nicht mehr bei David in Hebron. Denn er hatte ihn entlassen, und er war in Frieden weggegangen." },
      { number: 23, text: "Als nun Joab und das ganze Heer, das bei ihm war, ankamen, da berichtete man Joab: Abner, der Sohn des Ner, ist zum König gekommen. Und der hat ihn entlassen, und er ist in Frieden weggegangen." },
      { number: 24, text: "Da kam Joab zum König und sagte: Was hast du getan!* Siehe, Abner ist zu dir gekommen! Warum denn hast du ihn entlassen, so dass er ungehindert weggegangen ist?", footnotes: ["℘ 1Mo 12,18"] },
      { number: 25, text: "Du kennst doch Abner, den Sohn des Ner, dass er gekommen ist, um dich zu beschwatzen und um dein Gehen und dein Kommen zu erfahren und alles zu erfahren, was du tust*.", footnotes: ["℘ Kap. 10,3"] },
      { number: 26, text: "Und Joab ging von David hinaus und sandte Abner Boten nach. Die holten ihn zurück von der Zisterne Sira. David aber wusste* nichts davon.", footnotes: ["o. erkannte"] },
      { number: 27, text: "Als nun Abner nach Hebron zurückkam, führte ihn Joab beiseite in das Tor, um in der Stille mit ihm zu reden. Dort stach er ihn in den Bauch*, so dass er starb* — um des Blutes seines Bruders Asaël willen*.", footnotes: ["℘ Kap. 2,23", "℘ Kap. 20,10; 1Kö 2,5", "℘ Kap. 2,19-23; 4Mo 35,19"] },
      { number: 28, text: "Als David nachher davon hörte, sagte er: Schuldlos bin ich und mein Königtum vor dem HERRN auf ewig an dem Blut Abners, des Sohnes Ners!" },
      { number: 29, text: "Es wende sich gegen das Haupt Joabs* und gegen* das ganze Haus seines Vaters! Und nie soll im Haus Joabs der fehlen, der an Ausfluss leidet* und der Aussatz hat, der, der nach der Krücke fasst*, und der, der durchs Schwert fällt, und der, dem es an Brot fehlt*! —", footnotes: ["℘ Kap. 1,16; 4Mo 35,33; 1Kö 2,32", "o. Es breche herein über das Haupt Joabs und über", "s. Anm. zu 3Mo 15,2\n℘ 3Mo 15,2.3", "so mit LXX; Mas. T.: der nach der Spindel fasst", "℘ Ps 7,17; 109,10"] },
      { number: 30, text: "So haben Joab und sein Bruder Abischai Abner erschlagen, weil er ihren Bruder Asaël bei Gibeon im Kampf getötet hatte.*", footnotes: ["℘ Kap. 2,19-23; 4Mo 35,19"] },
      { number: 31, text: "Und David sagte zu Joab und zu all dem Volk, das bei ihm war: Zerreißt eure Kleider* und gürtet euch mit Sacktuch und haltet Totenklage vor Abner her! Und der König David ging hinter der Bahre her.", footnotes: ["℘ Kap. 1,11"] },
      { number: 32, text: "Und sie begruben Abner in Hebron*. Und der König erhob seine Stimme und weinte an Abners Grab, und das ganze Volk weinte.", footnotes: ["℘ Kap. 4,12"] },
      { number: 33, text: "Und der König stimmte ein Klagelied über Abner an* und sprach: Musste, wie ein Gottloser* stirbt, Abner sterben?", footnotes: ["℘ Kap. 1,17", "o. Unverständiger; o. Tor"] },
      { number: 34, text: "Deine Hände waren nicht gebunden, und deine Füße nicht in bronzene Fesseln gelegt*. Wie man vor Verbrechern* fällt, so bist du gefallen! Da weinte alles Volk noch mehr über ihn.", footnotes: ["w. nicht mit bronzenen Doppelfesseln in Berührung gebracht worden", "w. vor Söhnen der Verkehrtheit"] },
      { number: 35, text: "Und alles Volk kam, um David Brot zu reichen, während es noch Tag war. Aber David schwor und sprach: So soll mir Gott tun und so hinzufügen, wenn ich vor dem Untergang der Sonne Brot oder sonst irgendetwas genieße*!", footnotes: ["℘ Kap. 1,12; 12,17; Ri 20,26"] },
      { number: 36, text: "Und alles Volk nahm es wahr. Und es war gut in ihren Augen, wie alles, was der König tat, in den Augen des ganzen Volkes gut war." },
      { number: 37, text: "Und das ganze Volk und ganz Israel erkannten an diesem Tag, dass es nicht vom König ausgegangen war, Abner, den Sohn des Ner, zu töten." },
      { number: 38, text: "Und der König sagte zu seinen Knechten: Erkennt ihr nicht, dass an diesem Tag ein Oberster und Großer in Israel gefallen ist*?", footnotes: ["℘ 1Sam 26,15"] },
      { number: 39, text: "Ich aber bin, obwohl zum König gesalbt, heute noch schwach, während diese Männer, die Söhne der Zeruja, härter sind als ich. Der HERR vergelte dem, der das Böse tut, nach seiner Bosheit!*", footnotes: ["℘ 4Mo 32,23; Ri 9,57; 1Kö 2,6.33; Ps 28,4; 62,13; 2Tim 4,14"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und als der Sohn Sauls hörte, dass Abner in Hebron gestorben war, da wurden seine Hände schlaff, und ganz Israel war bestürzt.", heading: "Ermordung Isch-Boschets — Bestrafung der Mörder durch David" },
      { number: 2, text: "Nun hatte der Sohn Sauls zwei Männer als Oberste der Streifscharen, der Name des einen war Baana und der Name des anderen Rechab, Söhne Rimmons, des Beerotiters, von den Söhnen Benjamin. Denn auch Beerot* wird zu Benjamin gerechnet.", footnotes: ["℘ Kap. 23,37; Jos 18,25"] },
      { number: 3, text: "Die Beerotiter aber waren nach Gittajim* geflohen und sind dort als Fremde* wohnen geblieben bis auf diesen Tag.", footnotes: ["℘ Neh 11,33", "o. als Schutzbürger"] },
      { number: 4, text: "Und Jonatan, der Sohn Sauls, hatte einen an beiden Füßen gelähmten* Sohn. Er war fünf Jahre alt, als die Nachricht von Saul und Jonatan aus Jesreel kam; da hatte ihn seine Amme aufgenommen und war geflohen. Und es geschah, als sie hastig floh, dass er hinfiel und gelähmt wurde. Und sein Name war Mefi-Boschet*.", footnotes: ["w. geschlagenen", "℘ Kap. 9,3; 1Chr 8,34"] },
      { number: 5, text: "Und die Söhne Rimmons, des Beerotiters, Rechab und Baana, gingen hin und kamen bei der Hitze des Tages in das Haus Isch-Boschets; der hatte sich zur Mittagsruhe hingelegt." },
      { number: 6, text: "*Und die beiden kamen bis ins Innere des Hauses, als wollten sie Weizen holen, und stachen ihn in den Bauch*. Und Rechab und sein Bruder Baana entkamen*.", footnotes: ["Andere üs. mit LXX: Und siehe, die Pförtnerin des Hauses hatte Weizen gereinigt, war dabei eingenickt und schlief. So konnten sich die Brüder Rechab und Baana einschleichen. 7 Und sie kamen ins Haus", "℘ Kap. 2,23", "℘ Ri 3,26"] },
      { number: 7, text: "Sie waren nämlich ins Haus gekommen*, während er in seinem Schlafgemach auf seinem Bett lag; da schlugen sie ihn tot und hieben ihm den Kopf ab*. Und sie nahmen seinen Kopf und gingen den Weg durch die Jordanebene* die ganze Nacht hindurch.", footnotes: ["Andere üs. mit LXX: Und siehe, die Pförtnerin des Hauses hatte Weizen gereinigt, war dabei eingenickt und schlief. So konnten sich die Brüder Rechab und Baana einschleichen. 7 Und sie kamen ins Haus", "℘ 1Sam 17,51", "s. Anm. zu 5Mo 1,1"] },
      { number: 8, text: "Und sie brachten Isch-Boschets Kopf zu David nach Hebron und sagten zum König: Siehe da, der Kopf Isch-Boschets, des Sohnes Sauls, deines Feindes, der nach deinem Leben trachtete*! So hat der HERR meinem Herrn, dem König, an diesem Tag Rache verschafft an Saul und seinen Nachkommen*.", footnotes: ["℘ 1Sam 19,1", "w. und seinem Samen"] },
      { number: 9, text: "Da antwortete David dem Rechab und seinem Bruder Baana, den Söhnen Rimmons, des Beerotiters, und sagte zu ihnen: So wahr der HERR lebt, der meine Seele aus jeder Not errettet hat*,", footnotes: ["℘ 1Mo 48,16; 1Sam 26,24"] },
      { number: 10, text: "den, der mir berichtete: Siehe, Saul ist tot! — und der in seinen Augen ein guter Bote war, den ergriff ich und brachte ihn um in Ziklag, dem ich doch Lohn für gute Botschaft hätte geben sollen*.", footnotes: ["Andere üs. mit Textänderung: um ihm so Botenlohn zu geben\n℘ Kap. 1,15.16"] },
      { number: 11, text: "Wie viel mehr, da gottlose Männer einen gerechten Mann in seinem Haus auf seinem Lager umgebracht haben, sollte ich jetzt nicht sein Blut von eurer Hand fordern und euch ausrotten* von der Erde*?", footnotes: ["o. wegfegen", "℘ 1Mo 9,6"] },
      { number: 12, text: "Und David gab seinen Dienern Befehl, und sie erschlugen sie und hieben ihnen die Hände und die Füße ab und hängten sie am Teich von Hebron auf. Isch-Boschets Kopf aber nahmen sie und begruben ihn im Grab Abners zu Hebron*.", footnotes: ["℘ Kap. 3,32; 5Mo 21,22.23"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Und alle Stämme Israels kamen zu David nach Hebron. Und sie sagten: Siehe, wir sind dein Gebein und dein Fleisch*.", heading: "David wird König über ganz Israel — Davids Haus, seine Frauen und Söhne in Jerusalem", footnotes: ["℘ V. 1-5: 1Chr 11,1-3; 12,24-41", "℘ Kap. 19,13; 1Mo 29,14; 5Mo 17,15"] },
      { number: 2, text: "Schon früher*, als Saul König über uns war, bist du es gewesen, der Israel ins Feld hinausführte und wieder heimbrachte*. Und der HERR hat zu dir gesprochen: Du sollst mein Volk Israel weiden, und du sollst Fürst sein über Israel!*", footnotes: ["w. Schon gestern und schon vorgestern", "℘ 1Sam 18,16", "℘ Kap. 6,21; 7,8; 1Sam 13,14; Mt 2,6"] },
      { number: 3, text: "Und alle Ältesten Israels kamen zum König nach Hebron, und der König David schloss vor dem HERRN einen Bund mit ihnen in Hebron*. Und sie salbten David zum König* über Israel.*", footnotes: ["℘ 2Kö 11,17", "℘ Kap. 2,4", "℘ 1Chr 28,4"] },
      { number: 4, text: "Dreißig Jahre war David alt*, als er König wurde; vierzig Jahre lang war er König.", footnotes: ["℘ 1Mo 41,46"] },
      { number: 5, text: "In Hebron war er sieben Jahre und sechs Monate König über Juda, und in Jerusalem war er 33 Jahre König über ganz Israel und Juda.*", footnotes: ["℘ Kap. 2,11; 12,8; 1Kö 2,11; 1Chr 3,4"] },
      { number: 6, text: "*Und der König zog mit seinen Männern nach Jerusalem gegen die Jebusiter*, die Bewohner des Landes. Und sie sagten zu David: Du wirst nicht hier hereinkommen, *sondern die Blinden und die Lahmen werden dich wegtreiben*. Sie wollten damit sagen: David wird nicht hier hereinkommen.", footnotes: ["℘ V. 6-10: 1Chr 11,4-9", "℘ Jos 15,63", "o. es sei denn, du vertreibst auch noch die Blinden und die Lahmen", "o. es sei denn, du vertreibst auch noch die Blinden und die Lahmen"] },
      { number: 7, text: "Aber David nahm die Bergfeste Zion* ein, das ist die Stadt Davids*.", footnotes: ["℘ Ps 48,3", "℘ Kap. 6,10; 1Kö 2,10; Neh 3,15"] },
      { number: 8, text: "Und zwar sagte David an jenem Tag: Wer die Jebusiter schlägt und in den Wasserschacht* gelangt und die Lahmen und Blinden erschlägt, die der Seele Davids verhasst sind . . .*! Daher sagt man: Ein Blinder und ein Lahmer dürfen nicht ins Haus kommen.", footnotes: ["w. in den Wasserstrahl. — Vielleicht ist damit der Tunnel gemeint, der durch den alten Hügel von Jerusalem zur Gihonquelle führte (1Kö 1,33f). Durch ihn konnten Mutige hinaufsteigen und in die Stadt gelangen.", "An dieser Stelle muss ein Satz ausgefallen sein, der nach 1Chr 11,6 gelautet haben könnte: der soll Haupt und Oberster werden."] },
      { number: 9, text: "Und David wohnte in der Bergfeste und nannte sie Stadt Davids*. Und David baute ringsum vom Millo* an nach innen zu. —", footnotes: ["℘ Kap. 6,10; 1Kö 2,10; Neh 3,15", "d. h. Aufschüttung; der Millo diente zur Befestigung der Stadt\n℘ Ri 9,6; 1Kö 9,15; 2Kö 12,21; 2Chr 32,5"] },
      { number: 10, text: "Und David wurde immer mächtiger*, und der HERR, der Gott der Heerscharen, war mit ihm*.", footnotes: ["℘ Kap. 3,1", "℘ Kap. 7,9; 8,6.14; 1Sam 18,12.14"] },
      { number: 11, text: "*Und Hiram, der König von Tyrus*, sandte Boten zu David und Zedernholz und Zimmerleute und Mauerleute; die bauten David ein Haus*.", footnotes: ["℘ V. 11-16: 1Chr 14,1-7", "℘ Jos 19,29", "℘ Kap. 7,2; 1Kö 5,15-20"] },
      { number: 12, text: "Und David erkannte, dass der HERR ihn als König über Israel eingesetzt und dass er sein Königtum wegen seines Volkes Israel erhöht hatte*.", footnotes: ["℘ 4Mo 24,7; 1Kö 10,9"] },
      { number: 13, text: "Und David nahm noch Nebenfrauen und Frauen aus Jerusalem*, nachdem er von Hebron gekommen war; und es wurden David noch mehr Söhne und Töchter geboren.", footnotes: ["℘ 5Mo 17,17"] },
      { number: 14, text: "*Und dies sind die Namen derer, die ihm in Jerusalem geboren wurden: Schammua und Schobab und Nathan* und Salomo*", footnotes: ["℘ V. 14-16: 1Chr 3,5-9", "℘ 1Kö 4,5; Sach 12,12; Lk 3,31", "℘ Kap. 12,24.25; Mt 1,6"] },
      { number: 15, text: "und Jibhar und Elischua und Nefeg und Jafia" },
      { number: 16, text: "und Elischama und Eljada und Elifelet." },
      { number: 17, text: "*Und als die Philister hörten, dass man David zum König über Israel gesalbt hatte, da zogen alle Philister herauf, um David zu suchen*. Und David hörte es und zog in die Bergfeste hinab*.", heading: "Davids Siege über die Philister", footnotes: ["℘ 1Chr 14,8-17", "o. um David herauszufordern", "℘ Kap. 23,14"] },
      { number: 18, text: "Und die Philister waren gekommen und hatten sich in der Ebene Refaïm* ausgebreitet.", footnotes: ["℘ Kap. 23,13; Jos 15,8"] },
      { number: 19, text: "Da befragte David den HERRN*: Soll ich gegen die Philister hinaufziehen? Wirst du sie in meine Hand geben? Und der HERR sprach zu David: Zieh hinauf! Denn ich werde die Philister gewiss in deine Hand geben*.", footnotes: ["℘ Kap. 2,1", "℘ 1Sam 30,8"] },
      { number: 20, text: "Da kam David nach Baal-Perazim*, und David schlug sie dort. Und er sagte: Durchbrochen* hat der HERR meine Feinde vor mir, wie ein Wasserdurchbruch. Daher gab er jenem Ort den Namen Baal-Perazim*.", footnotes: ["℘ Jes 28,21", "hebr. paraz", "d. h. Herr der Durchbrüche"] },
      { number: 21, text: "Und sie ließen dort ihre Götzen zurück, und David und seine Männer nahmen sie mit*.", footnotes: ["℘ Jes 46,2; Jer 48,7; Dan 11,8"] },
      { number: 22, text: "Und die Philister zogen noch einmal herauf* und breiteten sich in der Ebene Refaïm* aus.", footnotes: ["℘ Kap. 21,15", "℘ Kap. 23,13; Jos 15,8"] },
      { number: 23, text: "Und David befragte den HERRN*; der aber sprach: Du sollst nicht hinaufziehen! Wende dich und fall ihnen in den Rücken, dass du von der Seite der Bakabäume an sie herankommst!", footnotes: ["℘ Kap. 2,1"] },
      { number: 24, text: "Und sobald du das Geräusch eines Daherschreitens in den Wipfeln der Bakabäume hörst, dann beeile dich! Denn dann ist der HERR vor dir ausgezogen*, um das Heerlager der Philister zu schlagen.", footnotes: ["℘ Ri 4,14"] },
      { number: 25, text: "Da machte David es so, wie der HERR ihm geboten hatte*. Und er schlug die Philister* von Gibeon* an*, bis man nach Geser* kommt.", footnotes: ["℘ 2Mo 12,28", "℘ Kap. 8,1", "℘ Jos 18,24", "so mit LXX und 1Chr 14,16; Mas. T.: von Geba an", "℘ Jos 10,33"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Und David versammelte wieder alle Auserlesenen in Israel, 30 000 Mann.", heading: "Einholung der Bundeslade nach Jerusalem", footnotes: ["℘ V. 1-11: 1Chr 13"] },
      { number: 2, text: "Und David machte sich auf und zog hin mit dem ganzen Volk, das bei ihm war, nach Baala* in Juda*, um von dort die Lade Gottes heraufzuholen*, über die der Name des HERRN, der Name des HERRN der Heerscharen, der über den Cherubim thront*, ausgerufen worden ist.", footnotes: ["so mit Angleichung an 1Chr 13,6; Mas. T.: von Baale", "℘ Jos 15,9", "℘ 1Sam 6,21", "℘ 2Mo 25,22"] },
      { number: 3, text: "Und sie stellten die Lade Gottes auf einen neuen Wagen*. So brachte man sie aus dem Haus Abinadabs, das auf dem Hügel war*. Usa aber und Achjo, die Söhne Abinadabs, führten den neuen Wagen.", footnotes: ["℘ 4Mo 7,9; 1Sam 6,7", "℘ 1Sam 7,1"] },
      { number: 4, text: "Und sie trugen sie aus dem Haus Abinadabs weg, das auf dem Hügel war; Usa ging neben der Lade Gottes, während Achjo vor der Lade herging." },
      { number: 5, text: "Und David und das ganze Haus Israel tanzten vor dem HERRN mit allerlei Instrumenten aus Wacholderhölzern*, mit Zithern und mit Harfen und mit Tamburinen und mit Rasseln und mit Zimbeln*.", footnotes: ["Vielleicht ist mit 1Chr 13,8 zu lesen: mit aller Kraft, mit Liedern", "℘ Ps 150,3-5"] },
      { number: 6, text: "Und als sie zur Tenne Nachons kamen, da streckte Usa seine Hand nach der Lade Gottes aus und fasste sie an, denn die Rinder hatten sich losgerissen*.", footnotes: ["o. wollten den Wagen umwerfen"] },
      { number: 7, text: "Da entbrannte der Zorn des HERRN gegen Usa, und Gott schlug ihn dort wegen der Unehrerbietigkeit. Und er starb dort bei der Lade Gottes*.", footnotes: ["℘ 4Mo 1,51; 1Sam 6,19"] },
      { number: 8, text: "Und es wurde David heiß vor Schrecken* darüber, dass der HERR den Usa so weggerissen hatte*. Und man nannte diesen Ort Perez-Usa*; so heißt er bis auf diesen Tag*.", footnotes: ["o. Und David entbrannte", "w. an Usa einen Riss gerissen hatte", "d. h. Riss Usas", "℘ 1Chr 15,13"] },
      { number: 9, text: "Und David fürchtete sich an diesem Tag vor dem HERRN und sagte: Wie soll die Lade des HERRN zu mir kommen*?", footnotes: ["℘ 1Sam 6,20; Ps 119,120"] },
      { number: 10, text: "Und David wollte die Lade des HERRN nicht zu sich in die Stadt Davids bringen lassen*. Und David ließ sie beiseite schaffen in das Haus Obed-Edoms*, des Gatiters*.", footnotes: ["℘ Kap. 5,7.9", "℘ 1Chr 15,18.24", "℘ Jos 19,45"] },
      { number: 11, text: "So blieb die Lade des HERRN drei Monate im Haus Obed-Edoms, des Gatiters. Und der HERR segnete Obed-Edom und sein ganzes Haus." },
      { number: 12, text: "*Und dem König David wurde berichtet: Der HERR hat das Haus Obed-Edoms und alles, was ihm gehört, gesegnet* wegen der Lade Gottes. Da ging David hin und holte die Lade Gottes mit Freuden aus dem Haus Obed-Edoms in die Stadt Davids herauf*.", footnotes: ["℘ V. 12-23: 1Chr 15; 16", "℘ 1Chr 26,4-8", "℘ 1Kö 8,3.4"] },
      { number: 13, text: "Und es geschah, wenn die Träger der Lade des HERRN sechs Schritte gegangen waren, opferte er einen Stier und ein Mastkalb*.", footnotes: ["℘ 1Kö 8,5"] },
      { number: 14, text: "Und David tanzte mit aller Kraft vor dem HERRN*, und David war mit einem leinenen Efod gegürtet*.", footnotes: ["℘ 2Mo 15,20", "℘ 1Sam 2,18"] },
      { number: 15, text: "So brachten David und das ganze Haus Israel die Lade des HERRN hinauf mit Jauchzen* und mit Hörnerschall*.", footnotes: ["℘ Ps 149,5; Hab 3,18", "℘ Ps 150,3"] },
      { number: 16, text: "Und es geschah, als die Lade des HERRN in die Stadt Davids kam, schaute Michal, die Tochter Sauls*, aus dem Fenster. Als sie nun den König David vor dem HERRN hüpfen und tanzen sah, da verachtete sie ihn in ihrem Herzen*.", footnotes: ["℘ 1Sam 18,20", "℘ Ps 123,3"] },
      { number: 17, text: "*Und sie brachten die Lade des HERRN hinein und stellten sie an ihre Stelle in die Mitte des Zeltes, das David für sie aufgeschlagen hatte. Und David brachte Brandopfer und Heilsopfer* vor dem HERRN dar.", footnotes: ["℘ V. 17-19: 1Chr 16,1-3", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 18, text: "Und als David die Darbringung der Brandopfer und der Heilsopfer* beendet hatte, segnete er das Volk im Namen des HERRN der Heerscharen*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 2Mo 39,43; 1Kö 8,14; Ps 129,8"] },
      { number: 19, text: "Und er verteilte an das ganze Volk, an die ganze Menge Israels, vom Mann bis zur Frau, an jeden einen Brotkuchen, einen Dattelkuchen und einen Rosinenkuchen*. Und das ganze Volk ging fort, jeder in sein Haus*.", footnotes: ["℘ 2Chr 30,24", "℘ Jos 22,6"] },
      { number: 20, text: "Und als David zurückkehrte, um seinem Haus den Segensgruß zu bringen*, ging Michal, die Tochter Sauls*, hinaus, David entgegen, und sagte: Wie ehrenwert hat sich heute der König von Israel gezeigt, als er sich heute vor den Augen der Mägde seiner Knechte entblößt hat, wie sich sonst nur einer der ehrlosen Leute entblößt!", footnotes: ["℘ 1Chr 16,43", "℘ 1Sam 18,20"] },
      { number: 21, text: "Da sagte David zu Michal: Vor dem HERRN, der mich vor deinem Vater und vor seinem ganzen Haus erwählt hat, um mich zum Fürsten über das Volk des HERRN, über Israel, zu bestellen*, ja, vor dem HERRN will ich tanzen.", footnotes: ["℘ 1Sam 13,14"] },
      { number: 22, text: "Und ich will noch geringer* werden als diesmal und will niedrig werden in meinen Augen*; aber bei den Mägden, von denen du sprichst, bei ihnen werde ich in Ehren stehen*.", footnotes: ["o. verachteter", "LXX: in deinen Augen", "℘ Ps 131,1; 1Kor 4,10"] },
      { number: 23, text: "Michal aber, die Tochter Sauls, bekam kein Kind bis zum Tag ihres Todes." },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Und es geschah, als der König in seinem Haus wohnte*, und der HERR ihm ringsumher Ruhe verschafft hatte vor all seinen Feinden,", heading: "Verheißung des HERRN für David und sein Königtum", footnotes: ["℘ V. 1-16: 1Chr 17,1-14; 22,7-10; 28,2-7", "℘ Kap. 5,11"] },
      { number: 2, text: "da sagte der König zum Propheten Nathan*: Siehe doch, ich wohne in einem Haus aus Zedern*, während die Lade Gottes in dem Zelt* wohnt*.", footnotes: ["℘ 1Kö 1,8; 1Chr 29,29; 2Chr 29,25", "℘ Kap. 5,11", "w. inmitten der Zeltdecke", "℘ Kap. 11,11; Ps 132,2-5; Apg 7,46"] },
      { number: 3, text: "Und Nathan* sagte zum König: Geh hin, tu alles, was du im Herzen hast*, denn der HERR ist mit dir*!", footnotes: ["℘ 1Kö 1,8; 1Chr 29,29; 2Chr 29,25", "℘ 1Sam 14,7; 1Kö 8,17.18", "℘ 1Sam 10,7"] },
      { number: 4, text: "Und es geschah in jener Nacht, da geschah das Wort des HERRN zu Nathan*:", footnotes: ["℘ 4Mo 12,6"] },
      { number: 5, text: "Geh hin und sage zu meinem Knecht, zu David*: So spricht der HERR: Du willst mir ein Haus bauen als Wohnung für mich*?", footnotes: ["℘ Spr 16,1", "℘ 1Kö 5,17; 1Chr 28,3"] },
      { number: 6, text: "Wahrhaftig, nie habe ich in einem Haus gewohnt von dem Tag an, als ich die Söhne Israel aus Ägypten heraufgeführt habe, bis zum heutigen Tag; sondern ich bin umhergezogen in Zelt und Wohnung*.", footnotes: ["o. in einer Zeltwohnung. — Andere üs. mit 1Chr 17,5: im Zelt von Wohnstätte zu Wohnstätte\n℘ 2Mo 40,38; Ri 20,27; 1Kö 8,16"] },
      { number: 7, text: "In der ganzen Zeit, die ich unter allen Söhnen Israel umhergezogen bin, habe ich da jemals zu einem der Stämme* Israels, dem ich gebot, mein Volk Israel zu weiden, ein Wort geredet und gesagt: Warum habt ihr mir nicht ein Haus aus Zedern gebaut*?", footnotes: ["mit 1Chr 17,6: zu einem der Richter", "℘ Jes 66,1"] },
      { number: 8, text: "Und nun, so sollst du zu meinem Knecht, zu David, sagen: So spricht der HERR der Heerscharen: Ich selbst habe dich von der Weide genommen, hinter der Schafherde weg*, dass du Fürst sein solltest über mein Volk, über Israel*.", footnotes: ["℘ Am 7,15", "℘ Kap. 5,2"] },
      { number: 9, text: "Und ich bin mit dir gewesen überall*, wohin du gegangen bist, und habe alle deine Feinde vor dir ausgerottet*. Und ich mache dir einen großen Namen* gleich dem Namen der Großen, die auf Erden sind.", footnotes: ["℘ Kap. 5,10; 8,6.14", "℘ Kap. 22,38-43", "o. Und ich habe dir einen großen Namen gemacht\n℘ 1Mo 12,2; Jos 6,27; 1Sam 18,30; Ps 21,6"] },
      { number: 10, text: "Und ich setze für mein Volk, für Israel, einen Ort fest und pflanze es ein*, dass es an seiner Stätte sicher wohnt und nicht mehr in Unruhe gerät und die Söhne der Ruchlosigkeit es nicht mehr unterdrücken* wie früher,", footnotes: ["o. ich habe . . . für Israel einen Ort festgesetzt und habe es eingepflanzt\n℘ 2Kö 21,8; Ps 80,9.10; Jes 60,21", "℘ Jes 60,18"] },
      { number: 11, text: "und zwar seit dem Tag, da ich Richter über mein Volk Israel bestellt habe*. Und ich verschaffe dir Ruhe* vor all deinen Feinden*. So verkündigt dir nun der HERR, dass der HERR dir ein Haus machen wird*.", footnotes: ["℘ Ri 2,16", "o. ich habe dir Ruhe verschafft", "℘ Hi 34,29", "℘ 2Mo 1,21; 1Sam 25,28"] },
      { number: 12, text: "Wenn deine Tage erfüllt sind und du dich zu deinen Vätern gelegt hast*, dann werde ich deinen Nachkommen*, der aus deinem Leib kommt*, nach dir aufstehen lassen und werde sein Königtum festigen*.", footnotes: ["℘ 1Kö 2,10", "w. deinen Samen", "℘ Mt 1,1", "℘ Ps 132,11; Apg 13,23"] },
      { number: 13, text: "Der wird meinem Namen ein Haus bauen*. Und ich werde den Thron seines Königtums festigen für ewig*.", footnotes: ["℘ 1Kö 5,19; 2Kö 21,4.7; Sach 6,12", "℘ Kap. 22,51; 1Mo 49,10; 1Kö 2,4; 2Kö 8,19; 2Chr 6,16; Hi 36,7; Ps 72,17; Jes 9,6; Jer 33,17; Hes 37,25; Dan 2,44; Lk 1,33; Apg 2,30; Offb 11,15"] },
      { number: 14, text: "Ich will ihm Vater sein*, und er soll mir Sohn sein*. Wenn er verkehrt handelt, werde ich ihn mit einer Menschenrute und mit Schlägen der Menschenkinder züchtigen*.", footnotes: ["℘ Ps 89,27", "℘ Ps 2,7; Offb 21,7", "d. h. menschlich züchtigen"] },
      { number: 15, text: "Aber meine Gnade soll nicht von ihm weichen*, wie ich sie von Saul habe weichen lassen, den ich vor dir weggetan habe*.", footnotes: ["℘ 1Kö 11,13; Ps 89,31-34", "℘ 1Sam 15,23"] },
      { number: 16, text: "Dein Haus aber und dein Königtum sollen vor dir* Bestand haben für ewig, dein Thron soll fest stehen für ewig.*", footnotes: ["einige hebr. Handschr. und LXX: vor mir", "℘ Kap. 22,51; 1Mo 49,10; 1Kö 2,4; 2Kö 8,19; 2Chr 6,16; Hi 36,7; Ps 72,17; Jes 9,6; Jer 33,17; Hes 37,25; Dan 2,44; Lk 1,33; Apg 2,30; Offb 11,15"] },
      { number: 17, text: "*Nach all diesen Worten und nach dieser ganzen Vision, so redete Nathan zu David.", footnotes: ["℘ V. 17-29: 1Chr 17,15-27"] },
      { number: 18, text: "Da ging der König David hinein und setzte sich vor dem HERRN nieder und sagte: Wer bin ich*, Herr, HERR, und was ist mein Haus*, dass du mich bis hierher gebracht hast?", footnotes: ["℘ Rt 2,10; 1Sam 18,18; 1Chr 29,14", "℘ Kap. 23,5; 1Mo 32,11"] },
      { number: 19, text: "Und das war noch zu gering in deinen Augen, Herr, HERR! Und du hast sogar über das Haus deines Knechtes auf ferne Zukunft hin geredet, und dies als Weisung für Menschen*, Herr, HERR*!", footnotes: ["o. und dies nach Menschenweise", "℘ 2Kö 3,18"] },
      { number: 20, text: "Doch was soll David noch weiter zu dir reden? Du kennst ja deinen Knecht*, Herr, HERR!", footnotes: ["℘ Jos 5,14; Ps 139,1"] },
      { number: 21, text: "Wegen deines Wortes und nach deinem Herzen hast du all dies Große getan, um es deinen Knecht erkennen zu lassen." },
      { number: 22, text: "Darum bist du groß, HERR, Gott! Ja, niemand ist dir gleich, und es gibt keinen Gott außer dir*, nach allem, was wir mit unseren Ohren gehört haben*.", footnotes: ["℘ Kap. 22,32; 2Mo 8,6; 5Mo 4,35.39; 1Kö 8,23.60", "℘ 5Mo 3,24"] },
      { number: 23, text: "Und wer ist wie dein Volk, wie Israel, die einzige Nation auf Erden, für die Gott hingegangen ist, sie sich zum Volk zu erlösen und um sich einen Namen zu machen* und an ihnen* Großes zu erweisen und furchtgebietende Taten an deinem Land, indem du vor deinem Volk, das du dir aus Ägypten erlöst hast, Nationen und ihre Götter vertriebst*.", footnotes: ["℘ 2Mo 9,16; 33,16; Jes 63,14", "so mit einigen hebr. Handschr., der aram. und lat. Üs.; Mas. T.: an euch", "vgl. 1Chr 17,21\n℘ Ps 44,3.4; Jer 32,20"] },
      { number: 24, text: "Und du hast dir dein Volk Israel fest gegründet, dass es ewig dir zum Volk sei; und du, HERR, bist ihr Gott* geworden*.", footnotes: ["w. ihnen zum Gott", "℘ 2Mo 6,7"] },
      { number: 25, text: "Und nun, HERR und Gott, das Wort, das du über deinen Knecht und über sein Haus geredet hast, halte ewig aufrecht, und tu, wie du geredet hast*!", footnotes: ["℘ 1Sam 1,23; 2Chr 6,17; Ps 119,49"] },
      { number: 26, text: "Dann wird dein Name ewig groß sein, indem man sagt: Der HERR der Heerscharen ist Gott über Israel!* Und das Haus deines Knechtes David wird vor dir fest stehen*.", footnotes: ["℘ 1Kö 18,36; Ps 48,15; Mt 15,31", "℘ Ps 61,7.8"] },
      { number: 27, text: "Denn du, HERR der Heerscharen, Gott Israels, hast das Ohr deines Knechtes geöffnet und gesagt: Ich werde dir ein Haus bauen*! — darum hat dein Knecht sich ein Herz gefasst, dieses Gebet zu dir zu beten.", footnotes: ["℘ 1Kö 11,38"] },
      { number: 28, text: "Und nun, Herr, HERR, du bist es, der da Gott ist, und deine Worte sind Wahrheit*, und du hast dieses Gute zu deinem Knecht geredet.", footnotes: ["o. Treue\n℘ Joh 17,17; Tit 1,2"] },
      { number: 29, text: "So lass es dir nun gefallen und segne das Haus deines Knechtes, dass es ewig vor dir sei! Denn du, Herr, HERR, hast geredet, und mit deinem Segen wird das Haus deines Knechtes gesegnet sein für ewig*!", footnotes: ["℘ Jes 55,3"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Und es geschah danach, da schlug David die Philister und demütigte sie*. Und David nahm die Zügel der Herrschaft* aus der Hand der Philister.", heading: "Davids Kriege — Seine Beamten", footnotes: ["℘ V. 1-14: 1Chr 18,1-13", "℘ Kap. 5,17-25; 21,15; 1Sam 7,13", "w. den Zaum der Hauptstadt, o. den Zaum der Elle. — Das Bild ist nicht mehr sicher zu deuten."] },
      { number: 2, text: "Er schlug auch die Moabiter* und maß sie mit der Messschnur ab, wobei er sie sich auf die Erde legen ließ. Und er maß zwei Schnurlängen ab, um zu töten, und eine volle Schnurlänge, um am Leben zu lassen. Und die Moabiter wurden David zu Knechten, die Tribut entrichten mussten*.", footnotes: ["℘ 4Mo 24,17", "℘ 2Kö 1,1; 3,4; Ps 18,45; 60,10; Hebr 11,33"] },
      { number: 3, text: "David schlug auch Hadad-Eser, den Sohn Rehobs, den König von Zoba*, als er hinzog, um seine Macht am Strom Euphrat wiederherzustellen.", footnotes: ["℘ Kap. 10,6; 23,36; 1Sam 14,47; 2Chr 8,3"] },
      { number: 4, text: "Und David nahm von ihm 1 700 Berittene und 20 000 Mann Fußvolk gefangen. Und David lähmte alle Wagenpferde*, aber 100 Wagenpferde von ihm ließ er übrig.", footnotes: ["℘ Jos 11,6.9"] },
      { number: 5, text: "Da kamen die Aramäer von Damaskus, um Hadad-Eser, dem König von Zoba, zu helfen. David aber schlug unter den Aramäern 22 000 Mann." },
      { number: 6, text: "Und David setzte in Aram-Damaskus Vögte* ein, und die Aramäer wurden David zu Knechten*, die Tribut entrichten mussten*. So half der HERR dem David überall, wohin er zog*.", footnotes: ["o. Gouverneure. — Andere üs.: David legte Besatzung nach Aram-Damaskus; vgl. V. 14: nach Edom", "℘ Kap. 10,19; 2Kö 14,28", "℘ 2Kö 1,1; 3,4; Ps 18,45; 60,10; Hebr 11,33", "o. sooft er auszog\n℘ Kap. 5,10; 7,9; 2Kö 18,7"] },
      { number: 7, text: "Und David nahm die goldenen Schilde*, die den Knechten Hadad-Esers gehörten, und brachte sie nach Jerusalem.", footnotes: ["℘ 1Kö 10,16; 2Kö 11,10"] },
      { number: 8, text: "Und aus Betach und aus Berotai, den Städten Hadad-Esers*, nahm der König David sehr viel Bronze.", footnotes: ["℘ 1Kö 11,23; Hes 47,16"] },
      { number: 9, text: "Und als Toï, der König von Hamat*, hörte, dass David die ganze Heeresmacht Hadad-Esers geschlagen hatte,", footnotes: ["℘ 4Mo 34,8; Am 6,2"] },
      { number: 10, text: "sandte Toï seinen Sohn Joram zum König David, um ihn nach seinem Wohlergehen zu fragen und ihm Glück zu wünschen*, weil er gegen Hadad-Eser gekämpft und ihn geschlagen hatte — denn Hadad-Eser war Toïs Kriegsgegner gewesen —, und in seiner Hand waren silberne Geräte und goldene Geräte und bronzene Geräte.", footnotes: ["w. um ihn zu segnen\n℘ Jes 39,1"] },
      { number: 11, text: "Auch diese heiligte der König David dem HERRN, samt dem Silber und Gold, das er von all den Nationen heiligte, die er unterworfen hatte*:", footnotes: ["℘ 1Kö 7,51; 1Chr 26,27; Mi 4,13"] },
      { number: 12, text: "von Aram, von Moab und von den Söhnen Ammon, von den Philistern und von Amalek und von dem Plündergut Hadad-Esers, des Sohnes Rehobs, des Königs von Zoba." },
      { number: 13, text: "Und David machte sich einen Namen: Als er von seiner Schlacht gegen Edom* im Salztal* zurückkam, da waren 18 000 Mann gefallen*.", footnotes: ["so mit einigen hebr. Handschr., LXX und der syr. Üs.; Mas. T.: gegen Aram", "℘ 2Kö 14,7", "℘ 1Kö 11,15; 2Kö 14,7; Ps 60,1.2"] },
      { number: 14, text: "Und er setzte in Edom Vögte* ein, in ganz Edom setzte er Vögte ein*. Und alle Edomiter wurden David zu Knechten*. So half der HERR dem David überall, wohin er zog*.", footnotes: ["o. Gouverneure. — Andere üs.: David legte Besatzung nach Edom", "℘ Kap. 5,10; 7,9; 2Kö 18,7", "℘ 1Mo 25,23; 4Mo 24,18; 1Kö 22,48", "o. sooft er auszog\n℘ 1Mo 25,23; 4Mo 24,18; 1Kö 22,48"] },
      { number: 15, text: "*Und David war König über ganz Israel. Und David übte Recht und Gerechtigkeit an seinem ganzen Volk*.", footnotes: ["℘ V. 15-18: Kap. 20,23-26; 1Chr 18,14-17; vgl. 1Kö 4,1-6", "℘ Kap. 15,3; 23,3.4; 1Kö 10,9; Ps 78,72; Jer 22,15; Hebr 11,33"] },
      { number: 16, text: "Und Joab, der Sohn der Zeruja, war über das Heer gesetzt*. Und Joschafat, der Sohn Ahiluds, war Berater*.", footnotes: ["℘ Kap. 18,2; 1Chr 11,6", "w. der Bekanntmachende\n℘ 2Kö 18,18"] },
      { number: 17, text: "Und Zadok*, der Sohn Ahitubs, und Ahimelech, der Sohn Abjatars, waren Priester*. Und Seraja war Schreiber.", footnotes: ["℘ 1Kö 1,26; 1Chr 5,34; 9,11; 12,29", "℘ Kap. 15,24.35; 17,15; 19,12; 1Chr 15,11; Hes 44,15"] },
      { number: 18, text: "Und Benaja*, der Sohn Jojadas, war über die Kreter und Pleter* gesetzt*. Und die Söhne Davids sind Priester* gewesen.", footnotes: ["℘ Kap. 23,20-23", "d. i. die Leibgarde Davids", "℘ Kap. 15,18; 20,7.23; 1Kö 1,38.44; 2Kö 11,4", "Vielleicht ist diese Bezeichnung als Ehrentitel gedacht."] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und David sagte: Gibt es vielleicht noch jemand, der vom Haus Sauls übrig geblieben ist, damit ich Gnade an ihm erweise Jonatans wegen*?", heading: "Davids Großmut gegen Mefi-Boschet, den Sohn Jonatans", footnotes: ["℘ Kap. 21,7; 1Sam 20,15"] },
      { number: 2, text: "Es war aber ein Knecht vom Haus Sauls, sein Name war Ziba*, den rief man zu David. Und der König sagte zu ihm: Bist du Ziba? Er sagte: Ja, dein Knecht.", footnotes: ["℘ Kap. 16,1; 19,18.30"] },
      { number: 3, text: "Und der König sagte: Ist niemand mehr da vom Haus Sauls, damit ich Gottes Gnade an ihm erweise? Da sagte Ziba zum König: Es ist noch ein Sohn Jonatans da, der an beiden Füßen gelähmt* ist*.", footnotes: ["w. geschlagen", "℘ Kap. 4,4; 19,27"] },
      { number: 4, text: "Und der König sagte zu ihm: Wo ist er? Ziba sagte zum König: Siehe, er ist im Haus Machirs, des Sohnes Ammiëls, in Lo-Dabar*.", footnotes: ["℘ Kap. 17,27"] },
      { number: 5, text: "Da sandte der König David hin und ließ ihn aus dem Haus Machirs, des Sohnes Ammiëls, aus Lo-Dabar holen." },
      { number: 6, text: "Da kam Mefi-Boschet*, der Sohn Jonatans*, des Sohnes Sauls, zu David und fiel auf sein Angesicht und warf sich nieder. Und David sagte: Mefi-Boschet! Er sagte: Siehe, dein Knecht.", footnotes: ["℘ Kap. 19,25; 21,7", "℘ 1Chr 8,34"] },
      { number: 7, text: "Und David sagte zu ihm: Fürchte dich nicht!* Denn ich will nur Gnade an dir erweisen wegen deines Vaters Jonatan*, und ich will dir alle Felder deines Vaters Saul zurückgeben; du aber sollst ständig an meinem Tisch Brot essen*.", footnotes: ["℘ 1Sam 22,23", "℘ Kap. 21,7; 1Sam 20,15", "℘ Kap. 19,29; 1Kö 2,7"] },
      { number: 8, text: "Da warf er sich nieder und sagte: Was ist dein Knecht, dass du dich einem toten Hund* zugewandt hast, wie ich einer bin?", footnotes: ["℘ Kap. 3,8"] },
      { number: 9, text: "Und der König rief Ziba, den Diener Sauls, und sagte zu ihm: Alles, was Saul und seinem ganzen Haus gehört hat, habe ich dem Sohn deines Herrn gegeben*.", footnotes: ["℘ Kap. 16,4; 19,30"] },
      { number: 10, text: "Und du sollst für ihn das Land bearbeiten, du und deine Söhne und deine Knechte, und die Ernte einbringen, damit der Sohn deines Herrn Brot zu essen hat*. Mefi-Boschet selbst aber, der Sohn deines Herrn, soll ständig Brot an meinem Tisch essen. Und Ziba hatte fünfzehn Söhne und zwanzig Knechte*.", footnotes: ["w. Brot hat und es essen kann", "℘ Kap. 19,18"] },
      { number: 11, text: "Da sagte Ziba zum König: Nach allem, was mein Herr, der König, seinem Knecht befiehlt, so wird dein Knecht tun*. Und Mefi-Boschet, sagte der König, wird an meinem Tisch essen wie einer von den Königssöhnen.", footnotes: ["℘ Kap. 15,15"] },
      { number: 12, text: "Und Mefi-Boschet hatte einen kleinen Sohn, dessen Name war Micha*. Und alle, die im Haus Zibas wohnten, waren Mefi-Boschets Knechte.", footnotes: ["℘ 1Chr 8,34"] },
      { number: 13, text: "So wohnte Mefi-Boschet in Jerusalem, denn er aß beständig am Tisch des Königs. Er war aber lahm an beiden Füßen*.", footnotes: ["℘ Kap. 4,4; 19,27"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und es geschah danach, da starb der König der Söhne Ammon, und sein Sohn Hanun wurde an seiner Stelle König.", heading: "Kriege gegen die Ammoniter und Aramäer", footnotes: ["℘ 1Chr 19"] },
      { number: 2, text: "Und David sagte: Ich will Gnade erweisen an Hanun, dem Sohn des Nahasch*, so wie sein Vater Gnade an mir erwiesen hat. So sandte David hin, um ihn durch seine Knechte wegen seines Vaters zu trösten. Und die Knechte Davids kamen in das Land der Söhne Ammon.", footnotes: ["℘ 1Sam 11,1"] },
      { number: 3, text: "Da sagten die Obersten der Söhne Ammon zu Hanun, ihrem Herrn: Will David in deinen Augen wirklich deinen Vater ehren, wenn er Tröster zu dir gesandt hat? Hat nicht David seine Knechte zu dir gesandt, um die Stadt zu erforschen und sie auszukundschaften und sie umzukehren*?", footnotes: ["℘ Kap. 3,25"] },
      { number: 4, text: "Da nahm Hanun die Knechte Davids und ließ ihnen die Hälfte des Bartes abscheren und ihre Kleider zur Hälfte abschneiden bis an ihr Gesäß*; und er schickte sie weg.", footnotes: ["℘ Jes 20,4"] },
      { number: 5, text: "Als man das David berichtete, sandte er ihnen Boten entgegen, denn die Männer waren sehr geschändet*. Und der König ließ ihnen sagen: Bleibt in Jericho*, bis euer Bart gewachsen ist, dann kommt zurück!", footnotes: ["o. die Männer schämten sich sehr", "℘ Jos 6,1"] },
      { number: 6, text: "Als nun die Söhne Ammon sahen, dass sie sich bei David stinkend gemacht hatten*, da sandten die Söhne Ammon hin und warben die Aramäer von Bet-Rehob* und die Aramäer von Zoba*, 20 000 Mann zu Fuß, und den König von Maacha*, 1 000 Mann, und die Männer von Tob, 12 000 Mann.", footnotes: ["℘ Kap. 16,21; 1Sam 13,4", "℘ Ri 18,28", "℘ Kap. 8,3-5; Ri 11,3.5; 1Kö 11,24", "℘ 5Mo 3,14; Jos 13,13"] },
      { number: 7, text: "Als David davon hörte, sandte er Joab aus und das ganze Heer, die Helden*.", footnotes: ["℘ Kap. 23,8"] },
      { number: 8, text: "Und die Söhne Ammon zogen aus und ordneten sich am Eingang des Tores zur Schlacht. Aber die Aramäer von Zoba und Rehob und die Männer von Tob und Maacha standen gesondert auf dem freien Feld." },
      { number: 9, text: "Und als Joab sah, dass die Kampffront von vorn und von hinten gegen ihn gerichtet war*, da wählte er von allen Auserlesenen Israels einen Teil aus und ordnete sich mit ihnen zur Schlacht gegen Aram.", footnotes: ["℘ 2Chr 13,14"] },
      { number: 10, text: "Den Rest des Kriegsvolkes aber übergab er der Hand seines Bruders Abischai*; und der ordnete sie zur Schlacht gegen die Söhne Ammon.", footnotes: ["℘ Kap. 18,2"] },
      { number: 11, text: "Und er sagte: Wenn Aram stärker ist als ich, dann sollst du mir Hilfe leisten; und wenn die Söhne Ammon stärker sind als du, dann will ich kommen, um dir zu helfen." },
      { number: 12, text: "Sei stark und lass uns stark sein* für unser Volk und für die Städte unseres Gottes*! Der HERR aber möge tun, was gut ist in seinen Augen*.", footnotes: ["℘ 5Mo 31,6; 1Sam 4,9", "℘ Neh 4,8", "℘ Kap. 15,26; 1Sam 3,18; Est 4,16"] },
      { number: 13, text: "Da rückten Joab und das Volk, das bei ihm war, zum Kampf gegen die Aramäer vor; und sie flohen vor ihm*.", footnotes: ["℘ Ps 68,2.13"] },
      { number: 14, text: "Als aber die Söhne Ammon sahen, dass Aram floh, da flohen auch sie vor Abischai und zogen sich in die Stadt zurück. Da wandte sich Joab von den Söhnen Ammon ab und kam nach Jerusalem." },
      { number: 15, text: "Als nun Aram sah, dass es vor Israel geschlagen war, sammelten sie sich alle wieder*.", footnotes: ["℘ Jos 11,1-5"] },
      { number: 16, text: "Und Hadad-Eser sandte hin und ließ die Aramäer, die jenseits des Stromes Euphrat waren, zum Kampf ausziehen. Und sie kamen nach Helam, und Schobach, der Heeroberste Hadad-Esers, ging vor ihnen her." },
      { number: 17, text: "Das wurde David berichtet. Da versammelte er ganz Israel und ging über den Jordan und kam nach Helam. Und die Aramäer ordneten sich zur Schlacht gegen David und kämpften mit ihm." },
      { number: 18, text: "Aram aber floh vor Israel*, und David erschlug von Aram 700 Wagenkämpfer und 40 000 Reiter. Auch seinen Heerobersten Schobach erschlug er; und der starb dort.", footnotes: ["℘ Ps 68,2.13"] },
      { number: 19, text: "Als nun all die Könige, die Hadad-Esers Knechte waren, sahen, dass sie vor Israel geschlagen waren, schlossen sie Frieden mit Israel und dienten ihnen. Und die Aramäer fürchteten sich, den Söhnen Ammon noch einmal zu helfen." },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und es geschah bei der Wiederkehr* des Jahres, zur Zeit, wenn die Könige ins Feld ausziehen*, da sandte David Joab und seine Knechte mit ihm und ganz Israel aus. Und sie verheerten das Land der Söhne Ammon und belagerten Rabba*. David aber blieb in Jerusalem*.", heading: "Davids Ehebruch und Blutschuld", footnotes: ["d. h. im folgenden Frühjahr", "so mit der Leseform des Mas. T.; mit der Schreibform: als die Boten ausgezogen waren\n℘ 1Kö 20,22.26", "℘ Kap. 12,26; 5Mo 3,11", "℘ 1Chr 20,1"] },
      { number: 2, text: "Und es geschah zur Abendzeit, dass David von seinem Lager aufstand und sich auf dem Dach des Königshauses erging. Da sah er vom Dach aus eine Frau baden. Die Frau aber war von sehr schönem Aussehen*.", footnotes: ["℘ Kap. 13,1; 14,27; 1Mo 12,11; 5Mo 5,21"] },
      { number: 3, text: "Und David sandte hin und erkundigte sich nach der Frau*. Und man sagte: Ist das nicht Batseba, die Tochter Eliams*, die Frau Urias, des Hetiters*?", footnotes: ["℘ Spr 6,25; Mt 5,28", "℘ Kap. 23,34; 1Chr 3,5", "℘ Kap. 23,39; Mt 1,6"] },
      { number: 4, text: "Da sandte David Boten hin und ließ sie holen. Und sie kam zu ihm, und er lag bei ihr*. Sie hatte sich aber gerade gereinigt von ihrer Unreinheit. Und sie kehrte in ihr Haus zurück*.", footnotes: ["℘ 1Mo 34,2; 5Mo 5,18.21; Ps 51,2; Jak 1,13-15", "℘ Spr 30,20"] },
      { number: 5, text: "Und die Frau wurde schwanger. Und sie sandte hin und berichtete es David und sagte: Ich bin schwanger." },
      { number: 6, text: "Da sandte David zu Joab: Schick mir Uria, den Hetiter! Und Joab schickte Uria zu David." },
      { number: 7, text: "Und Uria kam zu ihm, und David fragte nach dem Wohlergehen Joabs und nach dem Wohlergehen des Volkes* und nach der Kriegslage*.", footnotes: ["℘ 2Mo 18,7", "w. nach dem Wohlergehen des Krieges"] },
      { number: 8, text: "Und David sagte zu Uria: Geh in dein Haus hinab und wasche deine Füße*! Und als Uria aus dem Haus des Königs ging, kam ein Geschenk des Königs hinter ihm her.", footnotes: ["℘ 1Mo 19,2"] },
      { number: 9, text: "Uria aber legte sich am Eingang des Königshauses nieder bei allen Knechten seines Herrn und ging nicht in sein Haus hinab." },
      { number: 10, text: "Und man berichtete es David: Uria ist nicht in sein Haus hinabgegangen. Da sagte David zu Uria: Bist du nicht von der Reise* gekommen? Warum bist du nicht in dein Haus hinabgegangen?", footnotes: ["w. vom Weg"] },
      { number: 11, text: "Uria aber sagte zu David: Die Lade und Israel und Juda wohnen in Zelten*, und mein Herr selbst, Joab, und die Knechte meines Herrn lagern auf freiem Feld*, und da sollte ich in mein Haus hineingehen, um zu essen und zu trinken und bei meiner Frau zu liegen*? So wahr du lebst und deine Seele lebt*, wenn ich das tue!*", footnotes: ["w. Hütten, o. Laubhütten\n℘ Kap. 7,2", "w. auf der Fläche des Feldes", "℘ 1Kor 7,29", "℘ 1Sam 1,26", "w. wenn ich diese Sache tue! — Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 12, text: "Da sagte David zu Uria: Bleib auch heute noch hier! Morgen werde ich dich dann entlassen. So blieb Uria an diesem Tag und am folgenden in Jerusalem." },
      { number: 13, text: "Und David lud ihn ein, und er aß und trank vor ihm, und er machte ihn betrunken. Und am Abend ging er hinaus, um sich auf sein Lager bei den Knechten seines Herrn hinzulegen; aber in sein Haus ging er nicht hinab." },
      { number: 14, text: "Und es geschah am nächsten Morgen, da schrieb David einen Brief an Joab und sandte ihn durch Uria." },
      { number: 15, text: "Und er schrieb in dem Brief Folgendes: Stellt Uria dahin, wo die Kampffront am härtesten ist, und zieht euch hinter ihm zurück, dass er getroffen wird und stirbt*!", footnotes: ["℘ 1Sam 18,17.25"] },
      { number: 16, text: "Und es geschah, als Joab die Stadt ständig beobachtete, setzte er Uria an der Stelle ein, von der er erkannt hatte, dass dort kriegstüchtige Männer waren." },
      { number: 17, text: "Als nun die Männer der Stadt auszogen und gegen Joab kämpften, fielen einige vom Volk, von den Knechten Davids; dabei starb auch Uria, der Hetiter*.", footnotes: ["℘ Kap. 12,9"] },
      { number: 18, text: "Da sandte Joab hin und berichtete David alle Ereignisse des Kampfes." },
      { number: 19, text: "Und er befahl dem Boten und sagte: Wenn du damit fertig bist, alle Ereignisse des Kampfes dem König zu melden," },
      { number: 20, text: "und wenn dann der Zorn des Königs aufsteigt und er zu dir sagt: Warum seid ihr so nah an die Stadt herangerückt, um zu kämpfen? Habt ihr nicht erkannt, dass sie von der Mauer herab schießen würden?" },
      { number: 21, text: "Wer hat denn Abimelech, den Sohn Jerubbeschets*, erschlagen? Warf nicht eine Frau den oberen Mühlstein von der Mauer auf ihn herab, dass er in Tebez starb?* Wozu seid ihr so nah an die Mauer herangerückt? — dann sollst du sagen: Auch dein Knecht Uria, der Hetiter, ist tot.", footnotes: ["In Ri 7,1ff lautet der Name Jerubbaal.", "℘ Ri 9,50-53"] },
      { number: 22, text: "Und der Bote ging hin. Und er kam und berichtete David alles, was Joab ihm aufgetragen hatte." },
      { number: 23, text: "Und der Bote sagte zu David: Da die Männer uns überlegen waren, zogen sie gegen uns aufs freie Feld heraus; wir aber blieben an ihnen bis zum Eingang des Tores." },
      { number: 24, text: "Da schossen die Schützen von der Mauer herab auf deine Knechte, und es starben einige von den Knechten des Königs; und auch dein Knecht Uria, der Hetiter, ist tot." },
      { number: 25, text: "Da sagte David zu dem Boten: So sollst du zu Joab sagen: Lass diese Sache nicht so schlimm sein in deinen Augen! Denn das Schwert frisst bald so, bald so*. Führe deinen Kampf gegen die Stadt entschlossen fort und reiße sie nieder*! So ermutige ihn!", footnotes: ["o. bald hier, bald dort", "℘ Kap. 12,26"] },
      { number: 26, text: "Und als Urias Frau hörte, dass Uria, ihr Mann, tot war, hielt sie die Totenklage um ihren Gatten*.", footnotes: ["w. Eheherrn"] },
      { number: 27, text: "Als aber die Trauerzeit vorüber war, sandte David hin und nahm sie in sein Haus auf*. Und sie wurde seine Frau und gebar ihm einen Sohn. In den Augen des HERRN aber war die Sache böse, die David getan hatte*.", footnotes: ["℘ 1Kö 21,16", "℘ Kap. 12,9; 1Kö 21,20; 1Chr 21,7; Spr 6,29; Jes 29,15"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und der HERR sandte Nathan zu David*. Und er kam zu ihm* und sagte zu ihm*: Zwei Männer waren in einer Stadt, der eine reich und der andere arm.", heading: "Nathans Gerichtswort und Davids Schuldbekenntnis", footnotes: ["℘ 1Kö 21,18", "℘ Ps 51,2", "℘ Kap. 24,11"] },
      { number: 2, text: "Der Reiche hatte Schafe und Rinder in großer Menge." },
      { number: 3, text: "Der Arme hatte aber nichts als nur ein einziges kleines Lamm*, das er gekauft hatte. Und er ernährte es*, und es wurde groß bei ihm, zugleich mit seinen Kindern. Von seinem Bissen aß es, aus seinem Becher trank es, und in seinem Schoß schlief es. Es war ihm wie eine Tochter.", footnotes: ["w. weibliches Lamm", "w. er hielt es am Leben"] },
      { number: 4, text: "Da kam ein Besucher zu dem reichen Mann; dem aber tat es leid, ein Tier von seinen Schafen und von seinen Rindern zu nehmen, um es für den Wanderer zuzurichten, der zu ihm gekommen war. Da nahm er das Lamm* des armen Mannes und richtete es für den Mann zu, der zu ihm gekommen war.", footnotes: ["w. weibliches Lamm"] },
      { number: 5, text: "Da entbrannte der Zorn Davids sehr gegen den Mann, und er sagte zu Nathan: So wahr der HERR lebt, der Mann, der das getan hat, ist ein Sohn des Todes*.", footnotes: ["℘ 1Sam 14,39; Röm 2,1"] },
      { number: 6, text: "Das Lamm* aber soll er vierfach erstatten*, dafür, dass er diese Sache getan hat, und weil es ihm um den Armen nicht leid getan hat.", footnotes: ["w. weibliches Lamm", "℘ 2Mo 21,37"] },
      { number: 7, text: "Da sagte Nathan zu David: Du bist der Mann*! So spricht der HERR, der Gott Israels: Ich habe dich zum König über Israel gesalbt*, und ich habe dich aus der Hand Sauls gerettet*,", footnotes: ["℘ 1Kö 20,40-42", "℘ 1Sam 16,13", "℘ Kap. 22,1"] },
      { number: 8, text: "und ich habe dir das Haus deines Herrn gegeben und die Frauen deines Herrn in deinen Schoß und habe dir das Haus Israel und Juda gegeben*. Und wenn es zu wenig war, so hätte ich dir noch dies und das hinzugefügt.", footnotes: ["℘ Kap. 5,5"] },
      { number: 9, text: "Warum hast du das Wort des HERRN verachtet*, indem du tatest, was böse ist in seinen Augen*? Uria, den Hetiter, hast du mit dem Schwert erschlagen, und seine Frau hast du dir zur Frau genommen*. Ihn selbst hast du ja umgebracht durch das Schwert der Söhne Ammon*.", footnotes: ["℘ 4Mo 15,31; 1Sam 15,19; Spr 14,2", "℘ Kap. 11,27", "℘ Ps 68,2.13", "℘ Kap. 11,17; 1Kö 15,5; Ps 51,16"] },
      { number: 10, text: "Nun denn, so soll das Schwert von deinem Haus auf ewig nicht weichen*, dafür, dass du mich verachtet und die Frau Urias, des Hetiters, genommen hast, damit sie deine Frau sei.", footnotes: ["℘ Kap. 13,28.29; 18,14.15; 1Kö 2,24.25"] },
      { number: 11, text: "So spricht der HERR: Siehe, ich lasse aus deinem eigenen Haus Unglück über dich erstehen* und nehme deine Frauen vor deinen Augen weg und gebe sie deinem Nächsten, dass er bei deinen Frauen liegt vor den Augen dieser Sonne*!", footnotes: ["℘ Kap. 16,11", "℘ Kap. 16,22; Hi 31,10"] },
      { number: 12, text: "Denn du, du hast es im Verborgenen getan*; ich aber, ich werde dies tun vor ganz Israel und vor der Sonne*!", footnotes: ["℘ Hi 34,22; Lk 12,2", "℘ Kap. 16,22; Hi 31,10"] },
      { number: 13, text: "Da sagte David zu Nathan: Ich habe gegen den HERRN gesündigt*. Und Nathan sagte zu David: So hat auch der HERR deine Sünde hinweggetan*, du wirst nicht sterben*.", footnotes: ["℘ Kap. 24,10; 2Mo 9,27; Ps 51,6; Lk 15,21", "w. vorübergehen lassen\n℘ Ps 32,1.2; 130,4; Spr 28,13; Jes 44,22; 1Jo 1,7.9", "℘ 3Mo 20,10; 4Mo 35,31"] },
      { number: 14, text: "Nur weil du den Feinden des HERRN durch diese Sache Anlass zur Lästerung gegeben hast*, muss auch der Sohn, der dir geboren ist, sterben*.", footnotes: ["℘ Neh 5,9; Hes 36,20; Röm 2,24", "℘ Ps 99,8; 1Jo 5,16.17"] },
      { number: 15, text: "Und Nathan ging in sein Haus zurück.Und der HERR schlug das Kind, das Urias Frau dem David geboren hatte, und es wurde schwer krank.", heading: "Davids Bestrafung — Geburt Salomos" },
      { number: 16, text: "Und David suchte Gott um des Jungen willen. Und David fastete lange*. Und wenn er hineinkam, lag er die Nacht über auf der Erde*.", footnotes: ["w. fastete ein Fasten; d. h. auch: hielt ein absolutes Fasten", "℘ Kap. 13,31; Jos 7,6; Dan 9,3"] },
      { number: 17, text: "Und die Ältesten seines Hauses machten sich zu ihm auf, um ihn von der Erde aufzurichten. Aber er wollte nicht und aß kein Brot mit ihnen*.", footnotes: ["℘ Kap. 3,35; 1Mo 37,35"] },
      { number: 18, text: "Und es geschah am siebten Tag, da starb das Kind. Und die Knechte Davids fürchteten sich, ihm zu berichten, dass das Kind tot sei, denn sie sagten sich: Siehe, als das Kind noch am Leben war, haben wir zu ihm geredet, und er hat nicht auf unsere Stimme gehört: Wie könnten wir jetzt zu ihm sagen: Das Kind ist tot? Er würde Unheil anrichten." },
      { number: 19, text: "Und David sah, dass seine Knechte miteinander flüsterten. Da merkte David, dass das Kind tot war. Und David sagte zu seinen Knechten: Ist das Kind tot? Sie sagten: Es ist tot." },
      { number: 20, text: "Da stand David von der Erde auf und wusch sich und salbte sich und wechselte seine Kleider und ging ins Haus des HERRN und warf sich vor ihm nieder*. Dann kam er in sein Haus zurück und verlangte zu essen, und man setzte ihm Brot vor, und er aß.", footnotes: ["℘ 1Sam 15,25.31; Hi 1,20"] },
      { number: 21, text: "Da sagten seine Knechte zu ihm: Was ist das für eine Sache, die du tust? Als das Kind lebte, hast du seinetwegen gefastet und geweint, sobald aber das Kind gestorben war, bist du aufgestanden und hast gegessen!" },
      { number: 22, text: "Da sagte er: Als das Kind noch lebte, habe ich gefastet und geweint, weil ich mir sagte: Wer weiß, vielleicht wird der HERR mir gnädig sein, und das Kind bleibt am Leben*.", footnotes: ["℘ Jon 3,9"] },
      { number: 23, text: "Jetzt aber, da es tot ist, wozu sollte ich denn fasten? Kann ich es etwa noch zurückbringen? Ich gehe einmal zu ihm*, aber es wird nicht zu mir zurückkehren*.", footnotes: ["℘ 1Kö 2,2", "℘ Hi 7,10"] },
      { number: 24, text: "Und David tröstete seine Frau Batseba. Und er ging zu ihr ein und lag bei ihr. Und sie gebar einen Sohn*, und er gab ihm den Namen Salomo*. Und der HERR liebte ihn*.", footnotes: ["℘ Spr 4,3", "hebr. schelomo; d. h. der Friedliche\n℘ Kap. 5,14; 1Kö 1,10; 1Chr 22,9; Mt 1,6", "℘ 5Mo 33,12; Neh 13,26"] },
      { number: 25, text: "Und er sandte durch den Propheten Nathan* hin; und der gab ihm den Namen Jedidja* wegen des HERRN*.", footnotes: ["℘ 1Kö 1,8", "d. h. der Liebling Jahs", "℘ 5Mo 33,12; Neh 13,26"] },
      { number: 26, text: "*Und Joab kämpfte gegen die Stadt Rabba* der Söhne Ammon* und nahm die Königsstadt ein*.", heading: "Davids Sieg über die Ammoniter", footnotes: ["℘ 1Chr 20,1-3", "℘ Kap. 11,1; 17,27", "℘ Hes 25,5", "℘ Kap. 11,25"] },
      { number: 27, text: "Und Joab sandte Boten zu David und ließ ihm sagen: Ich habe gegen Rabba gekämpft und auch die Wasserstadt* eingenommen.", footnotes: ["d. i. der Stadtteil, der am Bach, dem heutigen Sel Amman, lag"] },
      { number: 28, text: "Und nun sammle den Rest des Kriegsvolkes und belagere die Stadt und nimm sie ein, damit nicht ich es bin, der die Stadt einnimmt, und nicht mein Name über ihr ausgerufen wird!" },
      { number: 29, text: "Da sammelte David alles Kriegsvolk und zog nach Rabba, und er kämpfte gegen es und nahm es ein." },
      { number: 30, text: "Und er nahm ihrem König die Krone von seinem Haupt*. Ihr Gewicht war ein Talent Gold, und ein kostbarer Stein war an ihr. Und sie kam auf das Haupt Davids. Und das Plündergut der Stadt brachte er in großer Menge hinaus.", footnotes: ["LXX: und nahm die Krone des Gottes Milkom von dessen Haupt; vgl. 1Kö 11,5"] },
      { number: 31, text: "Das Volk aber, das darin war, führte er heraus und stellte es an die Steinsäge, an die eisernen Pickel und an die eisernen Beile und ließ sie als Sklaven an den Ziegelformen arbeiten*. Und so machte er es mit allen Städten der Söhne Ammon*. Und David und das ganze Volk kehrten nach Jerusalem zurück*.", footnotes: ["T.; Mas. T.: ließ sie durch die Ziegelformen gehen", "℘ Am 1,13.14", "℘ Jos 10,15"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Und es geschah danach: Absalom*, der Sohn Davids, hatte eine schöne Schwester*, ihr Name war Tamar*. Und Amnon*, der Sohn Davids, liebte sie.", heading: "Amnons Schandtat", footnotes: ["℘ Kap. 3,3", "℘ Kap. 11,2", "℘ 1Chr 3,9", "℘ Kap. 3,2"] },
      { number: 2, text: "Und es war dem Amnon wehe wegen seiner Schwester Tamar, bis dass er sich krank fühlte. Denn sie war eine Jungfrau, und es war in den Augen Amnons unmöglich, ihr irgendetwas anzutun." },
      { number: 3, text: "Und Amnon hatte einen Freund, sein Name war Jonadab*, der Sohn des Schimea, des Bruders Davids*. Jonadab aber war ein sehr kluger Mann.", footnotes: ["℘ 1Chr 27,32", "℘ Kap. 21,21; 1Chr 2,13"] },
      { number: 4, text: "Der sagte zu ihm: Warum bist du Morgen für Morgen so elend, Königssohn? Willst du es mir nicht mitteilen*? Amnon sagte zu ihm: Ich liebe Tamar, die Schwester meines Bruders Absalom.", footnotes: ["℘ 1Kö 21,5"] },
      { number: 5, text: "Da sagte Jonadab zu ihm: Leg dich auf dein Lager und stell dich krank! Und kommt dein Vater, um nach dir zu sehen, dann sag zu ihm: Es soll doch meine Schwester Tamar kommen und mir Krankenkost bringen! Sie sollte vor meinen Augen die Krankenkost zubereiten, damit ich es sehen kann. Dann würde ich aus ihrer Hand essen." },
      { number: 6, text: "Und Amnon legte sich hin und stellte sich krank. Und als der König kam, um nach ihm zu sehen, sagte Amnon zum König: Es soll doch meine Schwester Tamar kommen und vor meinen Augen zwei Kuchen zubereiten, damit ich aus ihrer Hand Krankenkost esse!" },
      { number: 7, text: "Da sandte David zu Tamar ins Haus und ließ ihr sagen: Geh doch ins Haus deines Bruders Amnon und bereite ihm Krankenkost!" },
      { number: 8, text: "Und Tamar ging ins Haus ihres Bruders Amnon, während er im Bett lag, und sie nahm den Teig und knetete ihn und bereitete Kuchen vor seinen Augen zu und backte die Kuchen." },
      { number: 9, text: "Und sie nahm die Pfanne und schüttete sie vor ihm aus. Er aber weigerte sich zu essen. Und Amnon sagte: Lasst jedermann von mir hinausgehen! Und jedermann ging von ihm hinaus." },
      { number: 10, text: "Da sagte Amnon zu Tamar: Bring die Krankenkost in die innere Kammer, damit ich aus deiner Hand esse! Und Tamar nahm die Kuchen, die sie zubereitet hatte, und brachte sie ihrem Bruder Amnon in die innere Kammer." },
      { number: 11, text: "Als sie ihm aber etwas zu essen hinreichte, packte er sie und sagte zu ihr: Komm, liege bei mir*, meine Schwester!", footnotes: ["℘ 1Mo 39,12"] },
      { number: 12, text: "Sie aber sagte zu ihm: Nicht doch, mein Bruder! Tu mir keine Gewalt an, denn so handelt man nicht in Israel*! Tu doch diese Schandtat* nicht*!", footnotes: ["℘ 3Mo 18,9.11", "w. diese Torheit; das Wort hat den Beiklang der Gottlosigkeit", "℘ 1Mo 34,7"] },
      { number: 13, text: "Und ich, wohin sollte ich meine Schmach tragen? Du aber, du würdest sein wie einer der Schändlichen* in Israel. Und nun rede doch zum König, denn er wird mich dir nicht vorenthalten!", footnotes: ["w. der Toren"] },
      { number: 14, text: "Er aber wollte nicht auf ihre Stimme hören. Und er überwältigte sie und tat ihr Gewalt an und lag bei ihr*.", footnotes: ["T.; Mas. T.: legte sich zu ihr\n℘ 1Mo 34,2"] },
      { number: 15, text: "Dann aber hasste Amnon sie mit sehr großem Hass. Ja, der Hass, mit dem er sie hasste, war größer als die Liebe, mit der er sie geliebt hatte. Und Amnon sagte zu ihr: Steh auf, geh weg!" },
      { number: 16, text: "Sie aber sagte zu ihm: Nicht doch, mein Bruder! Denn dieses Unrecht ist noch größer als das andere, das du mir angetan hast, wenn du mich jetzt wegjagst*. Aber er wollte nicht auf sie hören.", footnotes: ["so mit LXX; Mas. T.: Werde nicht die Ursache für dieses noch größere Unrecht als das andere, das du mir bereits angetan hast, wenn du mich jetzt wegjagst"] },
      { number: 17, text: "Und er rief seinen Burschen, seinen Diener, und sagte: Jagt die da weg, fort von mir, nach draußen, und verriegele die Tür hinter ihr!" },
      { number: 18, text: "Sie trug aber einen bunten Leibrock*. Denn mit solchen Gewändern kleideten sich die Töchter des Königs, die noch Jungfrauen waren. Und sein Diener brachte sie hinaus und verriegelte die Tür hinter ihr.", footnotes: ["o. einen knöchellangen Leibrock; o. einen Leibrock, dessen Ärmel bis an die Hände reichen"] },
      { number: 19, text: "Da nahm Tamar Asche, streute sie auf ihren Kopf und zerriss den bunten Leibrock*, den sie anhatte, und sie legte ihre Hand auf ihren Kopf* und lief schreiend davon.", footnotes: ["o. einen knöchellangen Leibrock; o. einen Leibrock, dessen Ärmel bis an die Hände reichen\n℘ Kap. 1,2; Jos 7,6", "℘ Jer 2,37"] },
      { number: 20, text: "Und ihr Bruder Absalom sagte zu ihr: War dein Bruder Amnon* mit dir zusammen? Nun denn, meine Schwester, schweig still! Er ist dein Bruder. Nimm dir diese Sache nicht so zu Herzen! Da blieb Tamar, und zwar einsam*, im Haus ihres Bruders Absalom.", heading: "Absaloms Rache und Flucht", footnotes: ["Mas. T.: Aminon; d. i. eine ironisierende Verkleinerungsform", "w. verödet, o. verwüstet"] },
      { number: 21, text: "Als der König David alle diese Dinge hörte*, wurde er sehr zornig*.", footnotes: ["℘ 1Mo 35,22", "℘ 1Mo 34,7"] },
      { number: 22, text: "Absalom aber redete mit Amnon weder Böses noch Gutes*. Denn Absalom hasste Amnon* deshalb, weil er seiner Schwester Tamar Gewalt angetan hatte.", footnotes: ["℘ 1Mo 31,24", "℘ 3Mo 19,17.18"] },
      { number: 23, text: "Und es geschah nach einer Zeit von zwei Jahren, da hatte Absalom Schafscherer* in Baal-Hazor*, das bei Ephraim liegt*, und Absalom lud alle Söhne des Königs ein.", footnotes: ["℘ 1Mo 31,19", "℘ Neh 11,33", "℘ Joh 11,54"] },
      { number: 24, text: "Und Absalom kam zum König und sagte: Sieh doch, dein Knecht hat die Schafscherer! Der König und seine Knechte mögen doch mit deinem Knecht gehen!" },
      { number: 25, text: "Aber der König sagte zu Absalom: Nein, mein Sohn! Wir können doch nicht alle zusammen hingehen. Wir wollen dir nicht zur Last fallen. Und er drängte ihn; aber er wollte nicht gehen, sondern segnete ihn zum Abschied." },
      { number: 26, text: "Da sagte Absalom: Wenn nicht, dann mag doch wenigstens mein Bruder Amnon mit uns gehen*! Der König sagte zu ihm: Wozu soll er mit dir gehen?", footnotes: ["℘ Spr 26,24; Jer 9,7"] },
      { number: 27, text: "Absalom aber drängte ihn. Da schickte er Amnon und alle anderen Söhne des Königs mit ihm." },
      { number: 28, text: "Und Absalom befahl seinen Dienern: Seht doch zu, wenn Amnons Herz vom Wein fröhlich wird* und ich zu euch sage: Erschlagt Amnon! — dann tötet ihn! Fürchtet euch nicht! Ist es nicht so, dass ich es euch befohlen habe? Seid stark und zeigt euch als tapfere Männer!", footnotes: ["℘ Ps 104,15"] },
      { number: 29, text: "Und die Diener Absaloms machten es mit Amnon so, wie Absalom es befohlen hatte*. Da sprangen alle Söhne des Königs auf, und sie stiegen jeder auf sein Maultier und flohen.", footnotes: ["℘ Kap. 12,10; 14,6"] },
      { number: 30, text: "Und es geschah, während sie noch auf dem Weg waren, kam das Gerücht zu David: Absalom hat alle Söhne des Königs erschlagen, und nicht einer von ihnen ist übrig geblieben." },
      { number: 31, text: "Da stand der König auf und zerriss seine Kleider und legte sich auf die Erde*, und alle seine Knechte standen mit zerrissenen Kleidern um ihn herum.", footnotes: ["℘ Kap. 12,16; Jos 7,6"] },
      { number: 32, text: "Da ergriff Jonadab, der Sohn Schimeas, des Bruders Davids, das Wort und sagte: Mein Herr glaube* nicht, dass man all die jungen Männer, die Söhne des Königs, getötet hat, sondern Amnon allein ist tot. Denn auf Absaloms Mund lag das als finsterer Entschluss* von dem Tag an, da er* seiner Schwester Tamar Gewalt angetan hatte.", footnotes: ["w. sage", "o. Denn auf Absaloms Befehl hin geschah das, fest beschlossen,", "d. i. Amnon"] },
      { number: 33, text: "Und nun nehme mein Herr, der König, die Sache nicht so zu Herzen, dass er glaube*, alle Söhne des Königs seien tot, sondern Amnon allein ist tot!", footnotes: ["w. sage"] },
      { number: 34, text: "Und Absalom floh*. Als nun der Diener, der Turmwächter, seine Augen erhob und sah, siehe, da kam viel Volk vom Weg hinter ihm*, von der Seite des Berges.", footnotes: ["℘ Spr 28,17", "Andere Üs. mit Textänderung in Anlehnung an LXX: von der Horonajim-Straße"] },
      { number: 35, text: "Da sagte Jonadab zum König: Siehe, die Söhne des Königs kommen! Wie dein Knecht gesagt hat, so ist es geschehen." },
      { number: 36, text: "Und es geschah, als er zu Ende geredet hatte, siehe, da kamen die Söhne des Königs und erhoben ihre Stimme und weinten. Und auch der König und all seine Knechte brachen in ein sehr großes Weinen aus." },
      { number: 37, text: "Absalom aber war geflohen und ging zu Talmai*, dem Sohn Ammihuds, dem König von Geschur*. Und David* trauerte um seinen Sohn alle Tage.", footnotes: ["d. i. der Vater seiner Mutter Maacha", "℘ Kap. 3,3; 14,13; 15,8", "w. er"] },
      { number: 38, text: "Absalom aber war geflohen und nach Geschur* gegangen. Dort blieb er drei Jahre.", footnotes: ["℘ Kap. 3,3; 14,13; 15,8"] },
      { number: 39, text: "*Seine Flucht hielt den König David davon ab, gegen Absalom auszuziehen*; vielmehr tröstete er sich über Amnon, dass er tot war*.", footnotes: ["Andere üs. mit Textkorr.: Der König David hörte auf, mit Absalom zu hadern, denn er hatte sich über Amnon getröstet, dass er tot war. 1 Und Joab, der Sohn der Zeruja, merkte, dass das Herz des Königs an Absalom hing. 2 Da sandte", "℘ Kap. 14,1", "℘ 1Mo 38,12"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Als nun Joab, der Sohn der Zeruja, erkannte, dass das Herz des Königs auf Absalom gerichtet war*,", heading: "Absaloms Rückkehr und Begnadigung", footnotes: ["℘ Kap. 13,39"] },
      { number: 2, text: "da sandte* Joab nach Tekoa* und ließ von dort eine kluge Frau holen und sagte zu ihr: Stell dich doch wie eine Trauernde und zieh Trauerkleider an und salbe dich nicht mit Öl und benimm dich wie eine Frau, die schon viele Tage über einen Toten trauert*!", footnotes: ["Andere üs. mit Textkorr.: Der König David hörte auf, mit Absalom zu hadern, denn er hatte sich über Amnon getröstet, dass er tot war. 1 Und Joab, der Sohn der Zeruja, merkte, dass das Herz des Königs an Absalom hing. 2 Da sandte", "℘ Kap. 23,26; 2Chr 11,6; Am 1,1", "℘ 1Mo 38,19"] },
      { number: 3, text: "Geh dann zum König hinein und rede zu ihm nach folgendem Wort! Und Joab legte ihr die Worte in den Mund*.", footnotes: ["℘ Esr 8,17"] },
      { number: 4, text: "Und die Frau aus Tekoa kam* zum König. Und sie fiel auf ihr Gesicht zur Erde* und warf sich nieder und sagte: Hilf, König!", footnotes: ["so mit den meisten hebr. Handschr. und den alten Üs.; Mas. T.: sagte", "℘ V. 22.33; Kap. 1,2; 1Sam 20,41"] },
      { number: 5, text: "Und der König sprach zu ihr: Was fehlt dir? Da sagte sie: Ach, ich bin eine Witwe, und mein Mann ist gestorben." },
      { number: 6, text: "Und deine Magd hatte zwei Söhne, und sie rauften sich beide auf dem Feld, und da kein Retter zwischen ihnen war, schlug der eine den andern nieder und tötete ihn*.", footnotes: ["℘ Kap. 13,28.29"] },
      { number: 7, text: "Und siehe, die ganze Sippe ist gegen deine Magd aufgestanden, und sie sagen: Gib den heraus, der seinen Bruder erschlagen hat, damit wir ihn töten für die Seele seines Bruders, den er umgebracht hat, dass wir so auch den Erben ausrotten*! Und so wollen sie meine Kohle auslöschen, die mir übrig geblieben ist, um meinem Mann weder Namen noch Nachkommen* auf der Fläche des Erdbodens zu lassen.", footnotes: ["℘ 5Mo 19,12.13", "w. Rest"] },
      { number: 8, text: "Da sagte der König zu der Frau: Geh in dein Haus! Ich selbst werde deinetwegen Befehl geben." },
      { number: 9, text: "Und die Frau aus Tekoa sagte zum König: Auf mir, mein Herr und König, und auf dem Haus meines Vaters wird nun die Schuld liegen; der König aber und sein Thron werden schuldlos sein!" },
      { number: 10, text: "Da sagte der König: Wer gegen dich redet, den bring zu mir! Er soll dich künftig nicht mehr antasten." },
      { number: 11, text: "Sie aber sagte: Der König gedenke doch des HERRN, deines Gottes, damit der Bluträcher nicht noch mehr Verderben anrichtet und man meinen Sohn nicht ausrottet*! Und er sagte: So wahr der HERR lebt, wenn von den Haaren deines Sohnes eines auf die Erde fällt*!", footnotes: ["℘ 4Mo 35,19", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte, eine Verwünschung, nicht ausgesprochen wurde.\n℘ 1Sam 14,45; 1Kö 1,52"] },
      { number: 12, text: "Und die Frau sagte: Lass doch deine Magd ein Wort zu meinem Herrn, dem König, reden! Er sagte: Rede!" },
      { number: 13, text: "Da sagte die Frau: Und warum beabsichtigst du so etwas gegen das Volk Gottes? Denn da der König dieses Wort geredet hat, ist er einem Schuldbeladenen gleich*, indem der König den von ihm Verstoßenen nicht zurückkehren lässt*.", footnotes: ["so mit der aram. Üs.; Mas. T.: Denn der König rede ja nicht dieses Wort! Einem Schuldbeladenen ist er gleich", "℘ Kap. 13,37.38"] },
      { number: 14, text: "Denn sterben müssen wir* und sind wie Wasser, das auf die Erde geschüttet wird und das man nicht wieder sammeln kann*. Aber Gott will nicht das Leben wegnehmen, sondern er hat die Absicht, dass der Verstoßene nicht auch von ihm weg verstoßen bleibt*.", footnotes: ["℘ Pred 9,5; Hebr 9,27", "℘ Ps 22,15", "℘ 1Kö 11,39; Ps 77,8; Kla 3,31; Hes 18,23"] },
      { number: 15, text: "Nun denn, dass ich gekommen bin, um dieses Wort zu dem König, meinem Herrn, zu reden, geschah, weil das Volk mich in Furcht versetzt hat. Da sagte sich deine Magd: Ich will doch zum König reden, vielleicht wird der König das Wort seiner Sklavin tun." },
      { number: 16, text: "Denn der König wird darauf hören, um seine Sklavin aus der Faust des Mannes zu retten, der mich samt meinem Sohn aus dem Erbteil Gottes ausrotten will*.", footnotes: ["℘ Ps 72,12-14; Spr 16,10"] },
      { number: 17, text: "Und deine Magd sagte sich: Das Wort meines Herrn, des Königs, möge doch zur Beruhigung für mich sein. Denn wie der Engel Gottes*, so ist mein Herr, der König, um das Gute und das Böse anzuhören*. Und der HERR, dein Gott, sei mit dir!*", footnotes: ["℘ Kap. 19,28; 1Sam 29,9", "℘ 1Kö 3,9", "℘ Jos 1,17"] },
      { number: 18, text: "Da antwortete der König und sagte zu der Frau: Verschweige mir doch ja nichts von dem, wonach ich dich jetzt frage! Die Frau sagte: Mein Herr, der König, möge doch reden!" },
      { number: 19, text: "Der König sagte: Ist in alledem die Hand Joabs mit dir*? Da antwortete die Frau und sagte: So wahr deine Seele lebt, mein Herr und König, wenn jemand nach rechts oder nach links ausweichen kann vor allem, was mein Herr, der König, redet*! Ja, dein Knecht Joab, er hat mir Befehl gegeben, und er hat deiner Magd all diese Worte in den Mund gelegt.", footnotes: ["℘ Spr 25,2", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte, eine Verwünschung, nicht ausgesprochen wurde."] },
      { number: 20, text: "Um der Sache ein anderes Gesicht zu geben, hat dein Knecht Joab dieses Wort ausgemacht*. Aber mein Herr ist weise, gleich der Weisheit des Engels Gottes*, dass er alles erkennt, was auf Erden geschieht*.", footnotes: ["o. diese Sache getan", "℘ Kap. 19,28; 1Sam 29,9", "℘ Kap. 18,13"] },
      { number: 21, text: "Und der König sagte zu Joab: Siehe doch, ich tue diese deine Sache*. So geh nun hin, lass den Jungen, den Absalom, zurückkehren!", footnotes: ["Viele hebr. Handschr. überliefern: du hast diese Sache getan"] },
      { number: 22, text: "Da fiel Joab auf sein Angesicht zur Erde* und warf sich nieder und segnete den König*. Und Joab sagte: Heute erkennt dein Knecht, dass ich Gunst gefunden habe in deinen Augen, mein Herr und König, da der König das Wort* seines Knechtes getan hat.", footnotes: ["℘ V. 4.33", "o. dankte dem König; o. pries den König", "o. die Sache"] },
      { number: 23, text: "Und Joab machte sich auf und ging nach Geschur* und brachte Absalom nach Jerusalem zurück.", footnotes: ["℘ Kap. 3,3"] },
      { number: 24, text: "Aber der König sagte: Er soll sich zu seinem Haus wenden, mein Angesicht soll er nicht sehen. Da wandte sich Absalom zu seinem Haus, und das Angesicht des Königs sah er nicht." },
      { number: 25, text: "In ganz Israel aber gab es keinen Mann so schön wie Absalom und so sehr zu rühmen. Von seiner Fußsohle bis zu seinem Scheitel war kein Makel an ihm*.", footnotes: ["℘ 1Sam 9,2; 1Kö 1,6"] },
      { number: 26, text: "Und wenn er sein Haupt scheren ließ — es geschah nämlich am Ende jedes Jahres*, dass er es scheren ließ, denn es war ihm zu schwer, so ließ er es scheren —, dann wog sein Haupthaar zweihundert Schekel nach königlichem Gewicht.", footnotes: ["o. nach Ablauf einer gewissen Zeit"] },
      { number: 27, text: "Und dem Absalom wurden drei Söhne geboren* und eine Tochter, ihr Name war Tamar. Sie war eine Frau von schönem Aussehen*.", footnotes: ["℘ Kap. 18,18", "℘ Kap. 11,2"] },
      { number: 28, text: "Und Absalom wohnte in Jerusalem zwei volle Jahre und hatte das Angesicht des Königs noch nicht gesehen." },
      { number: 29, text: "Da sandte Absalom zu Joab, um ihn zum König zu schicken, aber er wollte nicht zu ihm kommen. Und er sandte noch ein zweites Mal, aber er wollte wieder nicht kommen." },
      { number: 30, text: "Da sagte er zu seinen Knechten: Seht, das Feld* Joabs ist an meiner Seite. Er hat dort Gerste. Geht hin und steckt es in Brand! Und die Knechte Absaloms steckten das Feld in Brand*.", footnotes: ["w. der Losanteil am Land", "℘ Ri 15,4.5"] },
      { number: 31, text: "Da machte Joab sich auf und kam zu Absalom ins Haus und sagte zu ihm: Warum haben deine Knechte das Feld, das mir gehört, in Brand gesteckt?" },
      { number: 32, text: "Und Absalom sagte zu Joab: Siehe, ich hatte zu dir geschickt und dir sagen lassen: Komm her, ich will dich zum König schicken, um ihm zu sagen: Wozu bin ich von Geschur hergekommen? Besser wäre es für mich, ich wäre noch dort. Jetzt aber will ich das Angesicht des Königs sehen. Und wenn es an mir eine Schuld gibt, dann soll er mich töten*.", footnotes: ["℘ 1Sam 20,8; 1Jo 1,10"] },
      { number: 33, text: "Da begab sich Joab zum König und berichtete es ihm. Und er rief Absalom. Der kam zum König und warf sich vor ihm nieder und fiel auf sein Angesicht zur Erde nieder* vor dem König, und der König küsste Absalom*.", footnotes: ["℘ 1Kö 1,53", "℘ Lk 15,20"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und es geschah danach, da schaffte sich Absalom Wagen und Pferde an und fünfzig Mann, die vor ihm herliefen*.", heading: "Absaloms Aufstand gegen David", footnotes: ["℘ 1Sam 8,11; 1Kö 1,5"] },
      { number: 2, text: "Und frühmorgens machte Absalom sich auf und stellte sich an den Rand des Weges zum Tor. Und es geschah: Jeden Mann, der einen Rechtsstreit hatte* und zum König kam, um eine Rechtsentscheidung zu suchen, den rief Absalom an und sagte: Aus welcher Stadt bist du? Und sagte der: Dein Knecht ist aus einem der Stämme Israels! —", footnotes: ["℘ 5Mo 17,8"] },
      { number: 3, text: "dann sagte Absalom zu ihm: Siehe, deine Anliegen sind gut und recht; aber du hast beim König niemanden, der dich anhört*.", footnotes: ["℘ Kap. 8,15"] },
      { number: 4, text: "Dann sagte Absalom weiter: Würde man mich doch als Richter im Land einsetzen! Bei mir würde jedermann Eingang finden, der einen Rechtsstreit hat und Rechtsentscheidung sucht; ich würde ihn gerecht sprechen*!", footnotes: ["℘ Ri 9,29"] },
      { number: 5, text: "Und es geschah, wenn jemand sich ihm näherte, um sich vor ihm niederzuwerfen, dann streckte er seine Hand aus und ergriff ihn und küsste ihn." },
      { number: 6, text: "Und Absalom handelte auf diese Weise an allen Israeliten, die zum König kamen, um eine Rechtsentscheidung zu suchen. So stahl Absalom das Herz der Männer von Israel*.", footnotes: ["℘ Dan 11,21; Röm 16,18"] },
      { number: 7, text: "Und es geschah am Ende der vierzig* Jahre, da sagte Absalom zum König: Lass mich doch hingehen und in Hebron mein Gelübde erfüllen, das ich dem HERRN gelobt habe.", footnotes: ["mit einer Lesart der LXX: vier"] },
      { number: 8, text: "Denn als ich in Geschur in Aram wohnte*, tat dein Knecht ein Gelübde und sagte: Wenn der HERR mich wirklich nach Jerusalem zurückbringt, dann will ich dem HERRN dienen*!", footnotes: ["℘ Kap. 13,38", "℘ 1Mo 28,21"] },
      { number: 9, text: "Da sagte der König zu ihm: Geh hin in Frieden!* Und er machte sich auf und ging nach Hebron.", footnotes: ["℘ 1Sam 1,17"] },
      { number: 10, text: "Und Absalom sandte Geheimboten in alle Stämme Israels und ließ sagen: Sobald ihr den Schall des Horns hört, sollt ihr rufen: Absalom ist König in Hebron*!", footnotes: ["℘ 1Kö 1,11; 2Kö 9,13"] },
      { number: 11, text: "Und mit Absalom gingen zweihundert Mann aus Jerusalem. Sie waren eingeladen worden* und gingen in ihrer Arglosigkeit mit; und sie hatten nichts von der ganzen Sache erkannt.", footnotes: ["d. h. zur Opfermahlzeit"] },
      { number: 12, text: "Auch sandte Absalom hin und ließ den Giloniter Ahitofel kommen, den Ratgeber Davids*, aus seiner Stadt, aus Gilo*, als er bereits die Opfer schlachtete*. So wurde die Verschwörung stark, und das Volk bei Absalom wurde laufend zahlreicher.", footnotes: ["℘ V. 31; Kap. 16,20.23; 1Chr 27,33; Ps 41,10", "℘ Kap. 17,23; 23,34; Jos 15,51", "℘ Spr 15,8; Pred 4,17; Jer 6,20"] },
      { number: 13, text: "Und ein Bote kam zu David und sagte: Das Herz der Männer von Israel steht hinter Absalom*.", heading: "Davids Flucht aus Jerusalem", footnotes: ["℘ Ri 9,3"] },
      { number: 14, text: "Da sagte David zu all seinen Knechten, die bei ihm in Jerusalem waren: Macht euch auf und lasst uns fliehen*! Denn sonst gibt es für uns kein Entkommen vor Absalom. Beeilt euch wegzukommen, damit er nicht eilends kommt und uns noch einholt und das Unheil über uns bringt und die Stadt mit der Schärfe des Schwertes schlägt!", footnotes: ["℘ Ps 3,1"] },
      { number: 15, text: "Da sagten die Knechte des Königs zum König: Ganz wie mein Herr, der König, entscheidet* — siehe, wir sind deine Knechte*!", footnotes: ["w. wählt", "℘ Kap. 9,11; 1Sam 14,7"] },
      { number: 16, text: "So zog denn der König hinaus* und sein ganzes Haus in seinem Gefolge. Und der König ließ zehn Nebenfrauen zurück, das Haus zu hüten*.", footnotes: ["℘ Kap. 19,10; Ps 3,1", "℘ Kap. 16,21"] },
      { number: 17, text: "Als nun der König hinausgezogen war und alles Volk in seinem Gefolge, machten sie halt beim letzten Haus." },
      { number: 18, text: "Und alle seine Knechte zogen an seiner Seite vorüber, und zwar alle Kreter und alle Pleter* und alle Gatiter, sechshundert Mann, die aus Gat in seinem Gefolge gekommen waren*, zogen vor dem König vorüber.", footnotes: ["℘ Kap. 8,18", "℘ 1Sam 27,4.7"] },
      { number: 19, text: "Da sagte der König zu dem Gatiter Ittai*: Warum willst auch du mit uns gehen? Kehr um und bleib bei dem König*, denn du bist ein Fremder, ja, du musstest sogar aus deinem Heimatort in die Verbannung gehen*.", footnotes: ["℘ Kap. 18,2", "℘ Rt 1,15", "w. ja, du bist sogar ein in die Verbannung Gegangener in Bezug auf deinen Ort"] },
      { number: 20, text: "Gestern bist du gekommen, und heute sollte ich dich aufjagen, mit uns zu gehen? Ich aber muss gehen, wohin ich eben gehe. Kehr um und führe deine Brüder zurück! Güte und Treue seien mit dir*!*", footnotes: ["o. Kehr um und erstatte deinen Brüdern bei dir Güte und Treue", "℘ Kap. 2,5.6; Ps 61,8"] },
      { number: 21, text: "Aber Ittai antwortete dem König und sagte: So wahr der HERR lebt und mein Herr, der König, lebt, wahrlich, an dem Ort, wo mein Herr, der König, sein wird, sei es zum Tod, sei es zum Leben, nur dort wird dein Knecht sein*!", footnotes: ["℘ Rt 1,16.17; Spr 18,24"] },
      { number: 22, text: "Da sagte David zu Ittai: Komm und zieh vorüber! Und Ittai, der Gatiter, zog vorüber mit allen seinen Männern und dem ganzen Tross*, der bei ihm war.", footnotes: ["Das Wort bezeichnet alle nicht oder wenig Marschfähigen eines Stammes, also Kinder, Alte und Frauen."] },
      { number: 23, text: "Und das ganze Land weinte mit lauter Stimme*, während das ganze Kriegsvolk vorüberging. Dann ging der König über den Bach Kidron*, und das ganze Kriegsvolk zog hinüber auf dem Weg zur Wüste hin.", footnotes: ["℘ Lk 23,27", "℘ 1Kö 2,37; Joh 18,1"] },
      { number: 24, text: "Und siehe, auch Zadok war da und mit ihm alle Leviten; die trugen die Lade des Bundes Gottes*. Und sie stellten die Lade Gottes hin*, und Abjatar* brachte Brandopfer dar, bis das ganze Kriegsvolk aus der Stadt vollständig hinübergezogen war.", footnotes: ["℘ 4Mo 4,15", "T.; Mas. T.: und sie leerten die Lade Gottes aus", "℘ Kap. 8,17; 1Sam 22,20; 1Kö 2,26"] },
      { number: 25, text: "Und der König sagte zu Zadok: Bring die Lade Gottes in die Stadt zurück! Wenn ich Gunst finde in den Augen des HERRN*, dann wird er mich zurückbringen und mich ihn und seine Stätte* wiedersehen lassen*.", footnotes: ["℘ 2Mo 33,13", "o. sie und ihre Stätte; o. sie und seine Stätte", "℘ Ps 43,3; 84,3"] },
      { number: 26, text: "Wenn er aber so spricht: Ich habe kein Gefallen an dir — hier bin ich, er mag mit mir tun, wie es gut ist in seinen Augen!*", footnotes: ["℘ Kap. 10,12; 19,28; Jos 9,25"] },
      { number: 27, text: "Und der König sagte zum Priester Zadok: Siehst du das ein*? Kehre in Frieden in die Stadt zurück und dein Sohn Ahimaaz und Jonatan, der Sohn Abjatars*, eure beiden Söhne, mit euch.", footnotes: ["o. Bist du nicht der Seher", "℘ Kap. 17,17; 18,19; 1Kö 1,42; 1Chr 5,34"] },
      { number: 28, text: "Seht, ich will an den Übergängen in der Wüste warten, bis ein Wort von euch kommt, mir Nachricht zu geben." },
      { number: 29, text: "So brachten Zadok und Abjatar die Lade Gottes nach Jerusalem zurück, und sie blieben dort." },
      { number: 30, text: "David aber ging die Anhöhe der Olivenbäume* hinauf und weinte im Gehen; und sein Haupt war verhüllt*, und er ging barfuß*. Und alles Volk, das bei ihm war, sie hatten jeder sein Haupt verhüllt und gingen unter ständigem Weinen hinauf.", footnotes: ["d. i. den Ölberg\n℘ Sach 14,4; Lk 19,29.37", "℘ Kap. 19,5; Est 6,12; Jer 14,3", "℘ Hes 24,17"] },
      { number: 31, text: "Und man berichtete David: Ahitofel ist unter den Verschwörern bei Absalom*. Da sagte David: Mach doch, HERR, den Rat Ahitofels zur Torheit*!", footnotes: ["℘ V. 12; Kap. 17,14.23", "℘ Ps 55,10"] },
      { number: 32, text: "Und es geschah, als David auf den Gipfel gekommen war, wo man sich vor Gott niederwirft, siehe, da kam ihm der Arkiter Huschai* entgegen mit zerrissenem Leibrock und Erde auf seinem Kopf*.", footnotes: ["℘ Kap. 16,16; 17,5; Jos 16,2; 1Chr 27,33", "℘ Kap. 1,2"] },
      { number: 33, text: "Und David sagte zu ihm: Wenn du mit mir weiterziehst, dann wirst du mir zur Last werden." },
      { number: 34, text: "Wenn du aber in die Stadt zurückkehrst und zu Absalom sagst: Dein Knecht, König, will ich sein; früher war ich der Knecht deines Vaters, jetzt aber will ich dein Knecht sein*! — dann kannst du mir den Rat Ahitofels zunichte machen*.", footnotes: ["℘ Kap. 16,19", "℘ Kap. 17,7"] },
      { number: 35, text: "Und sind dort nicht die Priester Zadok und Abjatar bei dir? Und es soll geschehen, alles, was du aus dem Haus des Königs hörst, sollst du den Priestern Zadok und Abjatar mitteilen*.", footnotes: ["℘ Kap. 17,15.16"] },
      { number: 36, text: "Siehe, ihre beiden Söhne sind dort bei ihnen, Ahimaaz*, der Sohn des Zadok, und Jonatan*, der Sohn des Abjatar. So sendet mir durch sie alles, was ihr hört!", footnotes: ["℘ Kap. 17,17; 18,19; 1Kö 1,42; 1Chr 5,34", "℘ Kap. 17,17; 18,19; 1Kö 1,42; 1Chr 5,34"] },
      { number: 37, text: "Da begab sich Huschai*, der Freund Davids, in die Stadt. Absalom aber zog gerade in Jerusalem ein*.", footnotes: ["℘ Kap. 16,16; 17,5; Jos 16,2; 1Chr 27,33", "℘ Kap. 16,15"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und als David von dem Gipfel ein wenig weitergegangen war, siehe, da kam Ziba*, der Knecht Mefi-Boschets, ihm entgegen mit einem Paar gesattelter Esel, und auf ihnen zweihundert Brote und hundert Rosinenkuchen und hundert Früchte vom Sommerobst und ein Schlauch Wein*.", heading: "Ziba verleumdet Mefi-Boschet — David wird von Schimi verflucht", footnotes: ["℘ Kap. 9,2", "℘ 1Sam 25,18"] },
      { number: 2, text: "Und der König sagte zu Ziba: Was willst du damit? Ziba sagte: Die Esel sind für das Haus des Königs zum Reiten und das Brot und das Sommerobst zum Essen für die Burschen und der Wein zum Trinken für den, der in der Wüste müde wird*.", footnotes: ["℘ Kap. 17,29"] },
      { number: 3, text: "Und der König sagte: Und wo ist der Sohn deines Herrn? Ziba sagte zum König: Siehe, er ist in Jerusalem geblieben, denn er sagte: Heute wird mir das Haus Israel das Königtum meines Vaters zurückgeben*!", footnotes: ["℘ Kap. 19,28"] },
      { number: 4, text: "Da sagte der König zu Ziba: Siehe, dein sei alles, was Mefi-Boschet gehört*! Ziba sagte: Ich beuge mich nieder. Möge ich Gunst finden in deinen Augen, mein Herr und König!", footnotes: ["℘ Kap. 9,9; Joh 7,51"] },
      { number: 5, text: "Und als der König David nach Bahurim* kam, siehe, da kam von dort ein Mann von der Sippe des Hauses Saul heraus, sein Name war Schimi, der Sohn des Gera*. Er kam unter ständigem Fluchen heraus*", footnotes: ["℘ Kap. 3,16; 23,31", "℘ Kap. 19,17", "℘ Kap. 19,22; 2Mo 22,27"] },
      { number: 6, text: "und warf mit Steinen nach David und nach allen Knechten des Königs David, obwohl alles Kriegsvolk und alle Helden zu seiner Rechten und zu seiner Linken gingen." },
      { number: 7, text: "Und so schrie Schimi, als er fluchte: Hinaus, hinaus*, du Blutmensch, du Ruchloser!", footnotes: ["℘ Ps 3,2; 55,4"] },
      { number: 8, text: "Der HERR hat die ganze Blutschuld am Haus Sauls, an dessen Stelle du König geworden bist, auf dich zurückgebracht, und der HERR hat das Königtum in die Hand deines Sohnes Absalom gegeben! Siehe, jetzt bist du in deinem Unglück, denn ein Blutmensch bist du*!", footnotes: ["℘ Kap. 19,19-23; 1Kö 2,8.44; Ps 7,4-6; Spr 26,2"] },
      { number: 9, text: "Da sagte Abischai, der Sohn der Zeruja, zum König: Warum soll dieser tote Hund* meinem Herrn, dem König, fluchen dürfen? Lass mich doch hinübergehen und ihm den Kopf abhauen*!", footnotes: ["℘ Kap. 3,8", "℘ 1Sam 26,8"] },
      { number: 10, text: "Aber der König sagte: Was habe ich mit euch zu tun, ihr Söhne der Zeruja*? Ja, soll er doch fluchen! Denn wenn der HERR ihm gesagt hat*: Fluche David! — wer darf dann sagen: Warum tust du das*?", footnotes: ["℘ Kap. 19,23", "o. Ganz so soll er fluchen, wenn der HERR ihm gesagt hat", "℘ 1Sam 26,19; Hi 9,12; Kla 3,37.38; Röm 9,20"] },
      { number: 11, text: "Und David sagte zu Abischai und zu all seinen Knechten: Siehe, mein Sohn, der aus meinem Leib hervorgegangen ist, trachtet mir nach dem Leben*; wie viel mehr jetzt dieser Benjaminiter*! Lasst ihn, mag er fluchen! Denn der HERR hat es ihm gewiss gesagt.", footnotes: ["℘ Kap. 12,11", "℘ Kap. 20,1"] },
      { number: 12, text: "Vielleicht wird der HERR mein Elend ansehen*, und der HERR wird mir Gutes zuwenden anstelle seines* Fluchs an diesem Tag*.", footnotes: ["so mit LXX, Vulg. und der syr. Üs.; mit der Schreibform des Mas. T.: meine Schuld ansehen; mit der Leseform: mein Auge ansehen, d. h. meinen Anblick\n℘ 1Mo 29,32; Ps 10,14; 25,18.19", "d. i. Schimis", "℘ 5Mo 23,6; Ps 109,28; Joe 2,14; Röm 8,28; 1Petr 2,23"] },
      { number: 13, text: "Und David und seine Männer gingen ihres Weges, während Schimi an der Seite des Berges neben ihm herging, im Gehen fluchte, mit Steinen nach ihm warf, immer neben ihm her, und ihn mit Erde bewarf." },
      { number: 14, text: "Und der König und alles Volk, das bei ihm war, kamen erschöpft am Wasser* an*. Dort erholte er sich wieder*.", footnotes: ["LXX: am Jordan", "℘ Kap. 17,2", "w. Dort atmete er auf"] },
      { number: 15, text: "Absalom aber und alles Volk, die Männer von Israel, kamen nach Jerusalem*, und Ahitofel war bei ihm.", heading: "Ahitofel und Huschai als Ratgeber Absaloms", footnotes: ["℘ Kap. 15,32.37"] },
      { number: 16, text: "Und es geschah, als Huschai, der Arkiter, der Freund Davids, zu Absalom kam*, da sagte Huschai zu Absalom: Es lebe der König! Es lebe der König!*", footnotes: ["℘ Kap. 15,32.37", "℘ 1Kö 1,25.39"] },
      { number: 17, text: "Und Absalom sagte zu Huschai: Das ist also deine Liebe* zu deinem Freund? Warum bist du nicht mit deinem Freund gegangen?", footnotes: ["w. Güte, o. Gnade"] },
      { number: 18, text: "Und Huschai sagte zu Absalom: Nein, sondern wen der HERR erwählt hat und dieses Volk und alle Männer von Israel, dem will ich angehören, und bei ihm will ich bleiben." },
      { number: 19, text: "Und zum andern, wem sollte ich dienen? Etwa nicht vor seinem Sohn? Wie ich vor deinem Vater gedient habe, so will ich auch vor dir sein*.", footnotes: ["℘ Kap. 15,34"] },
      { number: 20, text: "Und Absalom sagte zu Ahitofel: Gebt einen Rat, was wir tun sollen*!", footnotes: ["℘ Kap. 15,12"] },
      { number: 21, text: "Und Ahitofel sagte zu Absalom: Geh zu den Nebenfrauen deines Vaters ein, die er zurückgelassen hat, das Haus zu hüten*! Wenn dann ganz Israel hört, dass du dich bei deinem Vater stinkend gemacht hast*, werden die Hände all derer, die mit dir sind, stark werden.", footnotes: ["℘ Kap. 15,16", "℘ 1Mo 34,30; 2Sam 10,6; 1Kö 2,22"] },
      { number: 22, text: "Da schlug man für Absalom das Zelt auf dem Dach auf, und Absalom ging ein zu den Nebenfrauen seines Vaters vor den Augen von ganz Israel*.", footnotes: ["℘ Kap. 12,11.12; 20,3; 1Mo 35,22"] },
      { number: 23, text: "Der Rat Ahitofels aber, den er in jenen Tagen gab, war, als wenn man das Wort Gottes befragte; so viel galt jeder Rat Ahitofels sowohl bei David als auch bei Absalom*.", footnotes: ["℘ Kap. 15,12"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und Ahitofel sagte zu Absalom: Lass mich doch zwölftausend Mann auswählen und mich aufmachen und noch diese Nacht David nachjagen!", heading: "Ahitofels Rat wird verworfen, der Rat Huschais angenommen — Amasa, der Feldhauptmann Absaloms" },
      { number: 2, text: "Und ich werde über ihn kommen, solange er noch müde ist und schlaffe Hände hat*, und ihn in Schrecken versetzen. Dann wird das ganze Kriegsvolk, das bei ihm ist, fliehen, und ich werde den König allein erschlagen*.", footnotes: ["℘ Kap. 16,14", "℘ 1Kö 22,31; Neh 4,5"] },
      { number: 3, text: "So werde ich das ganze Volk zu dir zurückbringen. So viel wie die Rückkehr der Gesamtheit bedeutet der Mann, den du suchst: Das ganze Volk wird Frieden haben.*", footnotes: ["LXX: So werde ich das ganze Volk zu dir zurückbringen, wie die Braut zu ihrem Mann zurückkehrt. Nur die Seele eines einzigen Mannes suchst du, und das ganze Volk wird Frieden haben."] },
      { number: 4, text: "Und das Wort war recht in den Augen Absaloms und in den Augen aller Ältesten von Israel." },
      { number: 5, text: "Und Absalom sagte: Ruf doch auch Huschai, den Arkiter, damit wir hören, was auch er zu sagen hat*!", footnotes: ["℘ Kap. 15,31-37"] },
      { number: 6, text: "Da kam Huschai zu Absalom. Und Absalom sagte zu ihm: Solch ein Wort hat Ahitofel geredet. Sollen wir sein Wort ausführen? Wenn nicht, dann rede du!" },
      { number: 7, text: "Da sagte Huschai zu Absalom: Nicht gut ist der Rat, den Ahitofel diesmal gegeben hat*.", footnotes: ["℘ Kap. 15,31-37"] },
      { number: 8, text: "Und Huschai sagte weiter: Du kennst ja selbst deinen Vater und seine Männer: Helden sind sie und voll erbitterten Mutes* wie eine Bärin auf dem Feld*, der man die Jungen geraubt hat. Und dein Vater ist ein Kriegsmann; er wird mit dem Volk keine Nachtruhe halten.", footnotes: ["w. bitterer Seele", "℘ Spr 17,12; Hos 13,8"] },
      { number: 9, text: "Siehe, er hat sich jetzt in irgendeinem Loch oder sonst an einem Ort versteckt*. Und es wird geschehen, wenn zu Anfang einige von ihnen* fallen, so wird jeder, der es hört, sagen: Das Volk, das Absalom nachfolgt, hat eine Niederlage erlitten!", footnotes: ["℘ 1Sam 23,22", "d. h. von Absaloms Leuten"] },
      { number: 10, text: "Dann würde jeder — mag er auch ein tapferer Mann sein, dessen Herz wie ein Löwenherz ist* — ganz sicher verzagen. Denn ganz Israel hat erkannt, dass dein Vater ein Held ist und die, die bei ihm sind, tapfere Männer.", footnotes: ["℘ 1Sam 16,18"] },
      { number: 11, text: "Vielmehr rate ich: Ganz Israel soll sich zu dir versammeln, von Dan bis Beerscheba*, so zahlreich wie der Sand, der am Meer ist*, und du selber musst* mit in den Kampf ziehen.", footnotes: ["℘ Kap. 3,10", "℘ 1Mo 22,17; Jos 11,4", "w. dein Angesicht muss"] },
      { number: 12, text: "Kommen wir dann zu ihm an einen der Orte, wo immer er sich auch befinden mag, so werden wir uns auf ihn niederlassen, wie der Tau auf den Erdboden fällt. Dann wird von ihm und von all den Männern, die bei ihm sind, auch nicht einer übrig bleiben." },
      { number: 13, text: "Und wenn er sich in eine Stadt zurückzieht, dann soll ganz Israel Seile an jene Stadt heranschaffen, und wir schleppen sie* ins Flusstal, bis dort auch nicht ein Steinchen von ihr mehr gefunden wird.", footnotes: ["so mit LXX, Vulg., der aram. und syr. Üs.; Mas. T.: ihn"] },
      { number: 14, text: "Da sagten Absalom und alle Männer von Israel: Der Rat Huschais, des Arkiters, ist besser als der Rat Ahitofels. Der HERR aber hatte es so angeordnet, um den guten Rat Ahitofels* zunichte zu machen*, damit der HERR das Unheil über Absalom brächte*.", footnotes: ["℘ Kap. 15,31-37", "℘ Kap. 15,31; Hi 5,12.13; 12,17; Spr 19,21", "℘ Jos 11,20; 2Chr 10,15"] },
      { number: 15, text: "Und Huschai sagte zu den Priestern Zadok und Abjatar*: So und so hat Ahitofel dem Absalom und den Ältesten von Israel geraten, und so und so habe ich selbst geraten.", footnotes: ["℘ Kap. 8,17"] },
      { number: 16, text: "So sendet nun eilends hin und berichtet David und sagt: Übernachte nicht diese Nacht bei den Übergängen in der Wüste, sondern geh auf jeden Fall hinüber, damit nicht der König und das ganze Kriegsvolk, das bei ihm ist, verschlungen wird*!", footnotes: ["℘ Kap. 15,35.36"] },
      { number: 17, text: "Jonatan aber und Ahimaaz* standen bei En-Rogel*. Und als die Magd hinging und ihnen berichtete, da gingen sie ihrerseits hin und berichteten dem König David. Denn sie durften sich nicht sehen lassen und vermieden es darum, in die Stadt zu kommen*.", footnotes: ["℘ Kap. 15,35.36", "d. h. Walkerquelle\n℘ Jos 15,7; 1Kö 1,9", "o. dadurch, dass sie in die Stadt kamen"] },
      { number: 18, text: "Ein junger Mann aber sah sie und berichtete es Absalom. Da gingen die beiden eilends fort und kamen in das Haus eines Mannes in Bahurim*; der hatte einen Brunnen in seinem Hof, dort stiegen sie hinein.", footnotes: ["℘ Kap. 3,16"] },
      { number: 19, text: "Da nahm die Frau eine Decke und breitete sie über die Brunnenöffnung und streute Getreidekörner darüber aus, so dass man nichts erkennen konnte." },
      { number: 20, text: "Und die Knechte Absaloms kamen zu der Frau ins Haus und sagten: Wo sind Ahimaaz und Jonatan? Da sagte die Frau zu ihnen: Sie sind von hier zum Wasser weitergegangen*. Da suchten sie dort, aber sie fanden sie nicht und kehrten nach Jerusalem zurück.", footnotes: ["so in Anlehnung an die syr. Üs.; Mas. T.: Sie sind über die Wasseransammlung gegangen\n℘ Jos 2,4-6"] },
      { number: 21, text: "Und es geschah, nachdem sie weggegangen waren, stiegen die beiden* aus dem Brunnen herauf und gingen hin und berichteten dem König David. Und sie sagten zu David: Macht euch auf und geht eilends über das Wasser, denn so hat Ahitofel gegen euch geraten!", footnotes: ["w. sie"] },
      { number: 22, text: "Da machte sich David auf und das ganze Volk, das bei ihm war, und sie gingen über den Jordan. Bis der Morgen hell wurde, fehlte auch nicht einer, der nicht über den Jordan gegangen wäre." },
      { number: 23, text: "Als aber Ahitofel sah, dass sein Rat nicht ausgeführt worden war, sattelte er den Esel und machte sich auf und ging in sein Haus*, in seine Stadt*; und er bestellte sein Haus und erhängte sich*. Und er starb* und wurde im Grab seines Vaters begraben.", footnotes: ["℘ 2Kö 20,1", "℘ Kap. 15,12", "℘ Mt 27,5", "℘ 1Kö 16,18"] },
      { number: 24, text: "Und David kam nach Mahanajim*. Absalom aber ging über den Jordan, er und alle Männer von Israel mit ihm.", footnotes: ["℘ Kap. 2,8"] },
      { number: 25, text: "Und Absalom hatte Amasa an Joabs Stelle über das Heer eingesetzt*. Amasa war aber der Sohn eines Mannes, dessen Name Jitra* war, des Israeliten*, der zu Abigal eingegangen war, der Tochter des Nahasch, einer Schwester der Zeruja, der Mutter Joabs*.", footnotes: ["℘ Kap. 19,14; 1Chr 12,19", "sonst Jeter", "LXX liest mit 1Chr 2,17: des Ismaeliters", "℘ 1Chr 2,17"] },
      { number: 26, text: "Und Israel und Absalom lagerten sich im Land Gilead." },
      { number: 27, text: "Und es geschah, als David nach Mahanajim gekommen war, da kamen Schobi, der Sohn des Nahasch, aus Rabba, der Stadt der Söhne Ammon*, und Machir, der Sohn Ammiëls, aus Lo-Dabar*, und Barsillai, der Gileaditer*, aus Roglim.", heading: "Unterstützung für David in Mahanajim", footnotes: ["℘ Kap. 10,1.2; 12,26", "℘ Kap. 9,4", "℘ Kap. 19,32.33; 1Kö 2,7; Esr 2,61"] },
      { number: 28, text: "Betten und Becken und Töpfergefäße, Weizen und Gerste und Mehl, geröstete Körner und Bohnen und Linsen und Geröstetes*", footnotes: ["w. geröstete Körner"] },
      { number: 29, text: "und Honig und Rahm und Schafe und Kuhkäse brachten sie zu David und zu dem Kriegsvolk, das bei ihm war, zum Essen. Denn sie sagten sich: Das Volk ist hungrig und erschöpft und durstig in der Wüste*.", footnotes: ["℘ Kap. 16,2; Ps 107,5"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und David musterte das Kriegsvolk, das bei ihm war, und setzte über sie Oberste über Tausend und Oberste über Hundert ein*.", heading: "Davids Vorbereitung auf den Entscheidungskampf", footnotes: ["℘ 2Mo 18,21; 5Mo 20,9"] },
      { number: 2, text: "Und David sandte das Volk aus: ein Drittel unter Joab*, ein Drittel unter Abischai*, dem Sohn der Zeruja, dem Bruder Joabs, und ein Drittel unter Ittai*, dem Gatiter. Und der König sagte zu dem Kriegsvolk: Auch ich will mit euch ausziehen!", footnotes: ["w. in der Hand Joabs\n℘ Kap. 8,16; 1Kö 2,28", "℘ Kap. 10,9.10; 21,17; 23,18", "℘ Kap. 15,19"] },
      { number: 3, text: "Das Kriegsvolk aber sagte: Du sollst nicht mit ausziehen*. Denn wenn wir fliehen müssen, werden sie sich um uns keine Mühe machen*. Selbst wenn die Hälfte von uns stirbt, werden sie sich um uns keine Mühe machen*. Denn du bist wie zehntausend von uns*. Darum ist es jetzt besser, wenn du uns von der Stadt aus zur Hilfe wirst.", footnotes: ["℘ Kap. 21,17", "w. nicht auf uns das Herz richten", "w. nicht auf uns das Herz richten", "so mit 2 hebr. Handschr. und LXX; Mas. T.: Denn jetzt sind zehntausend wie wir"] },
      { number: 4, text: "Da sagte der König zu ihnen: Was gut ist in euren Augen, will ich tun. Und der König stellte sich an die Seite des Tores, und das ganze Kriegsvolk zog aus zu je hundert und je tausend." },
      { number: 5, text: "Und der König befahl Joab und Abischai und Ittai: Geht mir schonend um mit dem Jungen, mit Absalom! Und das ganze Kriegsvolk hörte es, als der König allen Obersten wegen Absalom Befehl gab." },
      { number: 6, text: "Und das Kriegsvolk zog aus ins Feld, Israel entgegen; und der Kampf entspann sich im Wald Ephraim.", heading: "Absaloms Niederlage und Tod" },
      { number: 7, text: "Dort wurde das Kriegsvolk Israels vor den Knechten Davids geschlagen, und die Niederlage war dort groß an jenem Tag: 20 000 Mann." },
      { number: 8, text: "Und der Kampf breitete sich dort aus über das ganze Land*. Und der Wald fraß mehr vom Volk, als das Schwert gefressen hatte* an jenem Tag.", footnotes: ["w. über die Fläche des ganzen Landes", "℘ Spr 24,21.22"] },
      { number: 9, text: "Und Absalom geriet vor die Knechte Davids. Absalom ritt aber auf einem Maultier. Und das Maultier kam unter die verschlungenen Zweige einer großen Terebinthe. Da verfing sich sein Kopf in der Terebinthe, und er schwebte zwischen Himmel und Erde. Das Maultier aber, das unter ihm war, lief weiter." },
      { number: 10, text: "Das sah ein Mann und meldete Joab Folgendes: Siehe, ich habe Absalom an einer Terebinthe hängen sehen*.", footnotes: ["℘ Hi 31,3"] },
      { number: 11, text: "Da sagte Joab zu dem Mann, der ihm das meldete: Wie, du hast ihn gesehen? Und warum hast du ihn dort nicht sofort zu Boden geschlagen? Und an mir wäre es, dir zehn Schekel Silber und einen Gürtel zu geben." },
      { number: 12, text: "Aber der Mann sagte zu Joab: Auch wenn ich tausend Schekel Silber auf meinen Händen wöge, würde ich meine Hand nicht gegen den Sohn des Königs ausstrecken. Denn vor unseren Ohren hat der König dir und Abischai und Ittai befohlen: Seid vorsichtig, wer es auch sei, mit* dem Jungen, mit Absalom!", footnotes: ["einige hebr. Handschr., LXX, Vulg., die syr. und aram. Üs.: Seid mir vorsichtig mit"] },
      { number: 13, text: "Oder hätte ich heimtückisch gegen sein Leben gehandelt* — und es bleibt ja keine Sache vor dem König verborgen* —, dann würdest du dich heraushalten*.", footnotes: ["so mit der Schreibform des Mas. T.; mit der Leseform: hätte ich an meiner Seele Betrug geübt", "℘ Kap. 14,20", "o. dich auf die gegenüberliegende Seite stellen"] },
      { number: 14, text: "Da sagte Joab: Ich will nicht so viel Zeit verlieren* vor dir. Und er nahm drei Stäbe in seine Hand und stieß sie Absalom ins Herz, während er mitten im Geäst der Terebinthe* noch lebendig hing*.", footnotes: ["w. Ich will nicht so lange warten", "w. und stieß sie in Absaloms Herz, während er im Herzen der Terebinthe", "℘ Kap. 12,10; 19,11; Hi 20,5; Ps 37,35.36"] },
      { number: 15, text: "Dann stellten sich zehn Burschen, Waffenträger Joabs, ringsum auf, erschlugen Absalom und töteten ihn*.", footnotes: ["℘ Kap. 12,10; 19,11; Hi 20,5; Ps 37,35.36"] },
      { number: 16, text: "Und Joab stieß ins Horn, da kehrte das Kriegsvolk von der Verfolgung Israels zurück*; denn Joab wollte das Kriegsvolk schonen.", footnotes: ["℘ Kap. 2,28"] },
      { number: 17, text: "Und sie nahmen Absalom und warfen ihn in die große Grube im Wald und errichteten über ihm einen sehr großen Steinhaufen*. Ganz Israel aber floh, jeder in sein Zelt*.", footnotes: ["℘ Jos 7,26", "℘ Kap. 19,9; 20,22"] },
      { number: 18, text: "Absalom aber hatte es unternommen und hatte noch zu seinen Lebzeiten einen Gedenkstein* für sich aufgerichtet*, der im Königstal ist*. Denn er sagte: Ich habe keinen Sohn*, meinen Namen in Erinnerung zu halten. Und er hatte den Gedenkstein* nach seinem Namen genannt. Und man nennt ihn das Denkmal Absaloms* bis auf diesen Tag.", footnotes: ["hebr. mazzeba; d. i. ein aufrecht hingestellter Stein, der kultisch verehrt wurde", "℘ 1Sam 15,12", "℘ 1Mo 14,17", "℘ Kap. 14,27", "hebr. mazzeba; d. i. ein aufrecht hingestellter Stein, der kultisch verehrt wurde", "w. Absaloms Hand"] },
      { number: 19, text: "Und Ahimaaz*, der Sohn Zadoks, sagte: Ich will doch hinlaufen und dem König die Freudenbotschaft bringen, dass der HERR ihm Recht verschafft hat vor der Gewalt* seiner Feinde.", heading: "Die Botschaft an David vom Tod Absaloms", footnotes: ["℘ Kap. 15,36", "w. heraus aus der Hand"] },
      { number: 20, text: "Aber Joab sagte zu ihm: Am heutigen Tag bist du nicht der Mann für eine Freudenbotschaft, du kannst an einem andern Tag Freudenbotschaft bringen. An diesem Tag aber sollst du keine Freudenbotschaft bringen, da ja der Sohn des Königs tot ist." },
      { number: 21, text: "Und Joab sagte zu dem Kuschiten: Geh hin, melde dem König, was du gesehen hast! Da warf sich der Kuschit vor Joab nieder und lief hin." },
      { number: 22, text: "Aber Ahimaaz, der Sohn Zadoks, fing noch einmal an und sagte zu Joab: Komme, was will, auch ich will laufen, hinter dem Kuschiten her! Joab sagte: Wozu willst du denn laufen, mein Sohn, da sich für dich keine Freudenbotschaft mehr findet?" },
      { number: 23, text: "Er aber antwortete: Komme, was will, ich laufe. Da sagte er zu ihm: Lauf! Und Ahimaaz lief den Weg durch die Ebene* des Jordan und überholte den Kuschiten.", footnotes: ["w. die Umgebung, o. den Umkreis"] },
      { number: 24, text: "Und David saß zwischen den beiden Toren. Und der Wächter* ging auf das Dach des Tores zur Mauer hin. Und er erhob seine Augen und sah: und siehe, ein Mann, der allein lief.", footnotes: ["℘ 2Kö 9,17"] },
      { number: 25, text: "Und der Wächter rief hinunter und meldete es dem König*. Der König sagte: Wenn er allein ist, so ist eine Freudenbotschaft in seinem Mund. Und als er ständig näher und näher kam,", footnotes: ["℘ Jes 21,6"] },
      { number: 26, text: "sah der Wächter einen anderen Mann laufen. Und der Wächter rief ins Tor hinein* und sagte: Siehe, noch ein Mann, der allein läuft! Der König sagte: Auch der ist ein Bote.", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: zum Torhüter, o. Toröffner"] },
      { number: 27, text: "Da sagte der Wächter: Soviel ich sehe, gleicht der Lauf des ersten dem Lauf des Ahimaaz, des Sohnes Zadoks. Da sagte der König: Das ist ein guter Mann, er kommt, um eine gute Botschaft zu melden*.", footnotes: ["℘ 1Kö 1,42"] },
      { number: 28, text: "Und Ahimaaz rief und sagte zum König: Friede*! Und er warf sich vor dem König auf sein Gesicht zur Erde nieder. Und er sagte: Gepriesen sei der HERR, dein Gott, der die Männer, die ihre Hand gegen meinen Herrn, den König, erhoben haben, in deine Hand ausgeliefert hat*!", footnotes: ["o. Heil", "℘ 1Mo 14,20"] },
      { number: 29, text: "Der König sagte: Der Junge, mein Absalom, ist doch hoffentlich unversehrt.* Ahimaaz sagte: Ich sah das große Getümmel, als Joab den Knecht des Königs und deinen Knecht fortschickte, aber ich konnte nicht erkennen, was es war.", footnotes: ["w. Heil ist dem Jungen, Absalom?"] },
      { number: 30, text: "Da sagte der König: Tritt zur Seite, stell dich hierher! Und er trat zur Seite und blieb stehen." },
      { number: 31, text: "Und siehe, da kam der Kuschit, und der Kuschit sagte: Mein Herr, der König, lasse sich Freudenbotschaft bringen! Denn der HERR hat dir heute Recht verschafft vor der Gewalt* aller, die sich gegen dich erhoben haben*.", footnotes: ["w. heraus aus der Hand", "℘ Kap. 22,49"] },
      { number: 32, text: "Der König sagte zu dem Kuschiten: Ist der Junge, mein Absalom, unversehrt*? Der Kuschit sagte: Wie dem Jungen, so möge es den Feinden meines Herrn, des Königs, ergehen und allen, die sich gegen dich zum Bösen erhoben haben*!", footnotes: ["w. Ist Heil dem Jungen, Absalom", "℘ Ri 5,31; 1Sam 25,26; Dan 4,16"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Da schrak der König zusammen, und er stieg hinauf ins Obergemach des Torgebäudes und weinte. Und so rief er im Gehen: Mein Sohn Absalom! Mein Sohn, mein Sohn Absalom! Wäre ich doch an deiner Stelle gestorben! Absalom, mein Sohn, mein Sohn*!", heading: "Davids Trauer um Absalom — Joabs Vorwürfe gegen David", footnotes: ["℘ 1Mo 37,35"] },
      { number: 2, text: "Und es wurde Joab berichtet: Siehe, der König weint und trauert um Absalom." },
      { number: 3, text: "So wurde der Sieg an diesem Tag zur Trauer für das ganze Kriegsvolk, denn das Volk hatte an jenem Tag gehört: Der König grämt sich wegen seines Sohnes." },
      { number: 4, text: "Da stahl sich das Kriegsvolk an jenem Tag davon, um in die Stadt zu kommen, wie sich Kriegsvolk davonstiehlt, das sich schämt, weil es im Kampf geflohen ist." },
      { number: 5, text: "Und der König hatte sein Gesicht verhüllt*, und der König schrie mit lauter Stimme: Mein Sohn Absalom! Absalom, mein Sohn, mein Sohn*!", footnotes: ["℘ Kap. 15,30", "℘ Kap. 18,17"] },
      { number: 6, text: "Da ging Joab zum König ins Haus hinein und sagte: Du hast heute das Gesicht all deiner Knechte schamrot gemacht, die heute dein Leben gerettet haben und das Leben deiner Söhne und deiner Töchter und das Leben deiner Frauen und das Leben deiner Nebenfrauen," },
      { number: 7, text: "indem du liebst, die dich hassen, und hasst, die dich lieben. Denn du hast heute bekundet, dass dir Oberste und Knechte nichts sind. Ja, heute erkenne ich: Wenn Absalom am Leben wäre, wir alle heute aber tot, das wäre dann recht gewesen in deinen Augen!" },
      { number: 8, text: "Nun aber mache dich auf, geh hinaus und rede zum Herzen deiner Knechte! Denn bei dem HERRN schwöre ich dir: Wenn du nicht hinausgehst, dann wird diese Nacht nicht ein Mann bei dir bleiben! Und das wäre schlimmer für dich als all das Schlimme, das über dich gekommen ist von deiner Jugend an bis jetzt." },
      { number: 9, text: "Da erhob sich der König und setzte sich ins Tor. Und man berichtete dem ganzen Kriegsvolk: Siehe, der König sitzt im Tor! Da kam das ganze Kriegsvolk vor den König.Israel aber war geflohen, jeder zu seinen Zelten*.", heading: "Davids Rückkehr", footnotes: ["℘ Kap. 18,17"] },
      { number: 10, text: "Und das ganze Volk stritt sich in allen Stämmen Israels und sagte: Der König hat uns aus der Hand unserer Feinde befreit, und er hat uns gerettet aus der Hand der Philister. Und jetzt ist er vor Absalom aus dem Land geflohen*.", footnotes: ["℘ Kap. 15,14.16"] },
      { number: 11, text: "Absalom aber, den wir über uns gesalbt hatten, ist im Kampf gestorben*. Und nun, warum schweigt ihr, anstatt den König wieder zurückzuholen?", footnotes: ["℘ Kap. 18,14.15"] },
      { number: 12, text: "Und der König David sandte zu den Priestern Zadok und Abjatar* und ließ ihnen sagen: Redet zu den Ältesten von Juda: Warum wollt ihr die Letzten sein, den König in sein Haus zurückzuholen, wo doch das Wort von ganz Israel bereits zum König in sein Haus gekommen ist?", footnotes: ["℘ Kap. 8,17"] },
      { number: 13, text: "Meine Brüder seid ihr, ihr seid mein Gebein und mein Fleisch!* Und warum wollt ihr die Letzten sein, den König zurückzuholen?", footnotes: ["℘ Kap. 5,1"] },
      { number: 14, text: "Und zu Amasa sollt ihr sagen: Bist du nicht mein Gebein und mein Fleisch?* So soll mir Gott tun und so hinzufügen*, wenn du nicht alle Tage Heeroberster vor mir sein sollst an Joabs Stelle*!", footnotes: ["℘ Kap. 5,1", "℘ Kap. 3,9.35", "℘ Kap. 17,25; 20,4"] },
      { number: 15, text: "Und er neigte das Herz aller Männer von Juda wie das eines Mannes. Und sie sandten zum König: Kehre zurück, du und alle deine Knechte!" },
      { number: 16, text: "Da kehrte der König zurück und kam bis an den Jordan, während Juda nach Gilgal* gekommen war, um dem König entgegenzugehen und den König über den Jordan zu führen.", footnotes: ["℘ 1Sam 10,8"] },
      { number: 17, text: "Da eilte Schimi, der Sohn Geras, der Benjaminiter, der von Bahurim war*, und kam mit den Männern von Juda herab dem König David entgegen:", heading: "David begnadigt Schimi", footnotes: ["℘ Kap. 3,16; 16,5"] },
      { number: 18, text: "Und tausend Mann aus Benjamin waren bei ihm, und Ziba*, der Diener des Hauses Sauls, und seine fünfzehn Söhne und seine zwanzig Knechte mit ihm*. Und sie waren, bevor der König kam, durch den Jordan gewatet*", footnotes: ["℘ V. 30; Kap. 9,2", "℘ Kap. 9,10", "w. gedrungen"] },
      { number: 19, text: "und versahen den Dienst*, das Haus des Königs hinüberzugeleiten und zu tun, was gut war in seinen Augen. Und Schimi, der Sohn des Gera, fiel vor dem König nieder, als der den Jordan überschreiten wollte.", footnotes: ["so mit LXX; Mas. T.: und der Übergang ging hinüber"] },
      { number: 20, text: "Und er sagte zum König: Mein Herr wolle mir die Schuld nicht anrechnen, und du wollest nicht länger daran denken, was dein Knecht verkehrt gemacht hat an dem Tag, als mein Herr, der König, aus Jerusalem auszog, dass der König es zu Herzen nähme!" },
      { number: 21, text: "Denn dein Knecht hat erkannt: Ich habe gesündigt*. Aber siehe, ich bin heute gekommen, als Erster vom ganzen Haus Josef, um hinabzuziehen, meinem Herrn, dem König, entgegen.", footnotes: ["℘ Kap. 16,5-8"] },
      { number: 22, text: "Da antwortete Abischai, der Sohn der Zeruja, und sagte: Sollte nicht Schimi dafür getötet werden, dass er dem Gesalbten des HERRN geflucht hat*?", footnotes: ["℘ Kap. 16,5; 1Sam 26,9"] },
      { number: 23, text: "David aber sagte: Was habe ich mit euch zu tun, ihr Söhne der Zeruja*, dass ihr mir heute zu Widersachern* werden wollt? Sollte heute ein Mann in Israel getötet werden*? Weiß ich denn nicht, dass ich heute König bin über Israel?", footnotes: ["℘ Kap. 16,10; Lk 9,55", "hebr. satan. — Das Wort steht im Hebr. in der Einzahl.", "℘ 1Sam 11,13"] },
      { number: 24, text: "Und der König sagte zu Schimi: Du sollst nicht sterben! Und der König schwor ihm*.", footnotes: ["℘ 1Kö 2,8"] },
      { number: 25, text: "Und Mefi-Boschet*, der Sohn Sauls, kam herab, dem König entgegen. Und er hatte seine Füße nicht gepflegt und seinen Bart nicht gepflegt und seine Kleider nicht gewaschen von dem Tag an, als der König weggegangen war, bis zu dem Tag, an dem er in Frieden zurückkommen würde.", heading: "Davids Begegnung mit Mefi-Boschet", footnotes: ["℘ Kap. 9,6"] },
      { number: 26, text: "Und es geschah, als er von Jerusalem dem König entgegenkam, da sagte der König zu ihm: Warum bist du nicht mit mir gezogen, Mefi-Boschet?" },
      { number: 27, text: "Er sagte: Mein Herr und König, mein Knecht hat mich betrogen! Denn dein Knecht hatte gesagt: Ich will mir den Esel satteln lassen und darauf reiten und mit dem König ziehen! — denn dein Knecht ist lahm*.", footnotes: ["℘ Kap. 9,3.13"] },
      { number: 28, text: "Er aber ist als Verleumder gegen deinen Knecht zu meinem Herrn, dem König, gelaufen*. Doch mein Herr, der König, ist wie der Engel Gottes*. So tu, was gut ist in deinen Augen!*", footnotes: ["℘ Kap. 16,3", "℘ Kap. 14,17.20", "℘ Kap. 15,26"] },
      { number: 29, text: "Denn das ganze Haus meines Vaters — das waren nichts als Männer des Todes vor meinem Herrn, dem König. Du aber hast deinen Knecht unter die gesetzt, die an deinem Tisch essen*. Was für ein Recht* habe ich da noch und welchen Anspruch, noch zum König zu schreien?", footnotes: ["℘ Kap. 9,7", "w. Was für eine Gerechtigkeit"] },
      { number: 30, text: "Da sagte der König zu ihm: Wozu redest du noch von deinen Angelegenheiten? Ich sage: Du und Ziba*, ihr sollt das Feld teilen*!", footnotes: ["℘ V. 18", "℘ Kap. 9,9"] },
      { number: 31, text: "Mefi-Boschet sagte zum König: Er mag auch das Ganze nehmen, nachdem mein Herr, der König, in Frieden in sein Haus gekommen ist!" },
      { number: 32, text: "Und Barsillai, der Gileaditer, kam von Roglim herab und ging mit dem König über den Jordan, um ihn am Jordan entlang zu geleiten*.", heading: "Davids Begegnung mit Barsillai", footnotes: ["o. am Jordan zu verabschieden; w. wegzuschicken"] },
      { number: 33, text: "Barsillai war aber sehr alt, ein Mann von achtzig Jahren. Er war es, der den König versorgt hatte, als der sich in Mahanajim aufgehalten hatte, denn er war ein sehr reicher Mann*.", footnotes: ["℘ Kap. 17,27-29; 1Tim 6,17-19"] },
      { number: 34, text: "Und der König sagte zu Barsillai: Du, geh mit mir hinüber, ich will dich bei mir in Jerusalem versorgen!" },
      { number: 35, text: "Doch Barsillai sagte zum König: Wie viel sind noch die Tage meiner Lebensjahre, dass ich mit dem König nach Jerusalem hinaufziehen sollte?" },
      { number: 36, text: "Achtzig Jahre bin ich heute alt*. Kann ich da noch zwischen Gutem und Bösem unterscheiden*? Oder kann dein Knecht schmecken, was ich esse und was ich trinke? Oder kann ich noch auf die Stimme der Sänger und der Sängerinnen hören*? Wozu sollte dein Knecht meinem Herrn, dem König, noch zur Last fallen?", footnotes: ["℘ Ps 90,10", "o. Kann ich da noch Gutes und Böses erkennen", "℘ Pred 12,1-5"] },
      { number: 37, text: "Kurz nur* kann dein Knecht mit dem König über den Jordan gehen. Und warum will der König mir diese große Vergeltung erweisen?", footnotes: ["w. Wie kurz nur"] },
      { number: 38, text: "Lass doch deinen Knecht zurückkehren, dass ich in meiner Stadt sterbe, beim Grab meines Vaters und meiner Mutter. Aber siehe, hier ist dein Knecht Kimham*! Der mag mit meinem Herrn, dem König, hinübergehen. Und tu ihm, was gut ist in deinen Augen!*", footnotes: ["℘ Jer 41,17", "℘ 1Kö 2,7"] },
      { number: 39, text: "Da sagte der König: Kimham soll mit mir hinübergehen, und ich will ihm tun, was gut ist in deinen Augen. Und alles, was du von mir begehrst*, will ich für dich tun!", footnotes: ["w. was du dir zu meinen Lasten auswählst"] },
      { number: 40, text: "Und alles Volk ging über den Jordan, und auch der König ging hinüber. Und der König küsste Barsillai und segnete ihn; und der kehrte an seinen Heimatort zurück." },
      { number: 41, text: "Und der König ging weiter nach Gilgal, und Kimham ging mit ihm hinüber. Und das ganze Volk von Juda und auch die Hälfte des Volkes von Israel führte den König hinüber." },
      { number: 42, text: "Und siehe, alle Männer von Israel kamen zum König und sagten zum König: Warum haben unsere Brüder, die Männer von Juda*, dich gestohlen und den König und sein Haus und alle Männer Davids mit ihm über den Jordan geführt?", heading: "Eifersucht von Juda und Israel auf David", footnotes: ["℘ Kap. 2,4"] },
      { number: 43, text: "Da antworteten alle Männer* von Juda den Männern* von Israel: Weil der König mir nähersteht! Warum bist du denn über diese Sache erzürnt? Haben wir vom König etwa irgendetwas aufgegessen, oder hat er uns irgendein Geschenk gemacht?", footnotes: ["Im Hebr. steht die Einzahl.", "Im Hebr. steht die Einzahl."] },
      { number: 44, text: "Aber die Männer* von Israel antworteten den Männern* von Juda und sagten: Ich habe zehn Anteile am König, und auch an David habe ich mehr Anrecht als du. Warum hast du mich verachtet? Ist nicht auch mein Wort das Erste gewesen, meinen König zurückzuholen? Aber das Wort der Männer* von Juda war härter als das Wort der Männer* von Israel*.", footnotes: ["Im Hebr. steht die Einzahl.", "Im Hebr. steht die Einzahl.", "Im Hebr. steht die Einzahl.", "Im Hebr. steht die Einzahl.", "℘ Ri 8,1; Spr 15,1"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Nun war dort zufällig* ein ruchloser Mann; sein Name war Scheba, der Sohn des Bichri, ein Benjaminiter*. Der stieß ins Horn und rief: Wir haben keinen Anteil an David! Wir haben kein Erbteil an Isais Sohn! Jeder zu seinen Zelten, Israel!*", heading: "Der Aufstand Schebas — Joabs Mord an Amasa — Schebas Tod", footnotes: ["℘ Rt 2,3", "℘ Kap. 16,11", "℘ 1Kö 12,16"] },
      { number: 2, text: "Da zogen alle Männer* von Israel von David weg und folgten Scheba nach, dem Sohn des Bichri. Die Männer von Juda aber hingen ihrem König an, vom Jordan bis Jerusalem*.", footnotes: ["Im Hebr. steht die Einzahl.", "℘ 1Kö 12,20"] },
      { number: 3, text: "Und David kam in sein Haus, nach Jerusalem. Und der König nahm die zehn Nebenfrauen, die er zurückgelassen hatte, das Haus zu hüten*, und gab sie in Gewahrsam*. Und er versorgte sie, ging aber nicht zu ihnen ein. Und sie waren eingeschlossen bis zum Tag ihres Todes — eine Witwenschaft zu Lebzeiten des Mannes.", footnotes: ["℘ Kap. 16,22", "w. in ein Haus der Bewachung"] },
      { number: 4, text: "Und der König sagte zu Amasa*: Rufe mir die Männer von Juda zusammen — drei Tage, dann stehst du hier!", footnotes: ["℘ Kap. 19,14"] },
      { number: 5, text: "Und Amasa ging hin, Juda zusammenzurufen. Aber er versäumte die bestimmte Zeit*, die er ihm bestimmt hatte.", footnotes: ["w. über die bestimmte Zeit hinaus"] },
      { number: 6, text: "Da sagte David zu Abischai: Jetzt wird Scheba, der Sohn des Bichri, für uns schlimmer sein als Absalom. Nimm du die Knechte deines Herrn und jage ihm nach, damit er nicht befestigte Städte für sich gewinnt* und uns unser Auge ausreißt*!", footnotes: ["o. erreicht", "o. unsere Quelle wegreißt; d. h. uns empfindlich schadet"] },
      { number: 7, text: "Da zogen die Männer Joabs aus, ihm nach, und die Kreter und die Pleter* und alle Helden. Und sie zogen von Jerusalem aus, um Scheba, dem Sohn des Bichri, nachzujagen.", footnotes: ["℘ V. 23; Kap. 8,18"] },
      { number: 8, text: "Als sie bei dem großen Stein waren, der bei Gibeon ist, war Amasa vor ihnen angekommen. Und Joab war mit seinem Waffenrock als seinem Gewand gegürtet, und darüber war der Gurt mit dem Schwert, das an seiner Hüfte befestigt war und in seiner Scheide steckte; trat diese hervor, fiel es heraus." },
      { number: 9, text: "Und Joab sagte zu Amasa: Geht es dir gut, mein Bruder? Und Joab fasste mit der rechten Hand Amasas Bart, um ihn zu küssen*.", footnotes: ["℘ Spr 26,23-25; 27,6; Mt 26,49"] },
      { number: 10, text: "Amasa hatte aber nicht auf das Schwert geachtet, das Joab in der anderen Hand hatte. Und er stach ihn damit in den Bauch, so dass er seine Eingeweide zur Erde schüttete; und er gab ihm keinen zweiten Stich mehr. So starb er*. Dann jagten Joab und sein Bruder Abischai Scheba, dem Sohn Bichris, weiter nach.", footnotes: ["℘ Kap. 2,23; 3,27; Ri 3,15"] },
      { number: 11, text: "Und ein Mann von den Burschen Joabs blieb bei Amasa* stehen und sagte: Wer an Joab Gefallen hat und wer für David ist, folge Joab nach!", footnotes: ["w. bei ihm"] },
      { number: 12, text: "Amasa aber wälzte sich in seinem Blut mitten auf der Straße. Und als der Mann sah, dass alles Volk stehen blieb, schaffte er Amasa von der Straße weg auf das Feld und warf ein Kleidungsstück über ihn, weil jeder, der vorbeikam, nach ihm sah und stehen blieb*.", footnotes: ["℘ Kap. 2,23"] },
      { number: 13, text: "Als er ihn von der Straße weggeschafft hatte, zog jedermann vorüber, Joab nach, um Scheba, dem Sohn Bichris, nachzujagen." },
      { number: 14, text: "Der aber zog durch alle Stämme Israels bis Abel und Bet-Maacha*, und alle Bichriter* versammelten sich und folgten ihm ebenfalls nach.", footnotes: ["Andere lesen mit Streichung eines Buchstabens: bis nach Abel-Bet-Maacha; vgl. V. 15", "T.; Wortbedeutung unbekannt"] },
      { number: 15, text: "Und sie kamen und belagerten ihn in Abel-Bet-Maacha*, und sie schütteten einen Wall gegen die Stadt auf, so dass er an die Vormauer stieß*. Und das ganze Kriegsvolk, das bei Joab war, unterwühlte die Hauptmauer, um sie zum Einsturz zu bringen.", footnotes: ["℘ 1Kö 15,20; 2Kö 15,29", "℘ Pred 9,14"] },
      { number: 16, text: "Da rief eine kluge Frau aus der Stadt: Hört her, hört her! Sagt doch zu Joab: Tritt hier heran, ich will mit dir reden!" },
      { number: 17, text: "Und er trat zu ihr heran. Und die Frau sagte: Bist du Joab? Er sagte: Ich bin es. Da sagte sie zu ihm: Höre die Worte deiner Magd! Und er sagte: Ich höre." },
      { number: 18, text: "Da sagte sie Folgendes: Früher pflegte man zu sagen: Man frage nur in Abel, und so ist man am Ziel!*", footnotes: ["w. so hatte man seine Suche beendet!; o. Man frage nur in Abel! So war man am Ziel."] },
      { number: 19, text: "Ich bin von den Friedsamen, den Getreuen Israels. Du aber trachtest danach, eine Stadt und Mutter in Israel zu töten. Warum willst du das Erbteil des HERRN* verschlingen?", footnotes: ["℘ Kap. 21,3; 5Mo 32,9; 1Sam 10,1; 1Kö 8,53; Ps 33,12; 78,71; 106,5"] },
      { number: 20, text: "Da antwortete Joab und sagte: Fern, fern sei es von mir, dass ich verschlingen und dass ich vernichten will!" },
      { number: 21, text: "So ist die Sache nicht! Vielmehr hat ein Mann vom Gebirge Ephraim, sein Name ist Scheba, der Sohn des Bichri, seine Hand gegen den König, gegen David, erhoben. Ihn allein gebt heraus, und ich ziehe von der Stadt ab! Da sagte die Frau zu Joab: Siehe, sein Kopf wird dir über die Mauer zugeworfen." },
      { number: 22, text: "Und die Frau ging zum ganzen Volk und beredete es mit ihrer Klugheit*. Da hieben sie Scheba, dem Sohn des Bichri, den Kopf ab und warfen ihn zu Joab hinaus*. Der stieß ins Horn, und sie zerstreuten sich von der Stadt weg, jeder zu seinen Zelten*. Joab aber kehrte zum König nach Jerusalem zurück.", footnotes: ["℘ Pred 7,19", "℘ Joh 11,50", "℘ Kap. 18,16.17"] },
      { number: 23, text: "*Und Joab war über das ganze Heer eingesetzt, über Israel, und Benaja, der Sohn Jojadas, über die Kreter und über die Pleter*,", heading: "Davids Beamte", footnotes: ["℘ Kap. 8,16-18; vgl. 1Kö 4,1-6", "℘ 1Kö 1,7.8"] },
      { number: 24, text: "und Adoram über die Zwangsarbeit. Und Joschafat, der Sohn Ahiluds, war Berater*,", footnotes: ["w. der Bekanntmachende"] },
      { number: 25, text: "und Scheja* war Schreiber, und Zadok und Abjatar waren Priester*,", footnotes: ["mit der Leseform: Schewa", "℘ 1Kö 1,7.8"] },
      { number: 26, text: "und auch Ira, der Jaïriter*, war Priester* Davids.", footnotes: ["℘ 5Mo 3,14", "d. i. hier viell. ein Ehrentitel"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und es gab eine Hungersnot in den Tagen Davids, drei Jahre lang, Jahr für Jahr*. Und David suchte das Angesicht des HERRN*. Und der HERR sprach: Wegen Saul und wegen des Hauses der Blutschuld*, weil er die Gibeoniter getötet hat!", heading: "Sühnung einer Schuld Sauls", footnotes: ["℘ Kap. 24,1; Rt 1,1", "℘ 1Sam 10,22; Ps 27,8", "LXX: Auf Saul und seinem Haus liegt Blutschuld"] },
      { number: 2, text: "Da rief der König die Gibeoniter herbei und redete zu ihnen. — Die Gibeoniter aber, sie waren nicht von den Söhnen Israel, sondern vom Rest der Amoriter. Und die Söhne Israel hatten ihnen geschworen*, sie zu verschonen. Saul aber hatte versucht, sie zu erschlagen in seinem Eifer für die Söhne Israel und Juda. —", footnotes: ["℘ Jos 9,15.18"] },
      { number: 3, text: "David also sagte zu den Gibeonitern: Was soll ich für euch tun? Und womit soll ich Sühne tun*, damit ihr das Erbteil des HERRN* segnet?", footnotes: ["℘ Jon 1,11", "℘ Kap. 20,19"] },
      { number: 4, text: "Und die Gibeoniter sagten zu ihm: Wir haben* kein Verlangen nach Silber und Gold von Saul und von seinem Haus, und wir haben kein Recht, jemanden in Israel zu töten. Und er sagte: Was wollt ihr denn, dass ich für euch tun soll?", footnotes: ["w. Ich habe"] },
      { number: 5, text: "Da sagten sie zum König: Der Mann, der uns vernichtet hat und der gegen uns plante, dass wir ausgerottet werden sollten, so dass wir nicht mehr hätten bestehen können im ganzen Gebiet Israels —" },
      { number: 6, text: "man gebe uns sieben Männer von seinen Söhnen, dass wir sie dem HERRN aufhängen* bei dem Gibea Sauls, des Erwählten des HERRN*. Und der König sagte: Ich will sie euch geben.", footnotes: ["o. mit gebrochenen Gliedern aussetzen; o. pfählen", "nach einigen LXX-Handschr.: aufhängen in Gibeon, auf dem Hügel des HERRN\n℘ 1Sam 10,24.26"] },
      { number: 7, text: "Aber der König hatte Mitleid mit Mefi-Boschet*, dem Sohn Jonatans, des Sohnes Sauls, wegen des Schwures bei dem HERRN, der zwischen ihnen war, zwischen David und Jonatan, dem Sohn Sauls*.", footnotes: ["℘ Kap. 9,6", "℘ 1Sam 24,22"] },
      { number: 8, text: "Und der König nahm die beiden Söhne Rizpas*, der Tochter des Aja, die sie dem Saul geboren hatte, Armoni und Mefi-Boschet, und die fünf Söhne Merabs*, der Tochter Sauls, die sie dem Adriël geboren hatte, dem Sohn des Barsillai, des Meholatiters*,", footnotes: ["℘ Kap. 3,7", "so mit 2 hebr. Handschr., einer LXX-Ausgabe und der syr. Üs.; Mas. T.: die fünf Söhne Michals", "℘ 1Sam 18,19"] },
      { number: 9, text: "und er gab sie in die Hand der Gibeoniter. Die hängten sie auf dem Berg vor dem HERRN auf*. So fielen die sieben auf einmal, und sie wurden in den ersten Tagen der Ernte, am Anfang der Gerstenernte, getötet.", footnotes: ["o. Sie pfählten sie auf dem Berg vor dem HERRN; o. Sie setzten sie mit gebrochenen Gliedern . . . aus\n℘ 4Mo 25,4; 35,33"] },
      { number: 10, text: "Da nahm Rizpa, die Tochter des Aja, das Sackgewand und breitete es für sich auf dem Felsen aus vom Anfang der Ernte an, bis das Wasser sich vom Himmel über die Toten* ergoss. Und sie ließ nicht zu, dass bei Tag die Vögel des Himmels sich auf ihnen niederließen und bei Nacht die Tiere des Feldes*.", footnotes: ["w. über sie", "℘ 5Mo 21,22.23"] },
      { number: 11, text: "Und es wurde David berichtet, was Rizpa, die Tochter des Aja, die Nebenfrau Sauls, getan hatte." },
      { number: 12, text: "Da ging David hin und holte die Gebeine Sauls und die Gebeine seines Sohnes Jonatan von den Bürgern* von Jabesch in Gilead, die sie von dem Marktplatz in Bet-Schean gestohlen hatten, wo die Philister sie an dem Tag aufgehängt hatten, als die Philister Saul am Gilboa schlugen.*", footnotes: ["w. von den Grundbesitzern", "℘ Kap. 2,4.5; 1Sam 31,10-13"] },
      { number: 13, text: "Und er brachte die Gebeine Sauls und die Gebeine seines Sohnes Jonatan von dort herauf. Dann sammelte man die Gebeine der Gehängten*", footnotes: ["o. der Gepfählten; o. der mit gebrochenen Gliedern Ausgesetzten"] },
      { number: 14, text: "und begrub sie mit den Gebeinen Sauls* und seines Sohnes Jonatan im Land Benjamin in Zela* im Grab seines Vaters Kisch. Und man tat alles, was der König befohlen hatte. Und danach ließ Gott sich für das Land erbitten*.", footnotes: ["o. begrub die Gebeine Sauls", "℘ Jos 18,28", "℘ Kap. 24,25; 4Mo 25,8; Jon 1,15"] },
      { number: 15, text: "*Wieder einmal hatten die Philister Krieg mit Israel. Und David zog hinab und seine Knechte mit ihm, und sie kämpften mit den Philistern*. Und David war ermüdet.", heading: "Siege über die Philister", footnotes: ["℘ 1Chr 20,4-8", "℘ Kap. 5,17-25; 8,1"] },
      { number: 16, text: "Und Jischbi in Nob*, der zu den Söhnen des Rafa* gehörte — das Gewicht seiner Lanzenspitze war dreihundert Schekel Bronze*, und er war mit einem neuen Schwert gegürtet —, der sagte, er wolle David erschlagen.", footnotes: ["o. Und David war ermüdet, 16 so dass sie sich in Nob niederließen; da war aber einer", "Rafa galt als Stammvater der Refaïter; das sind Riesen.\n℘ 5Mo 2,10.11; Jos 11,22", "℘ 1Sam 17,7"] },
      { number: 17, text: "Aber Abischai*, der Sohn der Zeruja, kam ihm zu Hilfe, schlug den Philister und tötete ihn. Damals schworen die Männer Davids ihm und sagten: Du sollst nicht mehr mit uns in den Kampf ausziehen, damit du die Leuchte Israels nicht auslöschst*!", footnotes: ["℘ Kap. 18,2", "℘ Kap. 18,3; 1Kö 11,36"] },
      { number: 18, text: "Und es geschah danach, da kam es wieder zum Kampf mit den Philistern bei Gob. Damals erschlug Sibbechai, der Huschatiter*, den Saf, der zu den Söhnen des Rafa* gehörte.", footnotes: ["℘ 1Chr 11,29", "Rafa galt als Stammvater der Refaïter; das sind Riesen."] },
      { number: 19, text: "Und wieder kam es bei Gob zum Kampf mit den Philistern. Und Elhanan*, der Sohn des Jaare-Oregim*, der Bethlehemiter, erschlug Goliat, den Gatiter; und der Schaft seines Speeres war wie ein Weberbaum*.", footnotes: ["℘ Kap. 23,24", "Mit Änderung lesen andere: Elhanan, der Sohn Jaïrs bzw. Isais", "℘ 1Sam 17,7"] },
      { number: 20, text: "Und wieder kam es zum Kampf bei Gat. Da war ein langer* Mann, der hatte sechs Finger an seinen Händen und sechs Zehen an seinen Füßen, 24 an der Zahl; und auch er war dem Rafa* geboren worden.", footnotes: ["so mit der aram. Üs. und 1Chr 20,6; Mas. T.: ein keifender o. streitsüchtiger", "Rafa galt als Stammvater der Refaïter; das sind Riesen."] },
      { number: 21, text: "Und er verhöhnte Israel*; da erschlug ihn Jonatan, der Sohn Schammas, des Bruders Davids*.", footnotes: ["℘ 1Sam 17,10", "℘ Kap. 13,3"] },
      { number: 22, text: "Diese vier wurden dem Rafa* in Gat geboren; und sie fielen durch die Hand Davids und durch die Hand seiner Knechte.", footnotes: ["Rafa galt als Stammvater der Refaïter; das sind Riesen."] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Und David redete zu dem HERRN die Worte dieses Liedes* an dem Tag, als der HERR ihn aus der Hand aller seiner Feinde und aus der Hand Sauls gerettet hatte*. Und er sprach:", heading: "Davids Dankpsalm", footnotes: ["℘ Ps 18", "℘ 2Mo 15,1; 5Mo 31,30; Ri 5,1", "℘ Kap. 12,7"] },
      { number: 2, text: "Der HERR ist mir mein Fels und meine Burg und mein Erretter." },
      { number: 3, text: "Mein Gott ist mein Hort*, bei dem ich Zuflucht suche, mein Schild und das Horn meines Heils, meine hohe Feste und meine Zuflucht*. Mein Retter, vor Gewalttat rettest du mich!*", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: Gott meines Horts", "℘ Ps 9,10; 46,2.8; Hebr 2,13", "℘ 2Mo 15,2"] },
      { number: 4, text: "Gelobt! rufe ich* zum HERRN, so werde ich vor meinen Feinden gerettet.*", footnotes: ["Mit anderer Vokalisierung lässt sich üs.: Lobend rufe ich; andere üs. mit Änderung eines Buchstabens: Durchbohrt rufe ich", "℘ 2Chr 20,22"] },
      { number: 5, text: "Denn mich umfingen die Wogen des Todes, Bäche des Verderbens erschreckten mich.*", footnotes: ["℘ Ps 42,8"] },
      { number: 6, text: "Fesseln des Scheols umgaben mich, Fallen des Todes überwältigten mich*.", footnotes: ["w. traten mir entgegen"] },
      { number: 7, text: "In meiner Bedrängnis rief ich zum HERRN, und ich schrie* zu meinem Gott*. Und er hörte aus seinem Tempel meine Stimme, und mein Schrei drang an seine Ohren.", footnotes: ["so mit LXX und der syr. Üs.; Mas. T.: ich rief", "℘ Ps 107,6"] },
      { number: 8, text: "Da wankte und bebte die Erde*; die Grundfesten des Himmels erzitterten und wankten*, denn er war von Zorn entbrannt.", footnotes: ["℘ Ri 5,4; Ps 77,19", "℘ Hi 26,11"] },
      { number: 9, text: "Rauch stieg auf von seiner Nase, und Feuer fraß aus seinem Mund, glühende Kohlen brannten aus ihm*.", footnotes: ["℘ 2Mo 24,17; Offb 11,5"] },
      { number: 10, text: "Er neigte den Himmel und fuhr hernieder*, und Dunkel war unter seinen Füßen.*", footnotes: ["℘ Jes 63,19", "℘ 5Mo 4,11"] },
      { number: 11, text: "Er fuhr auf einem Cherub und flog daher, so schwebte er* auf den Flügeln des Windes.", footnotes: ["so mit vielen hebr. Handschr. im Anschluss an Ps 18,11; Mas. T.: so erschien er"] },
      { number: 12, text: "Und er machte Finsternis rings um sich her zur Hütte*, das Sieb des Himmelswassers, dichtes Gewölk.", footnotes: ["w. zu Laubdächern"] },
      { number: 13, text: "Aus dem Glanz vor ihm brannten feurige Kohlen*.", footnotes: ["℘ 2Mo 24,17; Offb 11,5"] },
      { number: 14, text: "Der HERR donnerte vom Himmel her*, und der Höchste ließ seine Stimme erschallen.", footnotes: ["℘ 1Sam 7,10"] },
      { number: 15, text: "Und er schoss Pfeile und zerstreute sie, schoss seinen Blitz und verwirrte sie." },
      { number: 16, text: "Da wurden sichtbar die Betten des Meeres, die Fundamente der Welt wurden aufgedeckt durch das Schelten des HERRN, vor dem Schnauben des Hauchs seiner Nase*.", footnotes: ["℘ 2Mo 15,8"] },
      { number: 17, text: "Er griff aus der Höhe, erfasste mich, zog mich heraus aus großen Wassern." },
      { number: 18, text: "Er rettete mich vor meinem starken Feind, vor meinen Hassern, denn sie waren mächtiger als ich.*", footnotes: ["℘ Ps 35,10"] },
      { number: 19, text: "Sie überwältigten mich* am Tag meines Unglücks, aber der HERR wurde mir eine Stütze*.", footnotes: ["w. traten mir entgegen", "℘ Jes 41,10"] },
      { number: 20, text: "Und er führte mich heraus ins Weite*, er befreite mich, weil er Gefallen an mir hatte.", footnotes: ["℘ Ps 31,9"] },
      { number: 21, text: "Der HERR handelte an mir nach meiner Gerechtigkeit*, nach der Reinheit meiner Hände vergalt er mir.", footnotes: ["℘ 1Sam 26,23; 1Kö 3,6"] },
      { number: 22, text: "Denn ich habe die Wege des HERRN eingehalten und bin von meinem Gott nicht gottlos abgewichen*.", footnotes: ["w. bin nicht gottlos gewesen weg von meinem Gott\n℘ 1Kö 9,4"] },
      { number: 23, text: "Denn alle seine Rechtsbestimmungen waren vor mir, und seine Ordnungen — ich bin nicht davon abgewichen*.", footnotes: ["℘ 5Mo 17,20"] },
      { number: 24, text: "Auch war ich vollkommen* ihm gegenüber und hütete mich vor meiner Schuld.*", footnotes: ["o. rechtschaffen; o. untadelig; o. lauter", "℘ Ps 17,1-5"] },
      { number: 25, text: "So vergalt der HERR mir nach meiner Gerechtigkeit*, nach meiner Reinheit vor seinen Augen.", footnotes: ["℘ 1Sam 26,23; 1Kö 3,6"] },
      { number: 26, text: "Gegen den Gnädigen verhältst du dich gnädig, gegen den vollkommenen Mann vollkommen*.", footnotes: ["o. rechtschaffen; o. untadelig; o. lauter"] },
      { number: 27, text: "Gegen den Reinen zeigst du dich rein, gegen den Verkehrten aber verdreht.*", footnotes: ["℘ 3Mo 26,24"] },
      { number: 28, text: "Und das demütige* Volk rettest du; aber deine Augen sind gegen die Hochmütigen, du erniedrigst sie*.", footnotes: ["o. elende", "℘ Lk 1,51"] },
      { number: 29, text: "Ja, du bist meine Leuchte, HERR; und der HERR erhellt meine Finsternis*.", footnotes: ["℘ Jes 50,10; Joh 8,12"] },
      { number: 30, text: "Denn mit dir erstürme ich einen Wall*, mit meinem Gott springe ich über eine Mauer*.", footnotes: ["Andere Üs.: Mit dir renne ich gegen eine Feindesschar an, o. gehe ich auf Raubzug.", "d. h. eine Feldabgrenzung"] },
      { number: 31, text: "Gott — sein Weg ist vollkommen*; des HERRN Wort ist lauter; ein Schild ist er allen, die sich bei ihm bergen.*", footnotes: ["o. rechtschaffen; o. untadelig; o. lauter\n℘ 5Mo 32,4; Neh 9,8; Hi 34,10; Ps 92,16; 145,17; Pred 3,14; Dan 4,34; Offb 15,3", "℘ Spr 30,5"] },
      { number: 32, text: "Denn wer ist Gott außer dem HERRN?* Und wer ist ein Fels außer unserem Gott?*", footnotes: ["℘ Kap. 7,22; 5Mo 4,35.39", "℘ Kap. 23,3; 1Sam 2,2"] },
      { number: 33, text: "Gott ist meine starke Festung*, und vollkommen* macht er meinen Weg*.", footnotes: ["o. meine Zuflucht", "o. rechtschaffen; o. untadelig; o. lauter", "T.; Mas. T.: vollkommen gab er meinen Weg frei\n℘ Ps 32,8"] },
      { number: 34, text: "Er macht meine Füße den Hirschen gleich und stellt mich hin auf meine Höhen*.", footnotes: ["℘ Kap. 23,1"] },
      { number: 35, text: "Er lehrt meine Hände das Kämpfen, und meine Arme spannen den ehernen Bogen." },
      { number: 36, text: "Und du gabst mir den Schild deines Heils*, und dein Zuspruch* machte mich groß.", footnotes: ["℘ Eph 6,16.17", "w. dein Antworten, o. dein Erhören"] },
      { number: 37, text: "Du schafftest Raum meinen Schritten unter mir, und meine Knöchel haben nicht gewankt." },
      { number: 38, text: "Meinen Feinden jagte ich nach und vernichtete sie; und ich kehrte nicht um, bis ich sie aufgerieben hatte." },
      { number: 39, text: "Und ich rieb sie auf und zerschmetterte sie, dass sie nicht mehr aufstanden; und sie fielen unter meine Füße*.", footnotes: ["℘ Jos 10,24; 1Kö 5,17; Röm 16,20"] },
      { number: 40, text: "Und du umgürtetest mich mit Kraft zum Kampf, beugtest unter mich, die gegen mich aufstanden." },
      { number: 41, text: "Du hast bewirkt, dass meine Feinde mir den Rücken zeigen müssen*; meine Hasser, ich habe sie vernichtet*.", footnotes: ["w. Du hast mir den Rücken meiner Feinde gegeben", "o. brachte sie zum Schweigen"] },
      { number: 42, text: "Sie blickten umher — aber da war kein Retter — zum HERRN, doch er antwortete ihnen nicht." },
      { number: 43, text: "Und ich zermalmte sie wie Staub der Erde; wie Straßenkot zertrat, zerstampfte ich sie*.", footnotes: ["℘ Kap. 7,9; Jes 10,6; Mi 7,10"] },
      { number: 44, text: "Und du hast mich gerettet aus den Streitigkeiten meines Volkes*; du hast mich als Haupt der Nationen bewahrt; ein Volk, das ich nicht kannte, dient mir*.", footnotes: ["℘ Kap. 3,1", "℘ Jes 55,4.5"] },
      { number: 45, text: "Die Söhne der Fremde schmeichelten mir*; sowie ihr Ohr hörte, gehorchten sie mir.", footnotes: ["w. heuchelten mir Ergebung"] },
      { number: 46, text: "Die Söhne der Fremde sanken hin und zitterten hervor aus ihren Festungen*.", footnotes: ["℘ Mi 7,17"] },
      { number: 47, text: "Der HERR lebt!* Gepriesen sei mein Fels! Erhoben werde Gott, der Fels meines Heils*,", footnotes: ["℘ 5Mo 32,40", "w. der Gott des Felsens meines Heils\n℘ Ps 89,27"] },
      { number: 48, text: "der Gott, der mir Rache gab* und mir die Völker unterwarf", footnotes: ["℘ 5Mo 32,35"] },
      { number: 49, text: "und der mich herausholte von meinen Feinden weg! Und du erhöhtest mich über die, die gegen mich aufstanden; von dem Mann der Gewalttaten hast du mich befreit.*", footnotes: ["℘ Kap. 18,31"] },
      { number: 50, text: "Darum will ich dich preisen, HERR, unter den Nationen* und will spielen deinem Namen,", footnotes: ["℘ Ps 108,4; Jak 5,13"] },
      { number: 51, text: "der seinem König große Rettung schenkt* und Gnade erweist seinem Gesalbten*, David und seinen Nachkommen* ewig.*", footnotes: ["w. der groß macht die Rettungen seines Königs", "℘ Kap. 23,1.5", "w. seinem Samen", "℘ Kap. 7,12.13"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und dies sind die letzten Worte Davids: Ausspruch Davids, des Sohnes Isais*, Ausspruch des Mannes, der hochgestellt ist*, des Gesalbten des Gottes Jakobs* und des Lieblings in den Gesängen* Israels*:", heading: "Davids letzte Worte", footnotes: ["℘ 1Sam 17,12", "℘ Kap. 22,34", "℘ Kap. 22,51; Ps 89,21", "o. des Lieblichen der Gesänge; d. h. der lieblich zu singen versteht", "℘ 1Sam 18,7"] },
      { number: 2, text: "Der Geist des HERRN hat durch mich geredet, und sein Wort war auf meiner Zunge*.", footnotes: ["℘ Mt 22,43; Apg 2,30; 1Petr 4,11; 2Petr 1,21"] },
      { number: 3, text: "Es hat gesprochen der Gott Israels*, der Fels Israels hat zu mir geredet: Wer gerecht herrscht über die Menschen*, wer in der Furcht Gottes herrscht*,", footnotes: ["℘ Kap. 22,32", "℘ Kap. 8,15; Ps 72,1-4; Jer 23,5", "℘ Jes 11,2.3"] },
      { number: 4, text: "der ist wie das Licht des Morgens, wenn die Sonne aufstrahlt*, eines Morgens ohne Wolken; von ihrem Glanz nach dem Regen* sprosst das Grün aus der Erde.", footnotes: ["℘ Ri 5,31; Spr 4,18; Mal 3,20", "℘ Ps 72,6"] },
      { number: 5, text: "Ja, ist nicht so mein Haus bei* Gott*? Hat er mir doch einen ewigen Bund gesetzt*, in allem geordnet und bewahrt! Denn all mein Heil und all mein Wohlgefallen, lässt er es denn nicht sprießen?", footnotes: ["o. mit", "℘ Kap. 7,18", "℘ 1Mo 9,16; Ps 89,3-5; 111,9; Jes 55,3; Jer 33,21; Lk 1,31-33"] },
      { number: 6, text: "Aber die Verruchten sind allesamt wie Dorngestrüpp, das verweht wird; denn mit der Hand fasst man es nicht an*.", footnotes: ["℘ 1Sam 25,17; Mi 7,4"] },
      { number: 7, text: "Und der Mann, der es anfassen will, wappnet sich mit Eisen und Speerschaft; und mit Feuer wird es gründlich verbrannt an seiner Stätte*. —", footnotes: ["℘ Ps 21,10; Jes 27,4"] },
      { number: 8, text: "*Das sind die Namen der Helden*, die David hatte: Joscheb-Baschebet*, der Tachkemoniter*, das Haupt der »Drei«*; er schwang seinen Speer über* achthundert Mann, die er auf einmal erschlagen hatte*.", heading: "Davids Helden", footnotes: ["℘ 1Chr 11,10-47; 27,1-15", "℘ Kap. 10,7; 1Kö 1,8", "LXX: Jischbaal", "Andere ändern in »der Hachmoniter«, da 1Chr 11,11 überliefert: der Sohn Hachmonis", "So lesen mehrere Handschr. der LXX; Mas. T.: das Haupt des Dritten; o. der Dritten. — Der Dritte ist eine feststehende Bezeichnung für den dritten Mann auf dem Kriegswagen, einen Offizier (vgl. 1Kö 9,22).", "Die Üs. wurde an 1Chr 11,11 angeglichen; Mas. T.: er, nämlich Adino, der Ezniter kam über", "℘ Ri 15,15"] },
      { number: 9, text: "Und nach ihm kommt Eleasar, der Sohn Dodos, des Sohnes des Ahoach, unter den drei Helden bei David. Als sie unter den Philistern, die sich dort* zum Kampf versammelt hatten, einige herausforderten und als die Männer von Israel sich zurückzogen,", footnotes: ["Nach 1Chr 11,13 wird Pas Dammim gemeint sein."] },
      { number: 10, text: "da machte er sich auf und schlug auf die Philister ein, bis seine Hand müde wurde und seine Hand am Schwert kleben blieb. So schaffte der HERR an jenem Tag eine große Rettung. Das Kriegsvolk aber kehrte um, wieder hinter ihm her, nur um zu plündern*.", footnotes: ["℘ 1Sam 17,53"] },
      { number: 11, text: "Und nach ihm kommt Schamma, der Sohn des Age, der Harariter. Und die Philister sammelten sich zu einer Truppe*. Nun war dort ein Feldstück voller Linsen. Das Kriegsvolk aber floh vor den Philistern.", footnotes: ["Andere üs. mit Textänderung: sammelten sich in Lehi"] },
      { number: 12, text: "Da stellte er sich mitten auf das Stück und entriss es ihnen und schlug die Philister. So schaffte der HERR eine große Rettung." },
      { number: 13, text: "Und drei von den dreißig Helden* gingen hinab und kamen zur Erntezeit zu David, in die Höhle Adullam*. Und die Truppe der Philister lagerte in der Ebene Refaïm*.", footnotes: ["w. Häuptern", "℘ 1Sam 22,1", "℘ Kap. 5,18"] },
      { number: 14, text: "David war aber damals in der Bergfeste*, und ein Posten der Philister war damals in Bethlehem*.", footnotes: ["℘ Kap. 5,17", "℘ 1Mo 35,19"] },
      { number: 15, text: "Und David verspürte ein Verlangen und sagte: Wer gibt mir Wasser zu trinken aus der Zisterne von Bethlehem*, die im Tor ist?", footnotes: ["℘ 1Mo 35,19"] },
      { number: 16, text: "Da drangen die drei Helden in das Heerlager der Philister ein und schöpften Wasser aus der Zisterne von Bethlehem, die im Tor ist, und nahmen es mit und brachten es David. Aber er wollte es nicht trinken, sondern goss es als Trankopfer für den HERRN aus." },
      { number: 17, text: "Und er sagte: Fern sei es von mir vor dem HERRN*, dass ich das tue! Ist es nicht das Blut der Männer, die um ihr Leben hingegangen sind*? Und er wollte es nicht trinken. Das haben die drei Helden getan.", footnotes: ["so mit vielen hebr. Handschr., LXX, der aram. und syr. Üs.; Mas. T.: o HERR", "℘ Ps 72,14"] },
      { number: 18, text: "Und Abischai, der Bruder Joabs, der Sohn der Zeruja*, er war das Oberhaupt der Dreißig*. Und er schwang seinen Speer über dreihundert Erschlagenen. Er hatte einen Namen unter den Dreißig*.", footnotes: ["℘ Kap. 18,2", "so mit 2 hebr. Handschr. und der syr. Üs.; Mas. T.: der Drei", "so mit der syr. Üs.; Mas. T.: unter den Dreien"] },
      { number: 19, text: "War es nicht so, dass er mehr geehrt wurde als die Dreißig*, so dass er ihr Oberster wurde? Aber an die Drei reichte er nicht heran.", footnotes: ["Die Zahl ist an V. 23 angeglichen; Mas. T.: Drei"] },
      { number: 20, text: "Und Benaja, der Sohn Jojadas*, war ein tapferer Mann, groß an Taten, aus Kabzeel*. Der erschlug die beiden Kriegshelden* von Moab. Und er stieg hinab und erschlug den Löwen in der Zisterne an einem Schneetag.", footnotes: ["℘ Kap. 8,18", "℘ Jos 15,21", "Andere üs. mit einer Trennung des hebr. Wortes: die beiden Gotteslöwen"] },
      { number: 21, text: "Und er war es, der einen ägyptischen Mann erschlug, einen Mann von schrecklichem Aussehen*. Und der Ägypter hatte einen Speer in der Hand. Er aber ging mit einem Stock zu ihm hinab, riss dem Ägypter den Speer aus der Hand und brachte ihn mit dessen eigenem Speer um*.", footnotes: ["o. von gewaltiger Erscheinung", "℘ 1Sam 17,51"] },
      { number: 22, text: "Das tat Benaja, der Sohn Jojadas*; und er hatte einen Namen unter den dreißig* Helden.", footnotes: ["℘ Kap. 8,18", "Die Zahl ist an V. 23 angeglichen; Mas. T.: drei"] },
      { number: 23, text: "Mehr als die Dreißig wurde er geehrt, aber an die Drei reichte er nicht heran. Und David setzte ihn über seine Leibwache." },
      { number: 24, text: "Asaël*, der Bruder Joabs, war unter den Dreißig; ebenso Elhanan*, der Sohn Dodos, aus Bethlehem;", footnotes: ["℘ Kap. 2,18", "℘ Kap. 21,19"] },
      { number: 25, text: "Schamma, der Haroditer; Elika, der Haroditer*;", footnotes: ["℘ Ri 7,1"] },
      { number: 26, text: "Helez, der Peletiter*; Ira, der Sohn des Ikkesch aus Tekoa*;", footnotes: ["℘ Jos 15,27", "℘ Kap. 14,2"] },
      { number: 27, text: "Abiëser, der Anatotiter*; Mebunnai*, der Huschatiter;", footnotes: ["℘ Jos 21,18", "In 1Chr 11,29 lautet der Name »Sibbechai«."] },
      { number: 28, text: "Zalmon, der Ahoachiter*; Mahrai, der Netofatiter*;", footnotes: ["℘ 1Chr 8,4", "℘ Esr 2,22; Neh 7,26"] },
      { number: 29, text: "Heled*, der Sohn Baanas, der Netofatiter*; Ittai, der Sohn Ribais, aus dem Gibea der Söhne Benjamin*;", footnotes: ["so mit mehreren hebr. Handschr., Vulg. und 1Chr 11,30; Mas. T.: Heleb", "℘ Esr 2,22; Neh 7,26", "℘ 1Sam 13,2"] },
      { number: 30, text: "Benaja, der Piratoniter*; Hiddai, aus Nahale-Gaasch*;", footnotes: ["℘ Ri 12,13", "℘ Jos 24,30"] },
      { number: 31, text: "Abialbon, der Arbatiter*; Asmawet*, der Bahurimiter*;", footnotes: ["℘ Jos 18,22", "℘ 1Chr 12,3; 27,25", "T.; Mas. T.: Barhumiter\n℘ Kap. 16,5"] },
      { number: 32, text: "Eljachba, der Schaalboniter*; von den Söhnen des Jaschen: Jonatan;", footnotes: ["℘ Jos 19,42"] },
      { number: 33, text: "Schamma, der Harariter; Ahiam, der Sohn Scharars, der Arariter;" },
      { number: 34, text: "Elifelet, der Sohn Ahasbais, des Sohnes des Maachatiters*; Eliam*, der Sohn Ahitofels, der Giloniter*;", footnotes: ["℘ 5Mo 3,14", "℘ Kap. 11,3; 1Sam 26,6", "℘ Kap. 15,12"] },
      { number: 35, text: "Hezro, der Karmeliter*; Paarai, der Arabiter*;", footnotes: ["℘ Jos 15,55", "℘ Jos 15,52"] },
      { number: 36, text: "Jigal, der Sohn Nathans, aus Zoba*; Bani, der Gaditer;", footnotes: ["℘ Kap. 8,3"] },
      { number: 37, text: "Zelek, der Ammoniter; Nachrai, der Beerotiter*, der Waffenträger Joabs, des Sohnes der Zeruja;", footnotes: ["℘ Kap. 4,2"] },
      { number: 38, text: "Ira, der Jitriter*; Gareb, der Jitriter*;", footnotes: ["Andere lesen mit geringfügiger Änderung: der Jattiriter\n℘ 1Chr 2,53", "Andere lesen mit geringfügiger Änderung: der Jattiriter"] },
      { number: 39, text: "Uria*, der Hetiter*: im Ganzen 37.", footnotes: ["℘ 2Sam 11,3", "℘ Kap. 11,3; 1Sam 26,6"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "*Und wieder entbrannte der Zorn des HERRN gegen Israel*. Und er reizte David gegen sie auf zu sagen: Geh hin, zähle Israel und Juda!", heading: "Davids Volkszählung und deren Folgen", footnotes: ["℘ V. 1-9: 1Chr 21,1-6; 27,23.24", "℘ Kap. 21,1; Ri 2,14.20; 2Chr 32,25"] },
      { number: 2, text: "Da sagte der König zu Joab, dem Heerobersten, der bei ihm war: Zieh doch umher in allen Stämmen Israels, von Dan bis Beerscheba*! Ihr sollt das Kriegsvolk mustern, damit ich die Zahl des Volkes kenne!", footnotes: ["℘ V. 15; Kap. 3,10"] },
      { number: 3, text: "Joab aber sagte zum König: Der HERR, dein Gott, mag zu dem Volk, so viele sie auch sein mögen, noch hundertmal mehr hinzufügen*, während die Augen meines Herrn, des Königs, es sehen*! Aber mein Herr und König! Warum denn hat er Gefallen an einer solchen Sache?", footnotes: ["℘ 5Mo 1,11", "℘ Spr 14,28"] },
      { number: 4, text: "Doch das Wort des Königs blieb fest gegen Joab und gegen die Obersten des Heeres*. So zogen Joab und die Obersten des Heeres vor dem König aus, um das Volk Israel zu mustern*.", footnotes: ["℘ Pred 8,4", "℘ 2Mo 30,12"] },
      { number: 5, text: "Und sie gingen über den Jordan *und begannen bei Aroër*, bei der Stadt, die mitten im Flusstal liegt, und gingen weiter auf Gad zu und nach Jaser* hin*.", footnotes: ["So liest eine LXX-Ausgabe; Mas. T.: und lagerten bei Aroër rechts von der Stadt, die mitten im Flusstal von Gad liegt, und gingen weiter nach Jaser hin", "℘ Jos 13,25", "℘ Kap. 11,3; 1Sam 26,6", "So liest eine LXX-Ausgabe; Mas. T.: und lagerten bei Aroër rechts von der Stadt, die mitten im Flusstal von Gad liegt, und gingen weiter nach Jaser hin"] },
      { number: 6, text: "Und sie kamen nach Gilead und in das Land der Hetiter nach Kadesch*, und sie kamen nach Dan-Jaan* und in die Umgebung von Sidon*,", footnotes: ["So liest eine LXX-Ausgabe; Mas. T.: Tachtim Hodschi; das wäre ein unbekannter Ort", "℘ Jos 19,47", "℘ Jos 11,8"] },
      { number: 7, text: "und sie kamen zu der befestigten Stadt Tyrus* und zu allen Städten der Hiwiter* und der Kanaaniter, und sie zogen hinaus in den Süden von Juda nach Beerscheba*.", footnotes: ["℘ Jos 19,28.29", "℘ Jos 9,1.7", "℘ 1Mo 21,31"] },
      { number: 8, text: "Und sie zogen im ganzen Land umher und kamen am Ende von neun Monaten und zwanzig Tagen nach Jerusalem zurück." },
      { number: 9, text: "Und Joab gab dem König das Ergebnis der Musterung* an. Und zwar gab es in Israel 800 000 Wehrfähige*, die das Schwert zogen, und die Männer von Juda waren 500 000 Mann.", footnotes: ["w. die Zahl der Zählung des Volkes", "w. Männer des Krieges"] },
      { number: 10, text: "*Aber nachdem David das Volk gezählt hatte, schlug ihm das Herz*. Und David sagte zum HERRN: Ich habe sehr gesündigt mit dem, was ich getan habe*. Und nun, HERR, lass doch die Schuld deines Knechtes vorübergehen*, denn ich habe sehr töricht gehandelt!*", footnotes: ["℘ V. 10-25: 1Chr 21,7-30", "w. Aber Davids Herz schlug ihn, nachdem er das Volk gezählt hatte\n℘ 1Sam 24,6; 1Jo 3,20", "℘ Kap. 12,13; 2Mo 10,16; Ps 32,5", "℘ Hos 14,2.3; Joe 2,12-14", "℘ 4Mo 12,11; 1Sam 13,13"] },
      { number: 11, text: "Und als David am Morgen aufstand, da geschah das Wort des HERRN zu dem Propheten Gad, dem Seher Davids*, wie folgt:", footnotes: ["℘ Kap. 12,1; 1Sam 9,9; 22,5"] },
      { number: 12, text: "Geh hin und rede zu David: So spricht der HERR: Dreierlei lege ich dir vor*! Wähle dir eins davon, dass ich es dir tue*!", footnotes: ["w. auf", "℘ Jer 30,11"] },
      { number: 13, text: "Und Gad kam zu David und teilte ihm das mit und sagte zu ihm: Sollen dir sieben Jahre Hungersnot in dein Land kommen*? Oder willst du drei Monate vor deinen Bedrängern fliehen, während sie dir nachjagen? Oder soll drei Tage lang Pest in deinem Land sein? Nun überlege* und sieh zu, was für eine Antwort ich dem zurückbringen soll, der mich gesandt hat*.", footnotes: ["℘ 2Kö 8,1", "o. erkenne", "℘ 1Sam 25,17"] },
      { number: 14, text: "Und David sagte zu Gad: Mir ist sehr angst! Lass uns doch in die Hand des HERRN fallen, denn seine Erbarmungen sind groß*! Aber in die Hand der Menschen lass mich nicht fallen*!", footnotes: ["℘ 2Mo 34,6.7; Kla 3,22; Dan 9,9; Mi 7,19", "℘ Ps 106,41"] },
      { number: 15, text: "Da gab der HERR die Pest in Israel, vom Morgen an bis zu der bestimmten Zeit. Und es starben von dem Volk, von Dan bis Beerscheba*, 70 000 Mann*.", footnotes: ["℘ V. 2", "℘ 4Mo 25,9; 1Chr 27,24"] },
      { number: 16, text: "Und als der Engel seine Hand über Jerusalem ausstreckte, um es zu vernichten, da hatte der HERR Mitleid wegen des Unheils*, und er sprach zu dem Engel, der unter dem Volk vernichtete: Genug! Ziehe jetzt deine Hand ab*! Der Engel des HERRN war aber gerade bei der Tenne Araunas, des Jebusiters*.", footnotes: ["℘ 2Mo 32,14; Ps 78,38; Jer 42,10", "℘ Jes 57,16", "℘ 2Chr 3,1; Sach 9,7"] },
      { number: 17, text: "Und als David den Engel sah, der das Volk schlug, sprach er zu dem HERRN und sagte: Siehe, ich habe gesündigt, und ich habe verkehrt gehandelt*! Aber diese Schafe*, was haben sie getan*? Lass doch deine Hand gegen mich* und gegen das Haus meines Vaters sein!", footnotes: ["℘ Kap. 12,13; 2Mo 10,16; Ps 32,5", "℘ Ps 78,71", "℘ 1Mo 18,23", "℘ 1Mo 44,33; 4Mo 16,22; Jon 1,12"] },
      { number: 18, text: "Und Gad kam zu David an jenem Tag und sagte zu ihm: Geh hinauf, errichte dem HERRN einen Altar auf der Tenne des Jebusiters Arauna*.", footnotes: ["℘ 2Chr 3,1; Sach 9,7"] },
      { number: 19, text: "Da ging David hinauf nach dem Wort Gads, ganz wie der HERR geboten hatte." },
      { number: 20, text: "Und Arauna blickte hinaus und sah den König und seine Knechte zu sich herüberkommen. Da ging Arauna hinaus und warf sich vor dem König nieder, mit seinem Gesicht zur Erde." },
      { number: 21, text: "Und Arauna sagte: Weshalb kommt mein Herr, der König, zu seinem Knecht? David sagte: Um die Tenne von dir zu kaufen, um auf ihr dem HERRN einen Altar zu bauen, damit die Plage vom Volk abgewehrt wird!" },
      { number: 22, text: "Da sagte Arauna zu David: Mein Herr, der König, nehme und opfere, was gut ist in seinen Augen! Siehe, da sind die Rinder zum Brandopfer und die Dreschschlitten und die Geschirre der Rinder zum Brennholz*.", footnotes: ["℘ Ri 6,26; 1Kö 19,21"] },
      { number: 23, text: "Das alles, König, gibt Arauna dem König. Und Arauna sagte weiter zum König: Der HERR, dein Gott, nehme dich wohlgefällig an*!", footnotes: ["℘ Ps 20,4.5"] },
      { number: 24, text: "Aber der König sagte zu Arauna: Nein, sondern kaufen will ich es von dir für den Kaufpreis. Ich will dem HERRN, meinem Gott, nicht umsonst Brandopfer opfern. So kaufte David die Tenne und die Rinder für fünfzig Schekel Silber*.", footnotes: ["℘ 1Mo 23,11-16"] },
      { number: 25, text: "Und David baute dort dem HERRN einen Altar* und opferte Brandopfer und Heilsopfer*. Da ließ der HERR sich für das Land erbitten*, und die Plage wurde von Israel abgewehrt*.", footnotes: ["℘ 1Mo 12,7.8; Ri 6,24", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ Ri 21,4", "℘ Kap. 21,14", "℘ 4Mo 17,13"] },
    ]},
  ]
};
